import {b, type ReviewedLesson} from './types';
const reviewed: Record<string,ReviewedLesson> = {
  'm2-w044-e1': {
    title:b('Dominated limit and escaping mass','Giới hạn bị chặn và khối lượng thoát'),
    application:b(String.raw`On $(0,1)$, compare a sequence with a fixed integrable envelope; a moving spike shows why pointwise convergence alone does not control integrals.`,String.raw`Trên $(0,1)$, so sánh dãy với một hàm bao khả tích cố định; đỉnh nhọn dịch chuyển cho thấy vì sao hội tụ điểm đơn thuần không kiểm soát tích phân.`),
    formula:b(String.raw`On a measure space, if $f_n\to f$ a.e. and $|f_n|\le g$ a.e. for one $g\in L^1$, then $\int f_n\,d\mu\to\int f\,d\mu$. On $(0,1)$, $x^n\le1$ and $\int_0^1x^n\,dx=1/(n+1)$.`,String.raw`Trên không gian đo, nếu $f_n\to f$ h.k.n. và $|f_n|\le g$ h.k.n. với một $g\in L^1$, thì $\int f_n\,d\mu\to\int f\,d\mu$. Trên $(0,1)$, $x^n\le1$ và $\int_0^1x^n\,dx=1/(n+1)$.`),
    steps:[b(String.raw`For $0<x<1$, powers $x^n\to0$; the endpoint is a Lebesgue-null exception.`,String.raw`Với $0<x<1$, lũy thừa $x^n\to0$; đầu mút là ngoại lệ có độ đo Lebesgue bằng không.`),b(String.raw`The common envelope $g(x)=1$ is integrable on $(0,1)$, so DCT applies.`,String.raw`Hàm bao chung $g(x)=1$ khả tích trên $(0,1)$, nên áp dụng DCT.`),b(String.raw`Direct integration gives $\int_0^1x^n\,dx=[x^{n+1}/(n+1)]_0^1=1/(n+1)\to0$.`,String.raw`Tích phân trực tiếp cho $\int_0^1x^n\,dx=[x^{n+1}/(n+1)]_0^1=1/(n+1)\to0$.`),b(String.raw`The spike $s_n=n1_{(0,1/n)}$ also tends to zero at every fixed $x>0$, yet $\int_0^1s_n\,dx=1$; it has no common integrable dominator.`,String.raw`Đỉnh nhọn $s_n=n1_{(0,1/n)}$ cũng tiến về không tại mọi $x>0$ cố định, nhưng $\int_0^1s_n\,dx=1$; nó không có hàm trội khả tích chung.`)],
    primarySolution:[b(String.raw`For almost every $x\in(0,1)$, $x^n\to0$, and $|x^n|\le1$ with $\int_0^11\,dx=1$.`,String.raw`Với hầu hết $x\in(0,1)$, $x^n\to0$, và $|x^n|\le1$ với $\int_0^11\,dx=1$.`),b(String.raw`DCT therefore gives convergence of the integrals to the integral of the pointwise limit, zero.`,String.raw`Vì vậy DCT cho tích phân hội tụ về tích phân của giới hạn điểm, bằng không.`),b(String.raw`Indeed, $\int_0^1x^n\,dx=1/(n+1)\to0$.`,String.raw`Thật vậy, $\int_0^1x^n\,dx=1/(n+1)\to0$.`),b(String.raw`For $s_n=n1_{(0,1/n)}$, each fixed $x>0$ eventually lies outside its support, so $s_n(x)\to0$ while its integral is $n(1/n)=1$.`,String.raw`Với $s_n=n1_{(0,1/n)}$, mỗi $x>0$ cố định cuối cùng nằm ngoài giá đỡ nên $s_n(x)\to0$, còn tích phân bằng $n(1/n)=1$.`),b(String.raw`The missing DCT premise is one integrable function dominating every $s_n$; a.e. convergence alone is insufficient.`,String.raw`Giả thiết DCT thiếu là một hàm khả tích trội mọi $s_n$; hội tụ h.k.n. đơn thuần chưa đủ.`)],
    companions:[
      {prompt:b(String.raw`On $[0,1]$, let $u_n(x)=(1-x)^n$. Prove its integral tends to zero using DCT and compute it exactly.`,String.raw`Trên $[0,1]$, cho $u_n(x)=(1-x)^n$. Dùng DCT chứng minh tích phân tiến về không và tính chính xác tích phân.`),solution:[b(String.raw`For $x>0$, $(1-x)^n\to0$; the exception at zero is null.`,String.raw`Với $x>0$, $(1-x)^n\to0$; ngoại lệ tại không là tập không.`),b(String.raw`Since $0\le u_n\le1$ and the constant 1 is integrable on $[0,1]$, DCT applies.`,String.raw`Vì $0\le u_n\le1$ và hàm hằng 1 khả tích trên $[0,1]$, DCT áp dụng được.`),b(String.raw`Integration gives $\int_0^1(1-x)^n dx=1/(n+1)\to0$.`,String.raw`Tính tích phân được $\int_0^1(1-x)^n dx=1/(n+1)\to0$.`)]},
      {prompt:b(String.raw`On $(0,\infty)$, set $v_n(x)=n^2xe^{-nx}$. Show $v_n\to0$ pointwise but its integral stays positive.`,String.raw`Trên $(0,\infty)$, đặt $v_n(x)=n^2xe^{-nx}$. Chứng minh $v_n\to0$ từng điểm nhưng tích phân vẫn dương.`),solution:[b(String.raw`For fixed $x>0$, exponential decay dominates the polynomial factor, so $n^2xe^{-nx}\to0$.`,String.raw`Với $x>0$ cố định, suy giảm mũ nhanh hơn thừa số đa thức nên $n^2xe^{-nx}\to0$.`),b(String.raw`Substitute $y=nx$: $\int_0^\infty n^2xe^{-nx}dx=\int_0^\infty ye^{-y}dy$.`,String.raw`Đổi biến $y=nx$: $\int_0^\infty n^2xe^{-nx}dx=\int_0^\infty ye^{-y}dy$.`),b(String.raw`Integration by parts gives $\int_0^\infty ye^{-y}dy=1$, not the zero integral of the limit.`,String.raw`Tích phân từng phần cho $\int_0^\infty ye^{-y}dy=1$, khác tích phân bằng không của giới hạn.`)]},
      {prompt:b(String.raw`On $[0,1]$, let $w_n(x)=(1+nx)^{-2}$. Find its a.e. limit, a common integrable bound, and integral.`,String.raw`Trên $[0,1]$, cho $w_n(x)=(1+nx)^{-2}$. Tìm giới hạn h.k.n., hàm chặn khả tích chung và tích phân.`),solution:[b(String.raw`For each $x>0$, $w_n(x)\to0$; its value at $x=0$ does not affect the a.e. limit.`,String.raw`Với mỗi $x>0$, $w_n(x)\to0$; giá trị tại $x=0$ không ảnh hưởng giới hạn h.k.n.`),b(String.raw`The inequality $0\le w_n(x)\le1$ gives the integrable common bound 1.`,String.raw`Bất đẳng thức $0\le w_n(x)\le1$ cho hàm chặn chung khả tích 1.`),b(String.raw`An antiderivative yields $\int_0^1(1+nx)^{-2}dx=n^{-1}(1-(1+n)^{-1})=1/(n+1)\to0$.`,String.raw`Nguyên hàm cho $\int_0^1(1+nx)^{-2}dx=n^{-1}(1-(1+n)^{-1})=1/(n+1)\to0$.`)]}
    ],
    reviewNote:`DCT requires a.e. convergence and one integrable dominator. The primary spike has integral one and no such dominator; companions check both dominated convergence and escaping mass.`,
    sourceIds:['p-mit6436']
  },

  'm2-w044-e2': {
    title:b('Tower and uniqueness of conditional expectation','Tính tháp và duy nhất kỳ vọng có điều kiện'),
    application:b(String.raw`For nested information $\mathcal H\subseteq\mathcal G$, test the proposed $\mathcal H$-conditional expectation on every event in $\mathcal H$; equality holds only up to null sets.`,String.raw`Với thông tin lồng nhau $\mathcal H\subseteq\mathcal G$, kiểm tra kỳ vọng có điều kiện $\mathcal H$ được đề xuất trên mọi biến cố trong $\mathcal H$; đẳng thức chỉ đúng ngoài tập không.`),
    formula:b(String.raw`If $\mathcal H\subseteq\mathcal G$ and $X\in L^1$, then $\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]=\mathbb E[X\mid\mathcal H]$ a.s. Conditional expectation is characterized by measurability and $\mathbb E[1_AX]$ for every conditioning event $A$.`,String.raw`Nếu $\mathcal H\subseteq\mathcal G$ và $X\in L^1$, thì $\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]=\mathbb E[X\mid\mathcal H]$ h.c. Kỳ vọng có điều kiện được đặc trưng bởi tính đo được và $\mathbb E[1_AX]$ với mọi biến cố $A$ trong sigma-field điều kiện.`),
    steps:[b(String.raw`Take any $A\in\mathcal H$. Nesting gives $A\in\mathcal G$, so $\mathbb E[1_A\mathbb E[X\mid\mathcal G]]=\mathbb E[1_AX]$.`,String.raw`Lấy $A\in\mathcal H$ bất kỳ. Tính lồng nhau cho $A\in\mathcal G$, nên $\mathbb E[1_A\mathbb E[X\mid\mathcal G]]=\mathbb E[1_AX]$.`),b(String.raw`The outer defining identity gives $\mathbb E[1_A\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]]=\mathbb E[1_A\mathbb E[X\mid\mathcal G]]$.`,String.raw`Định nghĩa ngoài cho $\mathbb E[1_A\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]]=\mathbb E[1_A\mathbb E[X\mid\mathcal G]]$.`),b(String.raw`Thus both candidates have tested integral $\mathbb E[1_AX]$ for every $A\in\mathcal H$.`,String.raw`Vì vậy hai ứng viên có tích phân thử bằng $\mathbb E[1_AX]$ với mọi $A\in\mathcal H$.`),b(String.raw`The iterated conditional expectation is $\mathcal H$-measurable and integrable; uniqueness gives equality with $\mathbb E[X\mid\mathcal H]$ almost surely.`,String.raw`Kỳ vọng có điều kiện lặp lại là $\mathcal H$-đo được và khả tích; tính duy nhất cho đẳng thức với $\mathbb E[X\mid\mathcal H]$ hầu chắc chắn.`)],
    primarySolution:[b(String.raw`Set $Y=\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]$. It is $\mathcal H$-measurable and integrable since $X\in L^1$.`,String.raw`Đặt $Y=\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]$. Biến này $\mathcal H$-đo được và khả tích vì $X\in L^1$.`),b(String.raw`For any $A\in\mathcal H\subseteq\mathcal G$, the outer identity gives $\mathbb E[1_AY]=\mathbb E[1_A\mathbb E[X\mid\mathcal G]]$.`,String.raw`Với mọi $A\in\mathcal H\subseteq\mathcal G$, đồng nhất thức ngoài cho $\mathbb E[1_AY]=\mathbb E[1_A\mathbb E[X\mid\mathcal G]]$.`),b(String.raw`The inner identity changes the right side to $\mathbb E[1_AX]$, which is the defining integral for $\mathbb E[X\mid\mathcal H]$.`,String.raw`Đồng nhất thức trong biến vế phải thành $\mathbb E[1_AX]$, là tích phân định nghĩa $\mathbb E[X\mid\mathcal H]$.`),b(String.raw`Both $\mathcal H$-measurable candidates satisfy all tests, so uniqueness yields $Y=\mathbb E[X\mid\mathcal H]$ a.s.; versions may differ on null sets.`,String.raw`Cả hai ứng viên $\mathcal H$-đo được đều thỏa mọi phép thử, nên tính duy nhất cho $Y=\mathbb E[X\mid\mathcal H]$ h.c.; các phiên bản có thể khác trên tập không.`)],
    companions:[
      {prompt:b(String.raw`On four equally likely outcomes $HH,HT,TH,TT$, let $X$ indicate that toss 2 is heads. Let $\mathcal G$ reveal toss 1 and $\mathcal H$ be trivial. Compute both sides of the tower identity.`,String.raw`Trên bốn kết quả đồng xác suất $HH,HT,TH,TT$, cho $X$ chỉ báo lần tung 2 ra ngửa. Cho $\mathcal G$ tiết lộ lần tung 1 và $\mathcal H$ tầm thường. Tính hai vế đồng nhất thức tháp.`),solution:[b(String.raw`Given either first-toss outcome, toss 2 remains fair, so $\mathbb E[X\mid\mathcal G]=1/2$ on every outcome.`,String.raw`Với mỗi kết quả lần tung đầu, lần tung 2 vẫn công bằng, nên $\mathbb E[X\mid\mathcal G]=1/2$ trên mọi kết quả.`),b(String.raw`Conditioning this constant on trivial $\mathcal H$ leaves $\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]=1/2$.`,String.raw`Điều kiện hóa hằng số này theo $\mathcal H$ tầm thường vẫn cho $\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]=1/2$.`),b(String.raw`The unconditional probability of heads on toss 2 is $2/4=1/2$, hence $\mathbb E[X\mid\mathcal H]=\mathbb E[X]=1/2$.`,String.raw`Xác suất vô điều kiện lần tung 2 ra ngửa là $2/4=1/2$, nên $\mathbb E[X\mid\mathcal H]=\mathbb E[X]=1/2$.`)]},
      {prompt:b(String.raw`Let $\Omega=\{a,b,c,d\}$ be uniform, $\mathcal H=\sigma(\{a,b\},\{c,d\})$, and $\mathcal G$ reveal the outcome. For $X=(2,0,4,8)$ in that order, compute the tower values.`,String.raw`Cho $\Omega=\{a,b,c,d\}$ đều, $\mathcal H=\sigma(\{a,b\},\{c,d\})$, còn $\mathcal G$ tiết lộ kết quả. Với $X=(2,0,4,8)$ theo thứ tự đó, tính các giá trị tháp.`),solution:[b(String.raw`Since $\mathcal G$ reveals the outcome, $\mathbb E[X\mid\mathcal G]=(2,0,4,8)$.`,String.raw`Vì $\mathcal G$ tiết lộ kết quả, $\mathbb E[X\mid\mathcal G]=(2,0,4,8)$.`),b(String.raw`On $\{a,b\}$ the conditional average is $(2+0)/2=1$; on $\{c,d\}$ it is $(4+8)/2=6$.`,String.raw`Trên $\{a,b\}$, trung bình có điều kiện là $(2+0)/2=1$; trên $\{c,d\}$ là $(4+8)/2=6$.`),b(String.raw`Therefore $\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]=(1,1,6,6)=\mathbb E[X\mid\mathcal H]$.`,String.raw`Do đó $\mathbb E[\mathbb E[X\mid\mathcal G]\mid\mathcal H]=(1,1,6,6)=\mathbb E[X\mid\mathcal H]$.`)]},
      {prompt:b(String.raw`On $[0,1]$ with Lebesgue probability, let $\mathcal H$ split the interval into $[0,1/2)$ and $[1/2,1]$, and set $X(x)=x$. Find $\mathbb E[X\mid\mathcal H]$ and explain why changing its value at $x=0$ is allowed.`,String.raw`Trên $[0,1]$ với xác suất Lebesgue, cho $\mathcal H$ chia khoảng thành $[0,1/2)$ và $[1/2,1]$, đặt $X(x)=x$. Tìm $\mathbb E[X\mid\mathcal H]$ và giải thích vì sao có thể đổi giá trị tại $x=0$.`),solution:[b(String.raw`On the first atom, the mean is $(1/(1/2))\int_0^{1/2}x\,dx=1/4$.`,String.raw`Trên nguyên tử thứ nhất, trung bình là $(1/(1/2))\int_0^{1/2}x\,dx=1/4$.`),b(String.raw`On the second atom, it is $(1/(1/2))\int_{1/2}^1x\,dx=3/4$, giving the two-valued conditional expectation.`,String.raw`Trên nguyên tử thứ hai, giá trị là $(1/(1/2))\int_{1/2}^1x\,dx=3/4$, cho kỳ vọng có điều kiện nhận hai giá trị.`),b(String.raw`The singleton $\{0\}$ has probability zero, so changing the function there changes neither its a.s. equivalence class nor any tested integral over an H-event.`,String.raw`Tập đơn $\{0\}$ có xác suất không, nên đổi hàm tại đó không đổi lớp tương đương h.c. hay tích phân thử trên biến cố H nào.`)]}
    ],
    reviewNote:`Nesting lets both defining integral identities apply to the same H-events. Uniqueness is almost sure; changing a version on a null set preserves validity.`,
    sourceIds:['p-mit6436']
  },

  'm2-w044-e3': {
    title:b('Distinguish WLLN from SLLN','Phân biệt WLLN với SLLN'),
    application:b(String.raw`Chebyshev controls deviation probability at each sample size; the iid strong law controls almost every infinite path under a first-moment condition.`,String.raw`Chebyshev kiểm soát xác suất sai lệch tại từng cỡ mẫu; luật mạnh iid kiểm soát hầu hết đường đi vô hạn dưới điều kiện moment bậc nhất.`),
    formula:b(String.raw`For iid $X_i$ with $\mathbb E X_i=\mu$ and $\operatorname{Var}(X_i)=\sigma^2<\infty$, $\operatorname{Var}(\bar X_n)=\sigma^2/n$ and $P(|\bar X_n-\mu|>\varepsilon)\le\sigma^2/(n\varepsilon^2)\to0$ (WLLN). The iid SLLN needs only $\mathbb E|X_1|<\infty$ and yields $\bar X_n\to\mu$ a.s.`,String.raw`Với $X_i$ iid, $\mathbb E X_i=\mu$ và $\operatorname{Var}(X_i)=\sigma^2<\infty$, $\operatorname{Var}(\bar X_n)=\sigma^2/n$ và $P(|\bar X_n-\mu|>\varepsilon)\le\sigma^2/(n\varepsilon^2)\to0$ (WLLN). SLLN iid chỉ cần $\mathbb E|X_1|<\infty$ và cho $\bar X_n\to\mu$ h.c.`),
    steps:[b(String.raw`Linearity gives $\mathbb E\bar X_n=\mu$; independence makes cross-covariances zero and yields $\operatorname{Var}(\bar X_n)=\sigma^2/n$.`,String.raw`Tính tuyến tính cho $\mathbb E\bar X_n=\mu$; độc lập làm hiệp phương sai chéo bằng không và cho $\operatorname{Var}(\bar X_n)=\sigma^2/n$.`),b(String.raw`Chebyshev gives $P(|\bar X_n-\mu|>\varepsilon)\le\sigma^2/(n\varepsilon^2)$ for every fixed $\varepsilon>0$.`,String.raw`Chebyshev cho $P(|\bar X_n-\mu|>\varepsilon)\le\sigma^2/(n\varepsilon^2)$ với mọi $\varepsilon>0$ cố định.`),b(String.raw`The bound tending to zero proves convergence in probability; it is not by itself an almost-sure path statement.`,String.raw`Chặn tiến về không chứng minh hội tụ xác suất; tự nó không phải phát biểu theo đường đi hầu chắc.`),b(String.raw`The iid SLLN is separate: finite first absolute moment suffices, even when variance is infinite.`,String.raw`SLLN iid là định lý riêng: moment tuyệt đối bậc nhất hữu hạn là đủ, kể cả phương sai vô hạn.`)],
    primarySolution:[b(String.raw`Under iid finite variance, independence yields $\operatorname{Var}(\bar X_n)=n\sigma^2/n^2=\sigma^2/n$ and $\mathbb E\bar X_n=\mu$.`,String.raw`Với iid phương sai hữu hạn, độc lập cho $\operatorname{Var}(\bar X_n)=n\sigma^2/n^2=\sigma^2/n$ và $\mathbb E\bar X_n=\mu$.`),b(String.raw`Chebyshev gives $P(|\bar X_n-\mu|>\varepsilon)\le\sigma^2/(n\varepsilon^2)\to0$, proving the WLLN.`,String.raw`Chebyshev cho $P(|\bar X_n-\mu|>\varepsilon)\le\sigma^2/(n\varepsilon^2)\to0$, chứng minh WLLN.`),b(String.raw`The iid SLLN separately states $\bar X_n\to\mu$ almost surely under $\mathbb E|X_1|<\infty$; finite variance is unnecessary for that theorem.`,String.raw`SLLN iid riêng biệt khẳng định $\bar X_n\to\mu$ hầu chắc dưới điều kiện $\mathbb E|X_1|<\infty$; định lý đó không cần phương sai hữu hạn.`),b(String.raw`Chebyshev controls each n, not infinitely many deviations on one path. Its $1/n$ probability bound is not summable, so this proof alone does not give an almost-sure conclusion.`,String.raw`Chebyshev kiểm soát từng n, không kiểm soát vô hạn sai lệch trên một đường đi. Chặn xác suất $1/n$ không có tổng hữu hạn, nên riêng chứng minh này không cho kết luận hầu chắc.`)],
    companions:[
      {prompt:b(String.raw`Let iid $X_i$ take values $-2$ and $1$ with probabilities $1/3$ and $2/3$. Find $\mu,\sigma^2$ and a Chebyshev bound for $P(|\bar X_n-\mu|>1/2)$; state the SLLN mode.`,String.raw`Cho $X_i$ iid nhận $-2$ và $1$ với xác suất $1/3$ và $2/3$. Tìm $\mu,\sigma^2$ và chặn Chebyshev cho $P(|\bar X_n-\mu|>1/2)$; nêu kiểu hội tụ SLLN.`),solution:[b(String.raw`The mean is $(-2)/3+2/3=0$.`,String.raw`Trung bình là $(-2)/3+2/3=0$.`),b(String.raw`The second moment is $4/3+2/3=2$, hence the variance is 2.`,String.raw`Moment bậc hai là $4/3+2/3=2$, nên phương sai bằng 2.`),b(String.raw`Then $\operatorname{Var}(\bar X_n)=2/n$ and Chebyshev gives $(2/n)/(1/2)^2=8/n$.`,String.raw`Khi đó $\operatorname{Var}(\bar X_n)=2/n$ và Chebyshev cho $(2/n)/(1/2)^2=8/n$.`),b(String.raw`Finite support gives $\mathbb E|X_i|<\infty$, so the iid SLLN also yields $\bar X_n\to0$ almost surely; this finite-n bound is a WLLN estimate.`,String.raw`Giá đỡ hữu hạn cho $\mathbb E|X_i|<\infty$, nên SLLN iid cũng cho $\bar X_n\to0$ h.c.; chặn n hữu hạn này là ước lượng WLLN.`)]},
      {prompt:b(String.raw`Let iid positive integer-valued $Y_i$ satisfy $P(Y_i=k)=c/k^3$ for $k\ge1$, with c the normalizer. Show the first moment is finite but variance infinite, then state the SLLN conclusion.`,String.raw`Cho $Y_i$ iid nguyên dương với $P(Y_i=k)=c/k^3$ cho $k\ge1$, trong đó c là hệ số chuẩn hóa. Chứng minh moment bậc nhất hữu hạn nhưng phương sai vô hạn, rồi nêu kết luận SLLN.`),solution:[b(String.raw`The normalizer is $c=1/\zeta(3)$, and $\mathbb E Y_i=c\sum_{k\ge1}k^{-2}=c\zeta(2)<\infty$.`,String.raw`Hệ số chuẩn hóa là $c=1/\zeta(3)$, và $\mathbb E Y_i=c\sum_{k\ge1}k^{-2}=c\zeta(2)<\infty$.`),b(String.raw`But $\mathbb E Y_i^2=c\sum_{k\ge1}k^{-1}=\infty$, so the variance is infinite.`,String.raw`Nhưng $\mathbb E Y_i^2=c\sum_{k\ge1}k^{-1}=\infty$, nên phương sai vô hạn.`),b(String.raw`Integrability still permits the iid SLLN: $\bar Y_n\to c\zeta(2)$ a.s. The finite-variance Chebyshev proof does not apply to this law.`,String.raw`Tính khả tích vẫn cho phép dùng SLLN iid: $\bar Y_n\to c\zeta(2)$ h.c. Chứng minh Chebyshev phương sai hữu hạn không áp dụng cho luật này.`)]},
      {prompt:b(String.raw`Let $Z$ be Rademacher with equal probabilities at $-1,1$, and set $X_i=Z$ for every i. Compute $\bar X_n$ and explain why this is not an iid WLLN counterexample.`,String.raw`Cho $Z$ là Rademacher với xác suất bằng nhau tại $-1,1$, rồi đặt $X_i=Z$ với mọi i. Tính $\bar X_n$ và giải thích vì sao đây không phải phản ví dụ iid cho WLLN.`),solution:[b(String.raw`All observations equal Z, so $\bar X_n=Z$ for every n.`,String.raw`Mọi quan sát đều bằng Z, nên $\bar X_n=Z$ với mọi n.`),b(String.raw`Thus $P(|\bar X_n-0|>1/2)=1$ at every n, and convergence in probability to the mean zero fails.`,String.raw`Vì vậy $P(|\bar X_n-0|>1/2)=1$ với mọi n, và hội tụ xác suất về trung bình không thất bại.`),b(String.raw`The variables are perfectly dependent, not iid; the independence premise of the WLLN is missing.`,String.raw`Các biến phụ thuộc hoàn hảo, không iid; thiếu giả thiết độc lập của WLLN.`)]}
    ],
    reviewNote:`Chebyshev proves convergence in probability under iid finite variance; the iid SLLN needs only finite first absolute moment. The dependent Rademacher sequence shows why independence cannot be dropped.`,
    sourceIds:['p-mit6436']
  },

  'm2-w044-e4': {
    title:b('Finite-chain invariant law and mixing','Luật bất biến và trộn chuỗi hữu hạn'),
    application:b(String.raw`Solve the stationary equations, verify a common rowwise minorization, and then apply its geometric contraction in total variation.`,String.raw`Giải phương trình dừng, kiểm tra minorization chung theo từng hàng, rồi áp dụng hệ số co hình học theo total variation.`),
    formula:b(String.raw`For $P=\begin{pmatrix}.8&.2\\.3&.7\end{pmatrix}$, $\pi=(.6,.4)$ is invariant. If every row has $P(i,\cdot)\ge\varepsilon\nu(\cdot)$ for one probability $\nu$ and $0<\varepsilon\le1$, then $\|\mu P^n-\pi\|_{\rm TV}\le(1-\varepsilon)^n\|\mu-\pi\|_{\rm TV}$ for invariant $\pi$.`,String.raw`Với $P=\begin{pmatrix}.8&.2\\.3&.7\end{pmatrix}$, $\pi=(.6,.4)$ bất biến. Nếu mọi hàng có $P(i,\cdot)\ge\varepsilon\nu(\cdot)$ với một xác suất $\nu$ và $0<\varepsilon\le1$, thì $\|\mu P^n-\pi\|_{\rm TV}\le(1-\varepsilon)^n\|\mu-\pi\|_{\rm TV}$ với $\pi$ bất biến.`),
    steps:[b(String.raw`Set $\pi=(a,1-a)$ and solve $a=.8a+.3(1-a)$; this gives $.5a=.3$, hence $a=.6$.`,String.raw`Đặt $\pi=(a,1-a)$ và giải $a=.8a+.3(1-a)$; được $.5a=.3$, nên $a=.6$.`),b(String.raw`Thus $\pi=(.6,.4)$, and multiplication verifies $\pi P=(.48+.12,.12+.28)=(.6,.4)$.`,String.raw`Vậy $\pi=(.6,.4)$, và phép nhân xác nhận $\pi P=(.48+.12,.12+.28)=(.6,.4)$.`),b(String.raw`Each row dominates $.5\pi=(.3,.2)$; subtracting this vector leaves rows $(.5,0)$ and $(0,.5)$.`,String.raw`Mỗi hàng trội $.5\pi=(.3,.2)$; trừ véc-tơ này để lại các hàng $(.5,0)$ và $(0,.5)$.`),b(String.raw`Divide the residual rows by $.5$ to obtain the stochastic kernel $Q=I$, so $P=.5\Pi+.5Q$ where both rows of $\Pi$ equal $\pi$.`,String.raw`Chia hàng phần dư cho $.5$ được hạt nhân xác suất $Q=I$, nên $P=.5\Pi+.5Q$ với cả hai hàng của $\Pi$ bằng $\pi$.`),b(String.raw`The shared component contracts total variation by at most $.5$ each step; iteration gives the stated geometric bound for every initial law $\mu$.`,String.raw`Thành phần chung co total variation nhiều nhất $.5$ mỗi bước; lặp lại cho chặn hình học đã nêu với mọi luật đầu $\mu$.`)],
    primarySolution:[b(String.raw`Solving $\pi_1=.8\pi_1+.3\pi_2$ with $\pi_1+\pi_2=1$ gives $\pi=(.6,.4)$.`,String.raw`Giải $\pi_1=.8\pi_1+.3\pi_2$ cùng $\pi_1+\pi_2=1$ cho $\pi=(.6,.4)$.`),b(String.raw`The rows $(.8,.2)$ and $(.3,.7)$ both dominate $.5\pi=(.3,.2)$ coordinatewise.`,String.raw`Hai hàng $(.8,.2)$ và $(.3,.7)$ đều trội $.5\pi=(.3,.2)$ theo từng tọa độ.`),b(String.raw`Their residuals divided by $.5$ are $(1,0)$ and $(0,1)$, so they form a stochastic residual matrix.`,String.raw`Phần dư chia cho $.5$ lần lượt là $(1,0)$ và $(0,1)$, nên tạo thành ma trận phần dư xác suất.`),b(String.raw`The minorization contraction gives $\|\mu P^n-\pi\|_{\rm TV}\le(1-.5)^n\|\mu-\pi\|_{\rm TV}=2^{-n}\|\mu-\pi\|_{\rm TV}$.`,String.raw`Định lý co từ minorization cho $\|\mu P^n-\pi\|_{\rm TV}\le(1-.5)^n\|\mu-\pi\|_{\rm TV}=2^{-n}\|\mu-\pi\|_{\rm TV}$.`),b(String.raw`This is an upper bound, not a claim of equality for every n.`,String.raw`Đây là chặn trên, không khẳng định bằng nhau với mọi n.`)],
    companions:[
      {prompt:b(String.raw`For $P=\begin{pmatrix}.7&.3\\.2&.8\end{pmatrix}$, find the invariant distribution and verify minorization $\varepsilon=.5$ using it as $\nu$.`,String.raw`Với $P=\begin{pmatrix}.7&.3\\.2&.8\end{pmatrix}$, tìm phân phối bất biến và kiểm tra minorization $\varepsilon=.5$ bằng chính nó làm $\nu$.`),solution:[b(String.raw`Writing $\pi=(a,1-a)$, the equation $a=.7a+.2(1-a)$ gives $.5a=.2$, hence $\pi=(.4,.6)$.`,String.raw`Viết $\pi=(a,1-a)$, phương trình $a=.7a+.2(1-a)$ cho $.5a=.2$, nên $\pi=(.4,.6)$.`),b(String.raw`The common component is $.5\pi=(.2,.3)$. The row $(.7,.3)$ dominates it coordinatewise.`,String.raw`Thành phần chung là $.5\pi=(.2,.3)$. Hàng $(.7,.3)$ trội véc-tơ này theo từng tọa độ.`),b(String.raw`The other row $(.2,.8)$ also dominates it; residuals $(.5,0)$ and $(0,.5)$ divided by $.5$ are probability rows.`,String.raw`Hàng còn lại $(.2,.8)$ cũng trội; phần dư $(.5,0)$ và $(0,.5)$ chia $.5$ là các hàng xác suất.`),b(String.raw`Thus $\|\mu P^n-\pi\|_{\rm TV}\le2^{-n}\|\mu-\pi\|_{\rm TV}$.`,String.raw`Vậy $\|\mu P^n-\pi\|_{\rm TV}\le2^{-n}\|\mu-\pi\|_{\rm TV}$.`)]},
      {prompt:b(String.raw`For $P=\begin{pmatrix}.9&.1\\.4&.6\end{pmatrix}$, find $\pi$ and bound $\|\mu P^3-\pi\|_{\rm TV}$ using $\varepsilon=.4$.`,String.raw`Với $P=\begin{pmatrix}.9&.1\\.4&.6\end{pmatrix}$, tìm $\pi$ và chặn $\|\mu P^3-\pi\|_{\rm TV}$ bằng $\varepsilon=.4$.`),solution:[b(String.raw`The balance equation $a=.9a+.4(1-a)$ gives $.5a=.4$, so $\pi=(.8,.2)$.`,String.raw`Phương trình cân bằng $a=.9a+.4(1-a)$ cho $.5a=.4$, nên $\pi=(.8,.2)$.`),b(String.raw`Here $.4\pi=(.32,.08)$; both rows $(.9,.1)$ and $(.4,.6)$ dominate it, so the minorization is valid.`,String.raw`Ở đây $.4\pi=(.32,.08)$; cả hai hàng $(.9,.1)$ và $(.4,.6)$ đều trội, nên minorization hợp lệ.`),b(String.raw`The contraction factor is $.6$. After three steps $\|\mu P^3-\pi\|_{\rm TV}\le.6^3\|\mu-\pi\|_{\rm TV}=.216\|\mu-\pi\|_{\rm TV}$.`,String.raw`Hệ số co là $.6$. Sau ba bước $\|\mu P^3-\pi\|_{\rm TV}\le.6^3\|\mu-\pi\|_{\rm TV}=.216\|\mu-\pi\|_{\rm TV}$.`)]},
      {prompt:b(String.raw`A chain has $P=\begin{pmatrix}.75&.25\\.25&.75\end{pmatrix}$ and starts at state 1. Find $\pi$, a minorization constant, and the two-step TV bound.`,String.raw`Chuỗi có $P=\begin{pmatrix}.75&.25\\.25&.75\end{pmatrix}$ và bắt đầu ở trạng thái 1. Tìm $\pi$, hằng số minorization và chặn TV sau hai bước.`),solution:[b(String.raw`The matrix is doubly stochastic, so $\pi=(.5,.5)$; multiplication confirms $\pi P=\pi$.`,String.raw`Ma trận song ngẫu nhiên nên $\pi=(.5,.5)$; phép nhân xác nhận $\pi P=\pi$.`),b(String.raw`Each row dominates $.5\pi=(.25,.25)$, giving $\varepsilon=.5$ and residual rows $(1,0)$ and $(0,1)$.`,String.raw`Mỗi hàng trội $.5\pi=(.25,.25)$, cho $\varepsilon=.5$ và các hàng phần dư $(1,0)$, $(0,1)$.`),b(String.raw`The initial law $\delta_1$ has TV distance $.5$ from $\pi$; thus $\|\delta_1P^2-\pi\|_{\rm TV}\le(.5)^2(.5)=.125$.`,String.raw`Luật đầu $\delta_1$ cách $\pi$ một khoảng TV bằng $.5$; do đó $\|\delta_1P^2-\pi\|_{\rm TV}\le(.5)^2(.5)=.125$.`)]}
    ],
    reviewNote:`The invariant distributions were checked by multiplication. Each stated rowwise lower bound leaves nonnegative residual rows of total mass one after division by epsilon, so the TV contraction hypotheses hold.`,
    sourceIds:['p-mit6436']
  },

  'm2-w044-e5': {
    title:b('Bounded versus unbounded stopping','Dừng bị chặn và không bị chặn'),
    application:b(String.raw`For bounded stopping, expand into finitely many increments whose inclusion events are known before the increment. An unbounded hitting time requires an additional justification.`,String.raw`Với thời điểm dừng bị chặn, khai triển thành hữu hạn gia số có biến cố được biết trước gia số. Thời điểm chạm không bị chặn cần biện minh bổ sung.`),
    formula:b(String.raw`If $(M_k,\mathcal F_k)_{k=0}^N$ is an integrable martingale and $\tau\le N$ is a stopping time, then $\mathbb E M_\tau=\mathbb E M_0$, since $M_\tau=M_0+\sum_{k=1}^N1_{\{\tau\ge k\}}(M_k-M_{k-1})$. The deterministic bound is essential to this finite-sum argument; unbounded stopping needs extra conditions.`,String.raw`Nếu $(M_k,\mathcal F_k)_{k=0}^N$ là martingale khả tích và $\tau\le N$ là thời điểm dừng, thì $\mathbb E M_\tau=\mathbb E M_0$, vì $M_\tau=M_0+\sum_{k=1}^N1_{\{\tau\ge k\}}(M_k-M_{k-1})$. Chặn xác định thiết yếu cho lập luận tổng hữu hạn này; dừng không bị chặn cần điều kiện bổ sung.`),
    steps:[b(String.raw`The stopping-time property gives $\{\tau\ge k\}=\{\tau>k-1\}\in\mathcal F_{k-1}$.`,String.raw`Tính chất thời điểm dừng cho $\{\tau\ge k\}=\{\tau>k-1\}\in\mathcal F_{k-1}$.`),b(String.raw`Condition on $\mathcal F_{k-1}$: the indicator is measurable there, while $\mathbb E[M_k-M_{k-1}\mid\mathcal F_{k-1}]=0$.`,String.raw`Điều kiện hóa theo $\mathcal F_{k-1}$: chỉ báo đo được tại đó, còn $\mathbb E[M_k-M_{k-1}\mid\mathcal F_{k-1}]=0$.`),b(String.raw`So every stopped increment has expectation zero; summing only $N$ terms proves $\mathbb E M_\tau=\mathbb E M_0$.`,String.raw`Vì vậy mọi gia số dừng có kỳ vọng bằng không; cộng đúng $N$ số hạng chứng minh $\mathbb E M_\tau=\mathbb E M_0$.`),b(String.raw`For a fair simple random walk, the first hit of $+1$ is finite a.s. and its stopped value equals 1, while the starting mean is zero.`,String.raw`Với bước đi ngẫu nhiên đối xứng, lần đầu chạm $+1$ hữu hạn h.c. và giá trị dừng bằng 1, trong khi trung bình ban đầu bằng không.`),b(String.raw`That hitting time is unbounded, so the bounded theorem does not apply. In fact, stopped walks need not converge in $L^1$; a.s. finiteness alone is not enough.`,String.raw`Thời điểm chạm đó không bị chặn nên định lý bị chặn không áp dụng. Thật vậy, bước đi dừng không nhất thiết hội tụ trong $L^1$; chỉ hữu hạn h.c. là chưa đủ.`)],
    primarySolution:[b(String.raw`Expand $M_\tau=M_0+\sum_{k=1}^N1_{\{\tau\ge k\}}(M_k-M_{k-1})$, valid because $\tau\le N$.`,String.raw`Khai triển $M_\tau=M_0+\sum_{k=1}^N1_{\{\tau\ge k\}}(M_k-M_{k-1})$, hợp lệ vì $\tau\le N$.`),b(String.raw`For each k, $\{\tau\ge k\}\in\mathcal F_{k-1}$, so conditioning on $\mathcal F_{k-1}$ makes the expected kth stopped increment zero.`,String.raw`Với mỗi k, $\{\tau\ge k\}\in\mathcal F_{k-1}$, nên điều kiện hóa theo $\mathcal F_{k-1}$ làm kỳ vọng gia số dừng thứ k bằng không.`),b(String.raw`There are finitely many terms, hence $\mathbb E M_\tau=\mathbb E M_0$.`,String.raw`Có hữu hạn số hạng, do đó $\mathbb E M_\tau=\mathbb E M_0$.`),b(String.raw`For the symmetric walk's first hit of $+1$, $\tau<\infty$ a.s. but has no deterministic finite bound, and $M_\tau=1$ while $\mathbb E M_0=0$.`,String.raw`Với lần đầu bước đi đối xứng chạm $+1$, $\tau<\infty$ h.c. nhưng không có chặn hữu hạn xác định, và $M_\tau=1$ trong khi $\mathbb E M_0=0$.`),b(String.raw`The stopping time fails the theorem's boundedness premise; an unbounded optional-stopping result would need separate hypotheses such as uniform integrability.`,String.raw`Thời điểm dừng thiếu giả thiết bị chặn của định lý; kết quả dừng tùy chọn cho thời điểm không bị chặn cần giả thiết riêng như khả tích đồng đều.`)],
    companions:[
      {prompt:b(String.raw`Let $M_k=\sum_{i=1}^k(X_i-1/2)$ for independent Bernoulli$(1/2)$ tosses, and stop at $\tau=\min\{k\ge1:X_k=1\}\wedge3$. Compute $\mathbb E M_\tau$ using stopped increments.`,String.raw`Cho $M_k=\sum_{i=1}^k(X_i-1/2)$ với các lần tung Bernoulli$(1/2)$ độc lập, và dừng tại $\tau=\min\{k\ge1:X_k=1\}\wedge3$. Tính $\mathbb E M_\tau$ bằng gia số dừng.`),solution:[b(String.raw`Because $\tau\le3$, $M_\tau=\sum_{k=1}^3 1_{\{\tau\ge k\}}(X_k-1/2)$.`,String.raw`Vì $\tau\le3$, $M_\tau=\sum_{k=1}^3 1_{\{\tau\ge k\}}(X_k-1/2)$.`),b(String.raw`The first expected increment is $\mathbb E(X_1-1/2)=0$.`,String.raw`Kỳ vọng gia số đầu là $\mathbb E(X_1-1/2)=0$.`),b(String.raw`For k=2, $\{\tau\ge2\}=\{X_1=0\}$ is known before toss 2, so independence gives expected product zero.`,String.raw`Với k=2, $\{\tau\ge2\}=\{X_1=0\}$ đã biết trước lần tung 2, nên độc lập cho tích có kỳ vọng bằng không.`),b(String.raw`For k=3, $\{\tau\ge3\}=\{X_1=X_2=0\}$ is known before toss 3; the centered third toss again contributes expectation zero. Thus $\mathbb E M_\tau=0$.`,String.raw`Với k=3, $\{\tau\ge3\}=\{X_1=X_2=0\}$ đã biết trước lần tung 3; lần tung thứ ba đã tâm hóa cũng đóng góp kỳ vọng không. Vậy $\mathbb E M_\tau=0$.`)]},
      {prompt:b(String.raw`A simple symmetric walk starts at 0 and stops at its first hit of either $-2$ or $+2$. Compute the exit probabilities and mean, then justify the unbounded-time expectation.`,String.raw`Bước đi đối xứng bắt đầu ở 0 và dừng khi lần đầu chạm $-2$ hoặc $+2$. Tính xác suất thoát và trung bình, rồi biện minh kỳ vọng tại thời gian không bị chặn.`),solution:[b(String.raw`By symmetry, $P(S_\tau=2)=P(S_\tau=-2)=1/2$.`,String.raw`Theo đối xứng, $P(S_\tau=2)=P(S_\tau=-2)=1/2$.`),b(String.raw`Therefore $\mathbb E S_\tau=2(1/2)-2(1/2)=0$.`,String.raw`Do đó $\mathbb E S_\tau=2(1/2)-2(1/2)=0$.`),b(String.raw`The exit time is a.s. finite and $|S_{n\wedge\tau}|\le2$ for all n. Since $\mathbb E S_{n\wedge\tau}=0$, dominated convergence gives $\mathbb E S_\tau=0$ despite unbounded $\tau$.`,String.raw`Thời gian thoát hữu hạn h.c. và $|S_{n\wedge\tau}|\le2$ với mọi n. Vì $\mathbb E S_{n\wedge\tau}=0$, hội tụ bị chặn cho $\mathbb E S_\tau=0$ dù $\tau$ không bị chặn.`)]},
      {prompt:b(String.raw`A symmetric walk from 0 stops at the first hit of $+2$ or $-3$. Find the upper-hit probability and expected stopped position; explain the needed limit justification.`,String.raw`Bước đi đối xứng từ 0 dừng khi lần đầu chạm $+2$ hoặc $-3$. Tìm xác suất chạm trên và vị trí dừng kỳ vọng; giải thích biện minh giới hạn cần thiết.`),solution:[b(String.raw`The gambler's-ruin hitting probability is linear between the boundaries: shifting $[-3,2]$ to $[0,5]$ gives start 3 and upper endpoint 5, so $P(S_\tau=2)=3/5$.`,String.raw`Xác suất chạm biên trên là hàm tuyến tính giữa hai biên: tịnh tiến $[-3,2]$ thành $[0,5]$ cho điểm đầu 3 và biên trên 5, nên $P(S_\tau=2)=3/5$.`),b(String.raw`The lower endpoint is reached with probability $2/5$, hence $\mathbb E S_\tau=2(3/5)-3(2/5)=0$.`,String.raw`Biên dưới được chạm với xác suất $2/5$, nên $\mathbb E S_\tau=2(3/5)-3(2/5)=0$.`),b(String.raw`The stopped walk always lies in $[-3,2]$, so $|S_{n\wedge\tau}|\le3$. Dominated convergence transfers the bounded-time mean zero to $\mathbb E S_\tau$.`,String.raw`Bước đi dừng luôn nằm trong $[-3,2]$, nên $|S_{n\wedge\tau}|\le3$. Hội tụ bị chặn chuyển kỳ vọng không của thời gian bị chặn sang $\mathbb E S_\tau$.`)]}
    ],
    reviewNote:`The bounded proof relies on predictable inclusion events and a finite sum. The primary first-hit time is a.s. finite but unbounded; the companions distinguish this from cases where bounded stopped values justify a limit by dominated convergence.`,
    sourceIds:['p-mit6436']
  },

  'm2-w045-e1': {
    title:b('Check identifiability in a Bernoulli model','Kiểm tra tính nhận dạng mô hình Bernoulli'),
    application:b(String.raw`Identifiability asks whether distinct parameter values can induce exactly the same probability law; inspect an observable event whose probability equals the parameter.`,String.raw`Tính nhận dạng hỏi liệu hai giá trị tham số khác nhau có thể sinh cùng luật xác suất hay không; xét biến cố quan sát được có xác suất đúng bằng tham số.`),
    formula:b(String.raw`A parameterization $\{P_\theta:\theta\in\Theta\}$ is identifiable when $P_\theta=P_\eta$ implies $\theta=\eta$. For $X\sim\operatorname{Bernoulli}(\theta)$, $\theta\in[0,1]$, $P_\theta(X=1)=\theta$; for $\eta\in[-1,1]$ mapped to $\operatorname{Bernoulli}(\eta^2)$, signs are not distinguished.`,String.raw`Tham số hóa $\{P_\theta:\theta\in\Theta\}$ nhận dạng được nếu $P_\theta=P_\eta$ suy ra $\theta=\eta$. Với $X\sim\operatorname{Bernoulli}(\theta)$, $\theta\in[0,1]$, $P_\theta(X=1)=\theta$; với $\eta\in[-1,1]$ ánh xạ tới $\operatorname{Bernoulli}(\eta^2)$, dấu không được phân biệt.`),
    steps:[b(String.raw`The law of a Bernoulli variable assigns mass $\theta$ to the event $\{1\}$.`,String.raw`Luật của biến Bernoulli gán khối lượng $\theta$ cho biến cố $\{1\}$.`),b(String.raw`If $P_\theta=P_{\theta'}$, then their probabilities of this same event agree: $\theta=P_\theta(X=1)=P_{\theta'}(X=1)=\theta'$.`,String.raw`Nếu $P_\theta=P_{\theta'}$, xác suất của cùng biến cố bằng nhau: $\theta=P_\theta(X=1)=P_{\theta'}(X=1)=\theta'$.`),b(String.raw`Thus the Bernoulli family indexed directly by $\theta\in[0,1]$ is identifiable, including its endpoints.`,String.raw`Vì vậy họ Bernoulli được đánh chỉ số trực tiếp bởi $\theta\in[0,1]$ nhận dạng được, kể cả hai đầu mút.`),b(String.raw`In the second parameterization, $\eta=.4$ and $\eta'=-.4$ both produce success probability $.16$, hence the same law despite distinct parameters.`,String.raw`Trong tham số hóa thứ hai, $\eta=.4$ và $\eta'=-.4$ cùng cho xác suất thành công $.16$, nên sinh cùng luật dù hai tham số khác nhau.`)],
    primarySolution:[b(String.raw`For the direct model, observe that $P_\theta(X=1)=\theta$.`,String.raw`Với mô hình trực tiếp, ta có $P_\theta(X=1)=\theta$.`),b(String.raw`Equality $P_\theta=P_{\theta'}$ forces equality of probabilities of $\{1\}$, so $\theta=\theta'$.`,String.raw`Đẳng thức $P_\theta=P_{\theta'}$ buộc xác suất của $\{1\}$ bằng nhau, nên $\theta=\theta'$.`),b(String.raw`Therefore $\theta\in[0,1]$ is identifiable.`,String.raw`Vì vậy $\theta\in[0,1]$ nhận dạng được.`),b(String.raw`For the map $\eta\mapsto\operatorname{Bernoulli}(\eta^2)$ on $[-1,1]$, any pair $\eta,-\eta$ with $\eta\ne0$ is distinct but gives the same law; for example both $\pm1/2$ give success probability $1/4$.`,String.raw`Với ánh xạ $\eta\mapsto\operatorname{Bernoulli}(\eta^2)$ trên $[-1,1]$, cặp $\eta,-\eta$ khác nhau khi $\eta\ne0$ nhưng cho cùng luật; chẳng hạn $\pm1/2$ đều cho xác suất thành công $1/4$.`)],
    companions:[
      {prompt:b(String.raw`A Poisson model has parameter $\lambda>0$. Show its law identifies $\lambda$ using the probability of zero.`,String.raw`Mô hình Poisson có tham số $\lambda>0$. Dùng xác suất bằng không để chứng minh luật nhận dạng $\lambda$.`),solution:[b(String.raw`For $X\sim\operatorname{Poisson}(\lambda)$, $P_\lambda(X=0)=e^{-\lambda}$.`,String.raw`Với $X\sim\operatorname{Poisson}(\lambda)$, $P_\lambda(X=0)=e^{-\lambda}$.`),b(String.raw`The map $\lambda\mapsto e^{-\lambda}$ is strictly decreasing on $(0,\infty)$.`,String.raw`Hàm $\lambda\mapsto e^{-\lambda}$ giảm nghiêm ngặt trên $(0,\infty)$.`),b(String.raw`If two Poisson laws agree, their zero probabilities agree, and injectivity yields $\lambda=\lambda'$.`,String.raw`Nếu hai luật Poisson bằng nhau, xác suất zero bằng nhau; tính đơn ánh suy ra $\lambda=\lambda'$.`)]},
      {prompt:b(String.raw`For $X\sim N(\mu,4)$ with parameter $\mu\in\mathbb R$, prove that the model is identifiable from its law.`,String.raw`Với $X\sim N(\mu,4)$ và tham số $\mu\in\mathbb R$, chứng minh mô hình nhận dạng được từ luật.`),solution:[b(String.raw`A normal law $N(\mu,4)$ has finite mean $\mathbb E_\mu X=\mu$.`,String.raw`Luật chuẩn $N(\mu,4)$ có kỳ vọng hữu hạn $\mathbb E_\mu X=\mu$.`),b(String.raw`Equal probability laws have equal expectations whenever the expectation exists, so $P_\mu=P_{\mu'}$ implies $\mu=\mu'$.`,String.raw`Hai luật xác suất bằng nhau có kỳ vọng bằng nhau khi kỳ vọng tồn tại, nên $P_\mu=P_{\mu'}$ suy ra $\mu=\mu'$.`),b(String.raw`The mean parameterization is therefore identifiable; the fixed variance $4$ does not create ambiguity.`,String.raw`Do đó tham số hóa theo trung bình nhận dạng được; phương sai cố định $4$ không gây nhập nhằng.`)]},
      {prompt:b(String.raw`Consider $X\sim N(\eta^2,1)$ indexed by $\eta\in[-2,2]$. Decide whether this parameterization is identifiable and exhibit two parameter values if not.`,String.raw`Xét $X\sim N(\eta^2,1)$ với $\eta\in[-2,2]$. Xác định tham số hóa có nhận dạng được không và nêu hai giá trị nếu không.`),solution:[b(String.raw`The distribution depends on $\eta$ only through its mean $\eta^2$.`,String.raw`Phân phối chỉ phụ thuộc $\eta$ qua trung bình $\eta^2$.`),b(String.raw`For example, $\eta=1$ and $\eta'=-1$ both give the law $N(1,1)$.`,String.raw`Chẳng hạn, $\eta=1$ và $\eta'=-1$ đều cho luật $N(1,1)$.`),b(String.raw`Since these distinct parameters induce identical laws, this model indexed by the full interval is not identifiable.`,String.raw`Vì hai tham số khác nhau sinh luật giống nhau, mô hình đánh chỉ số trên cả khoảng không nhận dạng được.`)]}
    ],
    reviewNote:`Identifiability is injectivity of the map from parameter to probability law. The Bernoulli endpoints are identifiable; the signed-square map fails for every nonzero sign pair.`,
    sourceIds:['p-mit18655']
  },

  'm2-w045-e2': {
    title:b('Prove sufficiency factorization on finite support','Chứng minh phân tích nhân tử đủ trên hỗ trợ hữu hạn'),
    application:b(String.raw`On a finite common sample support, sufficiency is equivalent to the conditional distribution within each statistic fiber being parameter-free.`,String.raw`Trên hỗ trợ mẫu hữu hạn chung, tính đủ tương đương phân phối có điều kiện bên trong mỗi thớ của thống kê không phụ thuộc tham số.`),
    formula:b(String.raw`For finite $\mathcal X$ with common support, $T$ is sufficient iff $f_\theta(x)=g_\theta(T(x))h(x)$ for nonnegative factors. Equivalently, for every fiber $T=t$ with $P_\theta(T=t)>0$, $P_\theta(X=x\mid T=t)$ is independent of $\theta$; zero-probability fibers impose no conditional-law requirement.`,String.raw`Với $\mathcal X$ hữu hạn có hỗ trợ chung, $T$ đủ khi và chỉ khi $f_\theta(x)=g_\theta(T(x))h(x)$ với các thừa số không âm. Tương đương, trên mỗi thớ $T=t$ có $P_\theta(T=t)>0$, $P_\theta(X=x\mid T=t)$ không phụ thuộc $\theta$; thớ xác suất không không đòi luật điều kiện.`),
    steps:[b(String.raw`Assume first a factorization $f_\theta(x)=g_\theta(t)h(x)$ on the fiber $T(x)=t$.`,String.raw`Trước hết giả sử có phân tích $f_\theta(x)=g_\theta(t)h(x)$ trên thớ $T(x)=t$.`),b(String.raw`For a positive-probability fiber, summing over it gives $P_\theta(T=t)=g_\theta(t)\sum_{y:T(y)=t}h(y)$.`,String.raw`Với thớ có xác suất dương, cộng trên thớ cho $P_\theta(T=t)=g_\theta(t)\sum_{y:T(y)=t}h(y)$.`),b(String.raw`Divide the point mass by this fiber probability: $P_\theta(X=x\mid T=t)=h(x)/\sum_{y:T(y)=t}h(y)$, which contains no $\theta$.`,String.raw`Chia khối lượng điểm cho xác suất thớ: $P_\theta(X=x\mid T=t)=h(x)/\sum_{y:T(y)=t}h(y)$, không chứa $\theta$.`),b(String.raw`Conversely, if this conditional law is a fixed $q(x\mid t)$, write $f_\theta(x)=P_\theta(T=t)q(x\mid t)$; choose $g_\theta(t)=P_\theta(T=t)$ and $h(x)=q(x\mid T(x))$.`,String.raw`Ngược lại, nếu luật điều kiện là $q(x\mid t)$ cố định, viết $f_\theta(x)=P_\theta(T=t)q(x\mid t)$; chọn $g_\theta(t)=P_\theta(T=t)$ và $h(x)=q(x\mid T(x))$.`),b(String.raw`The common support lets the same points and fibers be compared across parameter values; conditionals are asserted only where the fiber has positive probability.`,String.raw`Hỗ trợ chung cho phép so sánh cùng điểm và thớ qua các tham số; luật điều kiện chỉ được khẳng định khi thớ có xác suất dương.`)],
    primarySolution:[b(String.raw`Suppose $T$ is sufficient, so on each positive-probability fiber its conditional law $q(x\mid t)$ does not depend on $\theta$.`,String.raw`Giả sử $T$ đủ, nên trên mỗi thớ xác suất dương, luật điều kiện $q(x\mid t)$ không phụ thuộc $\theta$.`),b(String.raw`Factor the joint point mass as $f_\theta(x)=P_\theta(T=t)P_\theta(X=x\mid T=t)$.`,String.raw`Phân tích khối lượng điểm thành $f_\theta(x)=P_\theta(T=t)P_\theta(X=x\mid T=t)$.`),b(String.raw`Set $g_\theta(t)=P_\theta(T=t)$ and $h(x)=q(x\mid T(x))$; this yields the required factorization, with zero-probability points contributing zero.`,String.raw`Đặt $g_\theta(t)=P_\theta(T=t)$ và $h(x)=q(x\mid T(x))$; ta được phân tích cần tìm, còn điểm xác suất không đóng góp số không.`),b(String.raw`Conversely, if $f_\theta(x)=g_\theta(T(x))h(x)$, summing over a positive-mass fiber cancels $g_\theta(t)$ and leaves a conditional probability proportional only to $h(x)$.`,String.raw`Ngược lại, nếu $f_\theta(x)=g_\theta(T(x))h(x)$, cộng trên thớ có khối lượng dương rồi rút gọn $g_\theta(t)$ cho xác suất điều kiện chỉ tỷ lệ với $h(x)$.`),b(String.raw`Thus the conditional law given $T$ is parameter-free. Common support ensures comparable sample points; no claim is needed for fibers of probability zero.`,String.raw`Vậy luật có điều kiện khi biết $T$ không phụ thuộc tham số. Hỗ trợ chung bảo đảm so sánh được các điểm mẫu; không cần khẳng định trên thớ xác suất không.`)],
    companions:[
      {prompt:b(String.raw`A categorical observation has probabilities $P_\theta(R)=\theta/2$, $P_\theta(B)=\theta/2$, and $P_\theta(G)=1-\theta$ for $0<\theta<1$. Let $T=1_{\{R,B\}}$. Show sufficiency by conditional probabilities and factorization.`,String.raw`Một quan sát phân loại có xác suất $P_\theta(R)=\theta/2$, $P_\theta(B)=\theta/2$, $P_\theta(G)=1-\theta$ với $0<\theta<1$. Cho $T=1_{\{R,B\}}$. Dùng xác suất điều kiện và phân tích nhân tử chứng minh tính đủ.`),solution:[b(String.raw`For $T=1$, the only outcomes are R and B, each with probability $\theta/2$, so each conditional probability is $1/2$.`,String.raw`Khi $T=1$, kết quả chỉ có R và B, mỗi kết quả có xác suất $\theta/2$, nên xác suất điều kiện đều bằng $1/2$.`),b(String.raw`For $T=0$, the outcome is certainly G, so its conditional probability is 1. Both conditional laws are parameter-free.`,String.raw`Khi $T=0$, kết quả chắc chắn là G, nên xác suất điều kiện bằng 1. Cả hai luật điều kiện đều không phụ thuộc tham số.`),b(String.raw`Explicitly, $g_\theta(1)=\theta$, $g_\theta(0)=1-\theta$, and $h(R)=h(B)=1/2,h(G)=1$ give $f_\theta(x)=g_\theta(T(x))h(x)$.`,String.raw`Cụ thể, $g_\theta(1)=\theta$, $g_\theta(0)=1-\theta$, $h(R)=h(B)=1/2,h(G)=1$ cho $f_\theta(x)=g_\theta(T(x))h(x)$.`)]},
      {prompt:b(String.raw`On $\mathcal X=\{A,B,C\}$, set $P_\theta(A)=\theta^2$, $P_\theta(B)=\theta(1-\theta)$, $P_\theta(C)=1-\theta$ for $0<\theta<1$. Let $T=1_{\{A,B\}}$. Show $T$ is not sufficient.`,String.raw`Trên $\mathcal X=\{A,B,C\}$, cho $P_\theta(A)=\theta^2$, $P_\theta(B)=\theta(1-\theta)$, $P_\theta(C)=1-\theta$ với $0<\theta<1$. Đặt $T=1_{\{A,B\}}$. Chứng minh $T$ không đủ.`),solution:[b(String.raw`The probabilities sum to $\theta^2+\theta(1-\theta)+1-\theta=1$, and the fiber $T=1$ has probability $\theta$.`,String.raw`Các xác suất cộng thành $\theta^2+\theta(1-\theta)+1-\theta=1$, còn thớ $T=1$ có xác suất $\theta$.`),b(String.raw`Within that fiber, $P_\theta(A\mid T=1)=\theta^2/\theta=\theta$.`,String.raw`Trong thớ đó, $P_\theta(A\mid T=1)=\theta^2/\theta=\theta$.`),b(String.raw`This conditional probability varies, for example from $1/4$ at $\theta=1/4$ to $3/4$ at $\theta=3/4$; hence the statistic is insufficient.`,String.raw`Xác suất điều kiện thay đổi, chẳng hạn từ $1/4$ khi $\theta=1/4$ thành $3/4$ khi $\theta=3/4$; do đó thống kê không đủ.`)]},
      {prompt:b(String.raw`A fair-parameterized six-outcome model groups outcomes into fibers: probabilities are $\theta/3$ each for $a,b,c$ and $(1-\theta)/3$ each for $d,e,f$, $0<\theta<1$. Let T indicate which group occurred. Find the conditional law on each fiber and a factorization.`,String.raw`Mô hình sáu kết quả có xác suất $\theta/3$ cho mỗi $a,b,c$ và $(1-\theta)/3$ cho mỗi $d,e,f$, $0<\theta<1$. Cho T chỉ nhóm đã xảy ra. Tìm luật điều kiện trên mỗi thớ và một phân tích nhân tử.`),solution:[b(String.raw`The first group has total probability $\theta$, and conditional on that group each of a,b,c has probability $(\theta/3)/\theta=1/3$.`,String.raw`Nhóm đầu có xác suất tổng $\theta$, và với điều kiện thuộc nhóm đó, mỗi a,b,c có xác suất $(\theta/3)/\theta=1/3$.`),b(String.raw`The second group has total probability $1-\theta$, and each of d,e,f conditionally has probability $((1-\theta)/3)/(1-\theta)=1/3$.`,String.raw`Nhóm hai có xác suất tổng $1-\theta$, và mỗi d,e,f có xác suất điều kiện $((1-\theta)/3)/(1-\theta)=1/3$.`),b(String.raw`The conditional laws are parameter-free. Set $g_\theta(1)=\theta,g_\theta(0)=1-\theta$ and $h(x)=1/3$ for every outcome to obtain the factorization.`,String.raw`Hai luật điều kiện không phụ thuộc tham số. Đặt $g_\theta(1)=\theta,g_\theta(0)=1-\theta$ và $h(x)=1/3$ với mọi kết quả để được phân tích nhân tử.`)]}
    ],
    reviewNote:`The finite-support factorization is equivalent to parameter-free conditional laws on positive-probability T-fibers. The common-support assumption permits a shared sample-space comparison; zero-probability fibers are excluded from conditioning.`,
    sourceIds:['p-mit18655']
  },

  'm2-w045-e3': {
    title:b('Factor a binomial likelihood','Phân tích likelihood nhị thức'),
    application:b(String.raw`For iid Bernoulli observations, the product likelihood depends on their order only through the success count $S=\sum_iX_i$.`,String.raw`Với quan sát Bernoulli iid, likelihood tích chỉ phụ thuộc thứ tự qua số lần thành công $S=\sum_iX_i$.`),
    formula:b(String.raw`For $X_1,\ldots,X_n$ iid $\operatorname{Bernoulli}(\theta)$ with $\theta\in[0,1]$ and $x_i\in\{0,1\}$, $L_\theta(x)=\theta^S(1-\theta)^{n-S}$ where $S=\sum_i x_i$. On common sample space $\{0,1\}^n$, set $g_\theta(S)=\theta^S(1-\theta)^{n-S}$ and $h(x)=1$.`,String.raw`Với $X_1,\ldots,X_n$ iid $\operatorname{Bernoulli}(\theta)$, $\theta\in[0,1]$, $x_i\in\{0,1\}$, ta có $L_\theta(x)=\theta^S(1-\theta)^{n-S}$ với $S=\sum_i x_i$. Trên không gian mẫu chung $\{0,1\}^n$, đặt $g_\theta(S)=\theta^S(1-\theta)^{n-S}$ và $h(x)=1$.`),
    steps:[b(String.raw`For a realized binary vector, independence gives $f_\theta(x)=\prod_{i=1}^n\theta^{x_i}(1-\theta)^{1-x_i}$.`,String.raw`Với véc-tơ nhị phân quan sát được, độc lập cho $f_\theta(x)=\prod_{i=1}^n\theta^{x_i}(1-\theta)^{1-x_i}$.`),b(String.raw`Collect exponents: $\sum_i x_i=S$ and $\sum_i(1-x_i)=n-S$, so $f_\theta(x)=\theta^S(1-\theta)^{n-S}$.`,String.raw`Gom số mũ: $\sum_i x_i=S$ và $\sum_i(1-x_i)=n-S$, nên $f_\theta(x)=\theta^S(1-\theta)^{n-S}$.`),b(String.raw`This is a function of the sample through S times the parameter-free factor 1, establishing sufficiency by factorization.`,String.raw`Đây là hàm của mẫu chỉ qua S nhân với thừa số 1 không phụ thuộc tham số, chứng minh tính đủ theo phân tích nhân tử.`),b(String.raw`Given S=s, all $\binom ns$ ordered binary strings have probability proportional to the same likelihood, so each has conditional probability $1/\binom ns$.`,String.raw`Khi S=s, cả $\binom ns$ chuỗi nhị phân có likelihood như nhau nên mỗi chuỗi có xác suất điều kiện $1/\binom ns$.`)],
    primarySolution:[b(String.raw`Independence gives $L_\theta(x)=\prod_i\theta^{x_i}(1-\theta)^{1-x_i}$.`,String.raw`Tính độc lập cho $L_\theta(x)=\prod_i\theta^{x_i}(1-\theta)^{1-x_i}$.`),b(String.raw`Set $S=\sum_i x_i$; collecting powers yields $\theta^S(1-\theta)^{n-S}$.`,String.raw`Đặt $S=\sum_i x_i$; gom lũy thừa được $\theta^S(1-\theta)^{n-S}$.`),b(String.raw`Thus choose $g_\theta(S)=\theta^S(1-\theta)^{n-S}$ and $h(x)=1$ on the common binary support, so S is sufficient.`,String.raw`Vậy chọn $g_\theta(S)=\theta^S(1-\theta)^{n-S}$ và $h(x)=1$ trên hỗ trợ nhị phân chung, nên S đủ.`),b(String.raw`No additional ordering information remains: conditional on S, every binary sequence with that count has probability $1/\binom nS$, independent of $\theta$.`,String.raw`Không còn thông tin thứ tự nào: với điều kiện theo S, mỗi chuỗi nhị phân có số đếm đó có xác suất $1/\binom nS$, không phụ thuộc $\theta$.`)],
    companions:[
      {prompt:b(String.raw`For iid exponential observations with rate $\lambda>0$, derive the joint density and show that $T=\sum_iX_i$ is sufficient.`,String.raw`Với các quan sát mũ iid có tốc độ $\lambda>0$, suy mật độ chung và chứng minh $T=\sum_iX_i$ đủ.`),solution:[b(String.raw`Each density is $\lambda e^{-\lambda x_i}1_{\{x_i\ge0\}}$, so independence gives $f_\lambda(x)=\lambda^n e^{-\lambda\sum_i x_i}1_{\{x_i\ge0\ \forall i\}}$.`,String.raw`Mỗi mật độ là $\lambda e^{-\lambda x_i}1_{\{x_i\ge0\}}$, nên độc lập cho $f_\lambda(x)=\lambda^n e^{-\lambda\sum_i x_i}1_{\{x_i\ge0\ \forall i\}}$.`),b(String.raw`Writing $T=\sum_i x_i$, factor this as $g_\lambda(T)=\lambda^ne^{-\lambda T}$ times the parameter-free common-support indicator.`,String.raw`Viết $T=\sum_i x_i$, ta phân tích thành $g_\lambda(T)=\lambda^ne^{-\lambda T}$ nhân chỉ báo hỗ trợ chung không phụ thuộc tham số.`),b(String.raw`The factorization criterion therefore makes the sample sum sufficient for the exponential rate.`,String.raw`Vì vậy tiêu chuẩn phân tích nhân tử cho biết tổng mẫu đủ cho tốc độ mũ.`)]},
      {prompt:b(String.raw`In $n$ iid draws from categories A, B, C with probabilities $(p_A,p_B,p_C)$, derive the likelihood and identify a sufficient statistic.`,String.raw`Trong $n$ lần lấy iid từ các loại A, B, C có xác suất $(p_A,p_B,p_C)$, suy likelihood và xác định thống kê đủ.`),solution:[b(String.raw`Independence multiplies the category probabilities, yielding $L(p;x)=p_A^{N_A}p_B^{N_B}p_C^{N_C}$, where $N_j$ counts category j.`,String.raw`Độc lập nhân các xác suất loại, được $L(p;x)=p_A^{N_A}p_B^{N_B}p_C^{N_C}$, trong đó $N_j$ đếm loại j.`),b(String.raw`The likelihood depends on the ordered data only through $(N_A,N_B,N_C)$, whose entries sum to n.`,String.raw`Likelihood chỉ phụ thuộc dữ liệu có thứ tự qua $(N_A,N_B,N_C)$, các thành phần có tổng n.`),b(String.raw`The remaining factor is the parameter-free indicator that each observation is in $\{A,B,C\}$; hence the count vector is sufficient.`,String.raw`Thừa số còn lại là chỉ báo không phụ thuộc tham số rằng mọi quan sát thuộc $\{A,B,C\}$; do đó véc-tơ số đếm là đủ.`)]},
      {prompt:b(String.raw`Let $X_i$ be iid geometric$(p)$ counts of failures before the first success, with $P(X_i=x)=p(1-p)^x$ for $x=0,1,\ldots$ and $0<p<1$. Show the sample sum is sufficient.`,String.raw`Cho $X_i$ iid hình học$(p)$ đếm số thất bại trước thành công đầu, với $P(X_i=x)=p(1-p)^x$, $x=0,1,\ldots$, $0<p<1$. Chứng minh tổng mẫu là đủ.`),solution:[b(String.raw`The joint pmf is $\prod_i p(1-p)^{x_i}=p^n(1-p)^{\sum_i x_i}$.`,String.raw`pmf chung là $\prod_i p(1-p)^{x_i}=p^n(1-p)^{\sum_i x_i}$.`),b(String.raw`Let $T=\sum_i x_i$. Then the parameter-dependent part is $g_p(T)=p^n(1-p)^T$ and the common-support factor is 1.`,String.raw`Đặt $T=\sum_i x_i$. Khi đó phần phụ thuộc tham số là $g_p(T)=p^n(1-p)^T$ và thừa số hỗ trợ chung bằng 1.`),b(String.raw`The factorization theorem shows T is sufficient for p; no ordering detail appears in the likelihood.`,String.raw`Định lý phân tích nhân tử cho T đủ cho p; likelihood không chứa chi tiết thứ tự.`)]}
    ],
    reviewNote:`The Bernoulli likelihood factorization is valid on the common binary sample space, including boundary parameters by the usual pmf convention. Conditional on the count, all strings have equal probability.`,
    sourceIds:['p-mit18655']
  },

  'm2-w045-e4': {
    title:b('Counterexample: a statistic can discard identifiable information','Phản ví dụ: thống kê có thể bỏ thông tin nhận dạng'),
    application:b(String.raw`A statistic is sufficient only if the conditional law of the full data given that statistic no longer depends on the parameter; identifiability of the model alone does not ensure this.`,String.raw`Thống kê đủ khi luật có điều kiện của toàn bộ dữ liệu khi biết thống kê không còn phụ thuộc tham số; tính nhận dạng của mô hình tự nó không bảo đảm điều này.`),
    formula:b(String.raw`For iid $\operatorname{Bernoulli}(\theta)$ data with $n\ge2$ and $0<\theta<1$, if $T=X_1$, then $P_\theta(X_2=1\mid T=0)=\theta$. This varies with $\theta$, so T is not sufficient although the full Bernoulli family is identifiable.`,String.raw`Với dữ liệu $\operatorname{Bernoulli}(\theta)$ iid, $n\ge2$, $0<\theta<1$, nếu $T=X_1$ thì $P_\theta(X_2=1\mid T=0)=\theta$. Xác suất này thay đổi theo $\theta$, nên T không đủ dù họ Bernoulli đầy đủ có tính nhận dạng.`),
    steps:[b(String.raw`The event $T=0$ is exactly $X_1=0$ and has positive probability $1-\theta$ for interior $\theta$.`,String.raw`Biến cố $T=0$ chính là $X_1=0$ và có xác suất dương $1-\theta$ với $\theta$ bên trong.`),b(String.raw`Independence leaves $X_2$ distributed as $\operatorname{Bernoulli}(\theta)$ after conditioning on $X_1=0$.`,String.raw`Tính độc lập khiến $X_2$ vẫn có phân phối $\operatorname{Bernoulli}(\theta)$ sau khi điều kiện hóa theo $X_1=0$.`),b(String.raw`Thus the conditional success chance is $\theta$: it is $1/4$ at $\theta=1/4$ and $3/4$ at $\theta=3/4$.`,String.raw`Vì vậy xác suất thành công có điều kiện là $\theta$: bằng $1/4$ khi $\theta=1/4$ và $3/4$ khi $\theta=3/4$.`),b(String.raw`The conditional data law given T depends on the parameter, contradicting the defining sufficiency criterion.`,String.raw`Luật dữ liệu có điều kiện theo T phụ thuộc tham số, trái với tiêu chuẩn định nghĩa tính đủ.`)],
    primarySolution:[b(String.raw`For any interior $\theta$, $P_\theta(T=0)=P_\theta(X_1=0)=1-\theta>0$.`,String.raw`Với mọi $\theta$ bên trong, $P_\theta(T=0)=P_\theta(X_1=0)=1-\theta>0$.`),b(String.raw`Because the Bernoulli observations are independent, $P_\theta(X_2=1\mid T=0)=P_\theta(X_2=1)=\theta$.`,String.raw`Vì các quan sát Bernoulli độc lập, $P_\theta(X_2=1\mid T=0)=P_\theta(X_2=1)=\theta$.`),b(String.raw`This conditional probability equals $1/4$ at $\theta=1/4$ and $3/4$ at $\theta=3/4$, so the conditional law changes with $\theta$.`,String.raw`Xác suất điều kiện này bằng $1/4$ khi $\theta=1/4$ và $3/4$ khi $\theta=3/4$, nên luật điều kiện thay đổi theo $\theta$.`),b(String.raw`Therefore T is insufficient. The full model remains identifiable because the unconditional probability $P_\theta(X_1=1)=\theta$ determines the parameter.`,String.raw`Vì vậy T không đủ. Mô hình đầy đủ vẫn nhận dạng được vì xác suất vô điều kiện $P_\theta(X_1=1)=\theta$ xác định tham số.`)],
    companions:[
      {prompt:b(String.raw`For two iid Bernoulli$(p)$ tosses, let $T=1_{\{X_1=X_2\}}$. Test sufficiency by finding $P_p(X_1=1\mid T=1)$ at $p=1/4$ and $p=3/4$.`,String.raw`Với hai lần tung Bernoulli$(p)$ iid, đặt $T=1_{\{X_1=X_2\}}$. Kiểm tra tính đủ bằng cách tìm $P_p(X_1=1\mid T=1)$ tại $p=1/4$ và $p=3/4$.`),solution:[b(String.raw`The event $T=1$ consists of outcomes $(0,0)$ and $(1,1)$ and has probability $(1-p)^2+p^2$.`,String.raw`Biến cố $T=1$ gồm $(0,0)$ và $(1,1)$, có xác suất $(1-p)^2+p^2$.`),b(String.raw`Hence $P_p(X_1=1\mid T=1)=p^2/[p^2+(1-p)^2]$.`,String.raw`Do đó $P_p(X_1=1\mid T=1)=p^2/[p^2+(1-p)^2]$.`),b(String.raw`At $p=1/4$ this is $1/10$, while at $p=3/4$ it is $9/10$; dependence on p proves T insufficient.`,String.raw`Tại $p=1/4$ giá trị là $1/10$, còn tại $p=3/4$ là $9/10$; phụ thuộc p chứng minh T không đủ.`)]},
      {prompt:b(String.raw`Let $X_1,X_2$ be iid Poisson$(\lambda)$, $\lambda>0$, and set $T=1_{\{X_1=0\}}$. Compare $P_\lambda(X_2=0\mid T=1)$ at $\lambda=1$ and 2.`,String.raw`Cho $X_1,X_2$ iid Poisson$(\lambda)$, $\lambda>0$, đặt $T=1_{\{X_1=0\}}$. So sánh $P_\lambda(X_2=0\mid T=1)$ tại $\lambda=1$ và 2.`),solution:[b(String.raw`The conditioning event has probability $P_\lambda(T=1)=P_\lambda(X_1=0)=e^{-\lambda}>0$.`,String.raw`Biến cố điều kiện có xác suất $P_\lambda(T=1)=P_\lambda(X_1=0)=e^{-\lambda}>0$.`),b(String.raw`Independence gives $P_\lambda(X_2=0\mid T=1)=P_\lambda(X_2=0)=e^{-\lambda}$.`,String.raw`Độc lập cho $P_\lambda(X_2=0\mid T=1)=P_\lambda(X_2=0)=e^{-\lambda}$.`),b(String.raw`The values are $e^{-1}$ and $e^{-2}$, which differ; hence T is not sufficient for $\lambda$.`,String.raw`Hai giá trị là $e^{-1}$ và $e^{-2}$, khác nhau; do đó T không đủ cho $\lambda$.`)]},
      {prompt:b(String.raw`For independent $X_1,X_2\sim N(\mu,1)$, take $T=1_{\{X_1>0\}}$. Compare $P_\mu(X_2>0\mid T=1)$ at $\mu=0$ and $\mu=1$.`,String.raw`Với $X_1,X_2\sim N(\mu,1)$ độc lập, đặt $T=1_{\{X_1>0\}}$. So sánh $P_\mu(X_2>0\mid T=1)$ tại $\mu=0$ và $\mu=1$.`),solution:[b(String.raw`For every finite $\mu$, $P_\mu(T=1)=\Phi(\mu)>0$, so the condition is legitimate.`,String.raw`Với mọi $\mu$ hữu hạn, $P_\mu(T=1)=\Phi(\mu)>0$, nên điều kiện hợp lệ.`),b(String.raw`Independence yields $P_\mu(X_2>0\mid T=1)=P_\mu(X_2>0)=\Phi(\mu)$.`,String.raw`Tính độc lập cho $P_\mu(X_2>0\mid T=1)=P_\mu(X_2>0)=\Phi(\mu)$.`),b(String.raw`At $\mu=0$ this is $1/2$; at $\mu=1$ it is $\Phi(1)\approx.8413$. Since it varies, T is not sufficient.`,String.raw`Tại $\mu=0$ giá trị là $1/2$; tại $\mu=1$ là $\Phi(1)\approx.8413$. Vì thay đổi nên T không đủ.`)]}
    ],
    reviewNote:`The conditional-law criterion directly detects lost information in each example; the primary uses an interior Bernoulli parameter so the conditioning event always has positive probability. Identifiability concerns the whole law and is a different property.`,
    sourceIds:['p-mit18655']
  },

  'm2-w045-e5': {
    title:b('Transfer: exponential-family sufficient statistic','Chuyển giao: thống kê đủ họ mũ'),
    application:b(String.raw`Factor the iid Poisson joint pmf into a parameter term that depends on the data only through its sum and a data-only factorial remainder.`,String.raw`Phân tích pmf Poisson iid thành phần tham số chỉ phụ thuộc dữ liệu qua tổng và phần giai thừa chỉ phụ thuộc dữ liệu.`),
    formula:b(String.raw`For iid $X_i\sim\operatorname{Poisson}(\lambda)$, $\lambda>0$, on $\mathbb N_0^n$, $f_\lambda(x)=e^{-n\lambda}\lambda^T/\prod_i x_i!$ with $T=\sum_i x_i$. The sum is sufficient; $\mathbb E_\lambda X_i=\lambda$ identifies $\lambda$.`,String.raw`Với $X_i\sim\operatorname{Poisson}(\lambda)$ iid, $\lambda>0$, trên $\mathbb N_0^n$, $f_\lambda(x)=e^{-n\lambda}\lambda^T/\prod_i x_i!$ với $T=\sum_i x_i$. Tổng là thống kê đủ; $\mathbb E_\lambda X_i=\lambda$ nhận dạng $\lambda$.`),
    steps:[b(String.raw`The Poisson pmf for observation $x_i$ is $e^{-\lambda}\lambda^{x_i}/x_i!$.`,String.raw`pmf Poisson cho quan sát $x_i$ là $e^{-\lambda}\lambda^{x_i}/x_i!$.`),b(String.raw`Independence multiplies these terms, collecting exponentials and powers into $e^{-n\lambda}\lambda^{\sum_i x_i}/\prod_i x_i!$.`,String.raw`Tính độc lập nhân các số hạng, gom hàm mũ và lũy thừa thành $e^{-n\lambda}\lambda^{\sum_i x_i}/\prod_i x_i!$.`),b(String.raw`Set $T=\sum_i x_i$; the likelihood factors as $g_\lambda(T)=e^{-n\lambda}\lambda^T$ times $h(x)=1/\prod_i x_i!$.`,String.raw`Đặt $T=\sum_i x_i$; likelihood phân tích thành $g_\lambda(T)=e^{-n\lambda}\lambda^T$ nhân $h(x)=1/\prod_i x_i!$.`),b(String.raw`The factorization theorem makes T sufficient, and equality of laws forces equal finite means $\lambda$, so the model is identifiable.`,String.raw`Định lý phân tích nhân tử cho T đủ, còn hai luật bằng nhau buộc kỳ vọng hữu hạn $\lambda$ bằng nhau, nên mô hình nhận dạng được.`)],
    primarySolution:[b(String.raw`Multiplying the $n$ individual pmfs gives $f_\lambda(x)=e^{-n\lambda}\lambda^{\sum_i x_i}/\prod_i x_i!$.`,String.raw`Nhân $n$ pmf riêng lẻ được $f_\lambda(x)=e^{-n\lambda}\lambda^{\sum_i x_i}/\prod_i x_i!$.`),b(String.raw`Let $T=\sum_i x_i$ and choose $g_\lambda(T)=e^{-n\lambda}\lambda^T$, $h(x)=1/\prod_i x_i!$ on the common support.`,String.raw`Đặt $T=\sum_i x_i$ và chọn $g_\lambda(T)=e^{-n\lambda}\lambda^T$, $h(x)=1/\prod_i x_i!$ trên hỗ trợ chung.`),b(String.raw`This is the factorization criterion, hence T is sufficient for $\lambda$.`,String.raw`Đây là tiêu chuẩn phân tích nhân tử, nên T đủ cho $\lambda$.`),b(String.raw`The marginal law has mean $\lambda$; if two parameter laws coincide, their means coincide and therefore their $\lambda$ values are equal.`,String.raw`Luật biên có trung bình $\lambda$; nếu hai luật tham số trùng nhau thì kỳ vọng bằng nhau, nên giá trị $\lambda$ bằng nhau.`)],
    companions:[
      {prompt:b(String.raw`For iid exponential data with density $f_\lambda(x)=\lambda e^{-\lambda x}1_{\{x\ge0\}}$, $\lambda>0$, factor the joint density and identify a sufficient statistic.`,String.raw`Với dữ liệu mũ iid có mật độ $f_\lambda(x)=\lambda e^{-\lambda x}1_{\{x\ge0\}}$, $\lambda>0$, phân tích mật độ chung và xác định thống kê đủ.`),solution:[b(String.raw`Independence gives $f_\lambda(x_1,\ldots,x_n)=\lambda^n e^{-\lambda\sum_i x_i}1_{\{x_i\ge0\ \forall i\}}$.`,String.raw`Độc lập cho $f_\lambda(x_1,\ldots,x_n)=\lambda^n e^{-\lambda\sum_i x_i}1_{\{x_i\ge0\ \forall i\}}$.`),b(String.raw`With $T=\sum_i x_i$, the density is $g_\lambda(T)=\lambda^ne^{-\lambda T}$ times the parameter-free support indicator.`,String.raw`Với $T=\sum_i x_i$, mật độ là $g_\lambda(T)=\lambda^ne^{-\lambda T}$ nhân chỉ báo hỗ trợ không phụ thuộc tham số.`),b(String.raw`The factorization theorem therefore makes the sum sufficient for the exponential rate.`,String.raw`Định lý phân tích nhân tử vì thế cho tổng đủ cho tốc độ mũ.`)]},
      {prompt:b(String.raw`For iid $N(\mu,4)$ observations, show that $T=\sum_iX_i$ is sufficient for the unknown mean $\mu\in\mathbb R$.`,String.raw`Với các quan sát $N(\mu,4)$ iid, chứng minh $T=\sum_iX_i$ đủ cho trung bình chưa biết $\mu\in\mathbb R$.`),solution:[b(String.raw`The joint density is proportional to $\exp[-\frac18\sum_i(x_i-\mu)^2]$ on the common support $\mathbb R^n$.`,String.raw`Mật độ chung tỷ lệ với $\exp[-\frac18\sum_i(x_i-\mu)^2]$ trên hỗ trợ chung $\mathbb R^n$.`),b(String.raw`Expand the squares: $\sum_i(x_i-\mu)^2=\sum_i x_i^2-2\mu T+n\mu^2$.`,String.raw`Khai triển bình phương: $\sum_i(x_i-\mu)^2=\sum_i x_i^2-2\mu T+n\mu^2$.`),b(String.raw`The density factors into $\exp(\mu T/4-n\mu^2/8)$, which uses the data only through T, times $\exp(-\sum_i x_i^2/8)$ and a constant. Thus T is sufficient.`,String.raw`Mật độ phân tích thành $\exp(\mu T/4-n\mu^2/8)$ chỉ dùng dữ liệu qua T, nhân $\exp(-\sum_i x_i^2/8)$ và hằng số. Vậy T đủ.`)]},
      {prompt:b(String.raw`Let $X_i$ be iid geometric$(p)$ failures-before-success counts, $P(X_i=x)=p(1-p)^x$, with $0<p<1$. Derive the likelihood and show $T=\sum_iX_i$ sufficient.`,String.raw`Cho $X_i$ iid hình học$(p)$ đếm số thất bại trước thành công, $P(X_i=x)=p(1-p)^x$, $0<p<1$. Suy likelihood và chứng minh $T=\sum_iX_i$ đủ.`),solution:[b(String.raw`For observed nonnegative integers, the joint pmf is $\prod_i p(1-p)^{x_i}=p^n(1-p)^T$.`,String.raw`Với các số nguyên không âm quan sát được, pmf chung là $\prod_i p(1-p)^{x_i}=p^n(1-p)^T$.`),b(String.raw`The expression depends on the sample only through $T=\sum_i x_i$; the support indicator is parameter-free.`,String.raw`Biểu thức phụ thuộc mẫu chỉ qua $T=\sum_i x_i$; chỉ báo hỗ trợ không phụ thuộc tham số.`),b(String.raw`Thus the factorization criterion proves that T is sufficient for p.`,String.raw`Vì vậy tiêu chuẩn phân tích nhân tử chứng minh T đủ cho p.`)]}
    ],
    reviewNote:`The Poisson sum is sufficient by factorization on the common countable support, and its mean identifies the parameter. The companions separately verify continuous and discrete exponential-family factorizations.`,
    sourceIds:['p-mit18655']
  },

  'm2-w046-e1': {
    title:b('Rao–Blackwellize a Bernoulli observation','Rao–Blackwell hóa một quan sát Bernoulli'),
    application:b(String.raw`Given the total number of Bernoulli successes, exchangeability makes each sample position equally likely to contain any one of those successes.`,String.raw`Khi biết tổng số thành công Bernoulli, tính hoán vị làm mỗi vị trí có xác suất như nhau để chứa một trong các lần thành công.`),
    formula:b(String.raw`If $X_1,\ldots,X_n$ are iid $\operatorname{Bernoulli}(p)$, $T=\sum_iX_i$, and $U=X_1$, then $\mathbb E[U\mid T=t]=t/n$ for $t=0,\ldots,n$, including endpoints. Thus $\mathbb E[U\mid T]=T/n$, with $\operatorname{Var}(U)=p(1-p)$ and $\operatorname{Var}(T/n)=p(1-p)/n$.`,String.raw`Nếu $X_1,\ldots,X_n$ iid $\operatorname{Bernoulli}(p)$, $T=\sum_iX_i$, $U=X_1$, thì $\mathbb E[U\mid T=t]=t/n$ với $t=0,\ldots,n$, kể cả hai đầu. Do đó $\mathbb E[U\mid T]=T/n$, với $\operatorname{Var}(U)=p(1-p)$ và $\operatorname{Var}(T/n)=p(1-p)/n$.`),
    steps:[b(String.raw`On the event $T=t$, exactly t of the n coordinates equal 1; all placements have equal probability by iid symmetry.`,String.raw`Trên biến cố $T=t$, đúng t trong n tọa độ bằng 1; mọi cách sắp xếp có xác suất bằng nhau nhờ đối xứng iid.`),b(String.raw`Therefore $P(X_1=1\mid T=t)=t/n$, and because $X_1$ is an indicator its conditional mean is also $t/n$.`,String.raw`Vì vậy $P(X_1=1\mid T=t)=t/n$, và do $X_1$ là chỉ báo, trung bình có điều kiện cũng bằng $t/n$.`),b(String.raw`This identity holds at t=0 and t=n as well, giving $0$ and $1$ on the two endpoint fibers.`,String.raw`Đẳng thức cũng đúng tại t=0 và t=n, cho lần lượt $0$ và $1$ trên hai thớ đầu mút.`),b(String.raw`Since $T\sim\operatorname{Binomial}(n,p)$, $\operatorname{Var}(T/n)=np(1-p)/n^2=p(1-p)/n$, compared with $\operatorname{Var}(X_1)=p(1-p)$.`,String.raw`Vì $T\sim\operatorname{Binomial}(n,p)$, $\operatorname{Var}(T/n)=np(1-p)/n^2=p(1-p)/n$, so với $\operatorname{Var}(X_1)=p(1-p)$.`)],
    primarySolution:[b(String.raw`Conditional on $T=t$, exactly t of the n coordinates are successes, and permutation symmetry treats all positions equally.`,String.raw`Có điều kiện theo $T=t$, đúng t trong n tọa độ là thành công, và đối xứng hoán vị đối xử các vị trí như nhau.`),b(String.raw`Hence $P(X_1=1\mid T=t)=t/n$, so $\mathbb E[X_1\mid T=t]=t/n$ for every t, including 0 and n.`,String.raw`Do đó $P(X_1=1\mid T=t)=t/n$, nên $\mathbb E[X_1\mid T=t]=t/n$ với mọi t, kể cả 0 và n.`),b(String.raw`Thus the Rao–Blackwellized estimator is $\mathbb E[U\mid T]=T/n$.`,String.raw`Vậy ước lượng Rao–Blackwell hóa là $\mathbb E[U\mid T]=T/n$.`),b(String.raw`Its variance is $p(1-p)/n$, whereas $\operatorname{Var}(U)=p(1-p)$; for $n>1$ the reduction is strict when $0<p<1$.`,String.raw`Phương sai của nó là $p(1-p)/n$, còn $\operatorname{Var}(U)=p(1-p)$; khi $n>1$ mức giảm là nghiêm ngặt nếu $0<p<1$.`)],
    companions:[
      {prompt:b(String.raw`Let $X_1,\ldots,X_4$ be iid Poisson$(\lambda)$ and $T=\sum_iX_i$. For $U=X_1$, find $\mathbb E[U\mid T=t]$ and compare variances at $\lambda=2$.`,String.raw`Cho $X_1,\ldots,X_4$ iid Poisson$(\lambda)$ và $T=\sum_iX_i$. Với $U=X_1$, tìm $\mathbb E[U\mid T=t]$ và so sánh phương sai tại $\lambda=2$.`),solution:[b(String.raw`Conditional on total t, the four Poisson counts have a multinomial allocation with equal cell probabilities $1/4$, so $X_1\mid T=t\sim\operatorname{Binomial}(t,1/4)$.`,String.raw`Có điều kiện tổng bằng t, bốn số đếm Poisson được phân bổ đa thức với xác suất ô bằng nhau $1/4$, nên $X_1\mid T=t\sim\operatorname{Binomial}(t,1/4)$.`),b(String.raw`Therefore $\mathbb E[X_1\mid T=t]=t/4$, and the Rao–Blackwell estimator is $T/4$.`,String.raw`Vì vậy $\mathbb E[X_1\mid T=t]=t/4$, và ước lượng Rao–Blackwell là $T/4$.`),b(String.raw`At $\lambda=2$, $\operatorname{Var}(X_1)=2$ while $\operatorname{Var}(T/4)=4\lambda/16=1/2$, a fourfold reduction.`,String.raw`Tại $\lambda=2$, $\operatorname{Var}(X_1)=2$ còn $\operatorname{Var}(T/4)=4\lambda/16=1/2$, giảm bốn lần.`)]},
      {prompt:b(String.raw`For three iid $N(\mu,4)$ observations, let $T=X_1+X_2+X_3$ and $U=X_1$. Use symmetry to find $\mathbb E[U\mid T]$ and compare its variance with that of U.`,String.raw`Với ba quan sát $N(\mu,4)$ iid, đặt $T=X_1+X_2+X_3$, $U=X_1$. Dùng đối xứng tìm $\mathbb E[U\mid T]$ và so phương sai với U.`),solution:[b(String.raw`Given $T$, the three conditional means are equal by exchangeability; their sum is T, so each equals $T/3$.`,String.raw`Khi biết $T$, ba trung bình có điều kiện bằng nhau do tính hoán vị; tổng của chúng là T nên mỗi giá trị bằng $T/3$.`),b(String.raw`Thus $\mathbb E[X_1\mid T]=T/3$, an unbiased estimator of $\mu$.`,String.raw`Vậy $\mathbb E[X_1\mid T]=T/3$, là ước lượng không chệch của $\mu$.`),b(String.raw`The original variance is 4, while $\operatorname{Var}(T/3)=\operatorname{Var}(T)/9=12/9=4/3$.`,String.raw`Phương sai ban đầu là 4, còn $\operatorname{Var}(T/3)=\operatorname{Var}(T)/9=12/9=4/3$.`)]},
      {prompt:b(String.raw`Let $X_1,X_2,X_3$ be iid Uniform$(0,\theta)$, $\theta>0$, and set $M=\max_iX_i$. For $U=X_1$, find $\mathbb E[U\mid M]$ and its variance; compare with $\operatorname{Var}(U)$.`,String.raw`Cho $X_1,X_2,X_3$ iid Uniform$(0,\theta)$, $\theta>0$, đặt $M=\max_iX_i$. Với $U=X_1$, tìm $\mathbb E[U\mid M]$ và phương sai; so với $\operatorname{Var}(U)$.`),solution:[b(String.raw`Given $M=m$, each observation is equally likely to be the unique maximum. With probability $1/3$, $X_1=m$; otherwise it is one of two exchangeable observations uniform on $(0,m)$ with mean $m/2$.`,String.raw`Khi biết $M=m$, mỗi quan sát có xác suất như nhau làm cực đại duy nhất. Với xác suất $1/3$, $X_1=m$; nếu không, nó là một trong hai quan sát hoán vị đều trên $(0,m)$ với trung bình $m/2$.`),b(String.raw`Thus $\mathbb E[X_1\mid M=m]=(1/3)m+(2/3)(m/2)=2m/3$.`,String.raw`Vậy $\mathbb E[X_1\mid M=m]=(1/3)m+(2/3)(m/2)=2m/3$.`),b(String.raw`For three uniforms, $\operatorname{Var}(M)=3\theta^2/(4^2\cdot5)=3\theta^2/80$, so $\operatorname{Var}(2M/3)=\theta^2/60$.`,String.raw`Với ba biến đều, $\operatorname{Var}(M)=3\theta^2/(4^2\cdot5)=3\theta^2/80$, nên $\operatorname{Var}(2M/3)=\theta^2/60$.`),b(String.raw`Since $X_1\sim U(0,\theta)$ has variance $\theta^2/12$, conditioning reduces the variance to $\theta^2/60$; the likelihood also shows M is sufficient.`,String.raw`Vì $X_1\sim U(0,\theta)$ có phương sai $\theta^2/12$, điều kiện hóa giảm xuống $\theta^2/60$; likelihood cũng cho thấy M đủ.`)]}
    ],
    reviewNote:`For Bernoulli data the conditional success chance is t/n on every fiber, including the two endpoints. Variance comparisons use the exact binomial variance; companion conditional means follow exchangeability.`,
    sourceIds:['p-mit18655']
  },

  'm2-w046-e2': {
    title:b('Prove the conditional-variance improvement','Chứng minh cải thiện phương sai có điều kiện'),
    application:b(String.raw`Add and subtract the conditional mean, then use its defining zero-residual identity to remove the cross term in the squared error.`,String.raw`Cộng và trừ trung bình có điều kiện, rồi dùng đồng nhất thức phần dư có kỳ vọng điều kiện bằng không để triệt tiêu số hạng chéo.`),
    formula:b(String.raw`For $U\in L^2$ and any statistic T, $\operatorname{Var}(U)=\mathbb E[\operatorname{Var}(U\mid T)]+\operatorname{Var}(\mathbb E[U\mid T])$. Since the first term is nonnegative, $\operatorname{Var}(\mathbb E[U\mid T])\le\operatorname{Var}(U)$.`,String.raw`Với $U\in L^2$ và thống kê T bất kỳ, $\operatorname{Var}(U)=\mathbb E[\operatorname{Var}(U\mid T)]+\operatorname{Var}(\mathbb E[U\mid T])$. Vì số hạng đầu không âm, $\operatorname{Var}(\mathbb E[U\mid T])\le\operatorname{Var}(U)$.`),
    steps:[b(String.raw`Let $m(T)=\mathbb E[U\mid T]$ and decompose $U-\mathbb EU=(U-m(T))+(m(T)-\mathbb EU)$.`,String.raw`Đặt $m(T)=\mathbb E[U\mid T]$ và phân rã $U-\mathbb EU=(U-m(T))+(m(T)-\mathbb EU)$.`),b(String.raw`Expand the square. The cross expectation is $\mathbb E[(U-m(T))(m(T)-\mathbb EU)]$.`,String.raw`Khai triển bình phương. Kỳ vọng số hạng chéo là $\mathbb E[(U-m(T))(m(T)-\mathbb EU)]$.`),b(String.raw`Conditioning that product on T makes $m(T)-\mathbb EU$ measurable and leaves $\mathbb E[U-m(T)\mid T]=0$, so the cross term vanishes.`,String.raw`Điều kiện hóa tích theo T làm $m(T)-\mathbb EU$ đo được và cho $\mathbb E[U-m(T)\mid T]=0$, nên số hạng chéo triệt tiêu.`),b(String.raw`The first square has expectation $\mathbb E[\operatorname{Var}(U\mid T)]$; the second is $\operatorname{Var}(m(T))$. Their sum is $\operatorname{Var}(U)$.`,String.raw`Kỳ vọng bình phương thứ nhất là $\mathbb E[\operatorname{Var}(U\mid T)]$; bình phương thứ hai là $\operatorname{Var}(m(T))$. Tổng bằng $\operatorname{Var}(U)$.`),b(String.raw`Nonnegativity of conditional variance gives the inequality, with equality exactly when $U=m(T)$ a.s.`,String.raw`Tính không âm của phương sai có điều kiện cho bất đẳng thức, đẳng thức xảy ra khi $U=m(T)$ h.c.`)],
    primarySolution:[b(String.raw`Because $U\in L^2$, its conditional expectation $m=\mathbb E[U\mid T]$ is also square-integrable.`,String.raw`Vì $U\in L^2$, kỳ vọng có điều kiện $m=\mathbb E[U\mid T]$ cũng bình phương khả tích.`),b(String.raw`Write $U-\mathbb EU=(U-m)+(m-\mathbb EU)$ and square both sides.`,String.raw`Viết $U-\mathbb EU=(U-m)+(m-\mathbb EU)$ rồi bình phương hai vế.`),b(String.raw`The cross term has expectation zero since $\mathbb E[U-m\mid T]=0$ and $m-\mathbb EU$ is T-measurable.`,String.raw`Số hạng chéo có kỳ vọng bằng không vì $\mathbb E[U-m\mid T]=0$ và $m-\mathbb EU$ đo được theo T.`),b(String.raw`The remaining expectations are $\mathbb E[\operatorname{Var}(U\mid T)]$ and $\operatorname{Var}(m)$, proving the decomposition.`,String.raw`Hai kỳ vọng còn lại là $\mathbb E[\operatorname{Var}(U\mid T)]$ và $\operatorname{Var}(m)$, chứng minh phân rã.`),b(String.raw`Since $\mathbb E[\operatorname{Var}(U\mid T)]\ge0$, the conditional mean has variance at most $\operatorname{Var}(U)$.`,String.raw`Vì $\mathbb E[\operatorname{Var}(U\mid T)]\ge0$, trung bình có điều kiện có phương sai không vượt $\operatorname{Var}(U)$.`)],
    companions:[
      {prompt:b(String.raw`Let four equiprobable outcomes have $U=(0,1,2,3)$ and let T distinguish only the first pair $\{a,b\}$ from the second pair $\{c,d\}$. Compute both variance components.`,String.raw`Cho bốn kết quả đồng xác suất với $U=(0,1,2,3)$ và T chỉ phân biệt cặp đầu $\{a,b\}$ với cặp sau $\{c,d\}$. Tính hai thành phần phương sai.`),solution:[b(String.raw`The overall mean is $\mathbb EU=(0+1+2+3)/4=3/2$, and $\mathbb E U^2=(0+1+4+9)/4=7/2$, so $\operatorname{Var}(U)=7/2-9/4=5/4$.`,String.raw`Trung bình chung là $\mathbb EU=(0+1+2+3)/4=3/2$, còn $\mathbb E U^2=(0+1+4+9)/4=7/2$, nên $\operatorname{Var}(U)=7/2-9/4=5/4$.`),b(String.raw`The two conditional means are $1/2$ and $5/2$, each with probability $1/2$; their variance is 1.`,String.raw`Hai trung bình có điều kiện là $1/2$ và $5/2$, mỗi giá trị xác suất $1/2$; phương sai của chúng là 1.`),b(String.raw`Within each pair the values differ by 1, so each conditional variance is $1/4$ and their average is $1/4$. Hence $5/4=1+1/4$.`,String.raw`Trong mỗi cặp, hai giá trị lệch nhau 1 nên phương sai có điều kiện là $1/4$; trung bình cũng là $1/4$. Do đó $5/4=1+1/4$.`)]},
      {prompt:b(String.raw`Let $U$ be Uniform$(0,1)$ and $T=1_{\{U<1/2\}}$. Find $\mathbb E[U\mid T]$ and verify the variance decomposition numerically.`,String.raw`Cho $U$ đều trên $(0,1)$ và $T=1_{\{U<1/2\}}$. Tìm $\mathbb E[U\mid T]$ và kiểm tra phân rã phương sai bằng số.`),solution:[b(String.raw`Conditional means are $1/4$ when $T=1$ and $3/4$ when $T=0$, so $\operatorname{Var}(\mathbb E[U\mid T])=(1/4)^2=1/16$.`,String.raw`Trung bình có điều kiện là $1/4$ khi $T=1$ và $3/4$ khi $T=0$, nên $\operatorname{Var}(\mathbb E[U\mid T])=(1/4)^2=1/16$.`),b(String.raw`Each half-interval has conditional variance $(1/2)^2/12=1/48$, giving $\mathbb E[\operatorname{Var}(U\mid T)]=1/48$.`,String.raw`Mỗi nửa khoảng có phương sai điều kiện $(1/2)^2/12=1/48$, nên $\mathbb E[\operatorname{Var}(U\mid T)]=1/48$.`),b(String.raw`Their sum is $1/16+1/48=1/12$, equal to the Uniform$(0,1)$ variance.`,String.raw`Tổng là $1/16+1/48=1/12$, bằng phương sai của Uniform$(0,1)$.`)]},
      {prompt:b(String.raw`Let $U\sim N(0,1)$ and $T=1_{\{U>0\}}$. Compute the variance of $\mathbb E[U\mid T]$ and the expected conditional variance.`,String.raw`Cho $U\sim N(0,1)$ và $T=1_{\{U>0\}}$. Tính phương sai của $\mathbb E[U\mid T]$ và kỳ vọng phương sai có điều kiện.`),solution:[b(String.raw`By symmetry, $T$ is a fair Bernoulli variable; the half-normal mean is $\mathbb E[U\mid U>0]=\sqrt{2/\pi}$ and the negative-half mean is its negative.`,String.raw`Theo đối xứng, $T$ Bernoulli công bằng; trung bình nửa chuẩn dương là $\mathbb E[U\mid U>0]=\sqrt{2/\pi}$, còn nửa âm là số đối.`),b(String.raw`The conditional mean therefore has variance $2/\pi$.`,String.raw`Vì vậy trung bình có điều kiện có phương sai $2/\pi$.`),b(String.raw`Since $\operatorname{Var}(U)=1$, the decomposition gives $\mathbb E[\operatorname{Var}(U\mid T)]=1-2/\pi$.`,String.raw`Vì $\operatorname{Var}(U)=1$, phân rã cho $\mathbb E[\operatorname{Var}(U\mid T)]=1-2/\pi$.`)]}
    ],
    reviewNote:`The cross term vanishes by conditioning on T, requiring square integrability for the variance quantities. Equality in the reduction occurs precisely when U is already T-measurable a.s.`,
    sourceIds:['p-mit18655']
  },

  'm2-w046-e3': {
    title:b('Use completeness to prove uniqueness','Dùng tính đầy đủ chứng minh duy nhất'),
    application:b(String.raw`Subtract two unbiased functions of a complete statistic; their difference has mean zero for every parameter and must vanish almost surely.`,String.raw`Lấy hiệu hai hàm không chệch của thống kê đầy đủ; hiệu có trung bình không với mọi tham số nên phải triệt tiêu hầu chắc chắn.`),
    formula:b(String.raw`A statistic T is complete if every measurable $g$ with $\mathbb E_\theta|g(T)|<\infty$ and $\mathbb E_\theta g(T)=0$ for all $\theta$ satisfies $g(T)=0$ a.s. under every $P_\theta$. Thus if $a(T),b(T)$ are integrable unbiased estimators of the same $\tau(\theta)$ for every $\theta$, then $a(T)=b(T)$ a.s.`,String.raw`Thống kê T đầy đủ nếu mọi hàm đo được $g$ có $\mathbb E_\theta|g(T)|<\infty$ và $\mathbb E_\theta g(T)=0$ với mọi $\theta$ đều thỏa $g(T)=0$ h.c. dưới mọi $P_\theta$. Vì vậy nếu $a(T),b(T)$ là ước lượng khả tích không chệch cùng $\tau(\theta)$ với mọi $\theta$, thì $a(T)=b(T)$ h.c.`),
    steps:[b(String.raw`Both unbiasedness statements give $\mathbb E_\theta[a(T)]=\tau(\theta)=\mathbb E_\theta[b(T)]$ for every parameter.`,String.raw`Hai phát biểu không chệch cho $\mathbb E_\theta[a(T)]=\tau(\theta)=\mathbb E_\theta[b(T)]$ với mọi tham số.`),b(String.raw`Subtract to obtain $\mathbb E_\theta[(a-b)(T)]=0$ for all $\theta$.`,String.raw`Lấy hiệu được $\mathbb E_\theta[(a-b)(T)]=0$ với mọi $\theta$.`),b(String.raw`The difference is integrable because both estimators are integrable, so it meets the completeness definition.`,String.raw`Hiệu khả tích vì cả hai ước lượng đều khả tích, nên thỏa định nghĩa đầy đủ.`),b(String.raw`Completeness applied to $g=a-b$ yields $(a-b)(T)=0$ almost surely under each model law, proving equality of the estimators a.s.`,String.raw`Áp dụng tính đầy đủ cho $g=a-b$ cho $(a-b)(T)=0$ h.c. dưới mỗi luật mô hình, chứng minh hai ước lượng bằng nhau h.c.`)],
    primarySolution:[b(String.raw`Define $g(t)=a(t)-b(t)$.`,String.raw`Đặt $g(t)=a(t)-b(t)$.`),b(String.raw`For every $\theta$, unbiasedness for the same target gives $\mathbb E_\theta[g(T)]=\tau(\theta)-\tau(\theta)=0$.`,String.raw`Với mọi $\theta$, tính không chệch cho cùng đại lượng đích cho $\mathbb E_\theta[g(T)]=\tau(\theta)-\tau(\theta)=0$.`),b(String.raw`Because a and b are integrable, g(T) is integrable, so completeness applies to this zero-mean function.`,String.raw`Vì a và b khả tích, g(T) khả tích, nên tính đầy đủ áp dụng cho hàm có trung bình không này.`),b(String.raw`It follows that $g(T)=0$ almost surely, hence $a(T)=b(T)$ almost surely under every parameter value.`,String.raw`Suy ra $g(T)=0$ hầu chắc, nên $a(T)=b(T)$ hầu chắc dưới mọi giá trị tham số.`)],
    companions:[
      {prompt:b(String.raw`Let $T\sim\operatorname{Binomial}(2,p)$ for all $0<p<1$. The estimator $1_{\{T=2\}}$ is unbiased for $p^2$. If $b(T)$ is any other unbiased function for $p^2$, determine its values at $T=0,1,2$.`,String.raw`Cho $T\sim\operatorname{Binomial}(2,p)$ với mọi $0<p<1$. Ước lượng $1_{\{T=2\}}$ không chệch cho $p^2$. Nếu $b(T)$ là hàm không chệch khác cho $p^2$, hãy tìm giá trị tại $T=0,1,2$.`),solution:[b(String.raw`Write $b(0)=a_0,b(1)=a_1,b(2)=a_2$. Its expectation is $a_0(1-p)^2+2a_1p(1-p)+a_2p^2$.`,String.raw`Viết $b(0)=a_0,b(1)=a_1,b(2)=a_2$. Kỳ vọng là $a_0(1-p)^2+2a_1p(1-p)+a_2p^2$.`),b(String.raw`Expanding gives $a_0+(-2a_0+2a_1)p+(a_0-2a_1+a_2)p^2$. This must equal $p^2$ for every p in an interval.`,String.raw`Khai triển được $a_0+(-2a_0+2a_1)p+(a_0-2a_1+a_2)p^2$. Biểu thức phải bằng $p^2$ với mọi p trong một khoảng.`),b(String.raw`Matching polynomial coefficients gives $a_0=0$, then $a_1=0$, then $a_2=1$. Thus $b(T)=1_{\{T=2\}}$, confirming uniqueness.`,String.raw`So hệ số cho $a_0=0$, tiếp theo $a_1=0$, rồi $a_2=1$. Vậy $b(T)=1_{\{T=2\}}$, xác nhận tính duy nhất.`)]},
      {prompt:b(String.raw`For $T\sim\operatorname{Poisson}(\lambda)$, $\lambda>0$, the indicator $1_{\{T=0\}}$ estimates $e^{-\lambda}$ unbiasedly. Prove any integrable unbiased function of T for this target agrees with it a.s.`,String.raw`Với $T\sim\operatorname{Poisson}(\lambda)$, $\lambda>0$, chỉ báo $1_{\{T=0\}}$ ước lượng không chệch $e^{-\lambda}$. Chứng minh mọi hàm khả tích không chệch của T cho đại lượng này bằng nó h.c.`),solution:[b(String.raw`Let $g(T)=b(T)-1_{\{T=0\}}$ for a competing unbiased estimator b. Then $\mathbb E_\lambda g(T)=0$ for every $\lambda>0$.`,String.raw`Đặt $g(T)=b(T)-1_{\{T=0\}}$ với ước lượng cạnh tranh b. Khi đó $\mathbb E_\lambda g(T)=0$ với mọi $\lambda>0$.`),b(String.raw`Using the Poisson pmf, $e^\lambda\mathbb E_\lambda g(T)=\sum_{k=0}^\infty g(k)\lambda^k/k!=0$. Integrability ensures absolute convergence for each $\lambda>0$.`,String.raw`Dùng pmf Poisson, $e^\lambda\mathbb E_\lambda g(T)=\sum_{k=0}^\infty g(k)\lambda^k/k!=0$. Tính khả tích bảo đảm hội tụ tuyệt đối với từng $\lambda>0$.`),b(String.raw`A power series vanishing throughout $(0,\infty)$ has all coefficients zero; hence $g(k)=0$ for every k and the two estimators coincide on the support.`,String.raw`Chuỗi lũy thừa bằng không trên $(0,\infty)$ có mọi hệ số bằng không; do đó $g(k)=0$ với mọi k và hai ước lượng trùng nhau trên hỗ trợ.`)]},
      {prompt:b(String.raw`For $X_1,X_2$ iid $N(\mu,1)$ with $\mu\in\mathbb R$, assume the complete statistic theorem for $T=X_1+X_2$. Find a function of T unbiased for $\mu^2$ and state the uniqueness implication.`,String.raw`Với $X_1,X_2$ iid $N(\mu,1)$, $\mu\in\mathbb R$, giả sử định lý thống kê đầy đủ cho $T=X_1+X_2$. Tìm hàm T không chệch cho $\mu^2$ và nêu hệ quả duy nhất.`),solution:[b(String.raw`Here $T\sim N(2\mu,2)$, so $\mathbb E[T^2]=\operatorname{Var}(T)+(\mathbb ET)^2=2+4\mu^2$.`,String.raw`Ở đây $T\sim N(2\mu,2)$, nên $\mathbb E[T^2]=\operatorname{Var}(T)+(\mathbb ET)^2=2+4\mu^2$.`),b(String.raw`Therefore $A(T)=T^2/4-1/2$ has expectation $(2+4\mu^2)/4-1/2=\mu^2$.`,String.raw`Vì vậy $A(T)=T^2/4-1/2$ có kỳ vọng $(2+4\mu^2)/4-1/2=\mu^2$.`),b(String.raw`If B(T) is any other integrable unbiased function for $\mu^2$, then $\mathbb E_\mu[B(T)-A(T)]=0$ for all real μ.`,String.raw`Nếu B(T) là hàm khả tích không chệch khác cho $\mu^2$, thì $\mathbb E_\mu[B(T)-A(T)]=0$ với mọi μ thực.`),b(String.raw`Completeness of T forces $B(T)=A(T)$ almost surely, with the completeness theorem explicitly assumed here.`,String.raw`Tính đầy đủ của T buộc $B(T)=A(T)$ h.c.; bài này nêu rõ đang giả sử định lý đầy đủ.`)]}
    ],
    reviewNote:`The uniqueness argument requires zero expectation for every parameter and integrability of the difference. Binomial and Poisson companions show coefficient arguments underlying completeness; the normal completeness premise is explicitly assumed.`,
    sourceIds:['p-mit18655']
  },

  'm2-w046-e4': {
    title:b('Counterexample: sufficiency without completeness','Phản ví dụ: đủ nhưng không đầy đủ'),
    application:b(String.raw`A sufficient statistic need not be complete when the parameter space is restricted: build a nonzero function of the statistic whose expectation vanishes at every allowed parameter.`,String.raw`Thống kê đủ chưa chắc đầy đủ khi không gian tham số bị hạn chế: dựng hàm khác không của thống kê có kỳ vọng bằng không tại mọi tham số được phép.`),
    formula:b(String.raw`For $X_1,X_2$ iid $\operatorname{Bernoulli}(p)$ with $p\in\{1/4,3/4\}$ and $T=X_1+X_2$, the binomial likelihood makes T sufficient. With $g(0)=3,g(1)=-5,g(2)=3$, $\mathbb E_p g(T)=3-16p+16p^2=0$ at both allowed p, although g is nonzero.`,String.raw`Với $X_1,X_2$ iid $\operatorname{Bernoulli}(p)$, $p\in\{1/4,3/4\}$, $T=X_1+X_2$, likelihood nhị thức cho T đủ. Với $g(0)=3,g(1)=-5,g(2)=3$, $\mathbb E_p g(T)=3-16p+16p^2=0$ tại cả hai p cho phép, dù g khác không.`),
    steps:[b(String.raw`Factor the joint Bernoulli likelihood as $p^T(1-p)^{2-T}$ times the common-support indicator; this depends on the sample through T only.`,String.raw`Phân tích likelihood Bernoulli chung thành $p^T(1-p)^{2-T}$ nhân chỉ báo hỗ trợ chung; mẫu chỉ xuất hiện qua T.`),b(String.raw`For $T=0,1,2$, assign $g(T)=3,-5,3$, respectively; this function is plainly not identically zero.`,String.raw`Với $T=0,1,2$, lần lượt đặt $g(T)=3,-5,3$; hàm này rõ ràng không đồng nhất bằng không.`),b(String.raw`Using $P(T=0)=(1-p)^2$, $P(T=1)=2p(1-p)$, and $P(T=2)=p^2$, obtain $\mathbb E_pg(T)=3(1-p)^2-10p(1-p)+3p^2$.`,String.raw`Dùng $P(T=0)=(1-p)^2$, $P(T=1)=2p(1-p)$, $P(T=2)=p^2$, ta được $\mathbb E_pg(T)=3(1-p)^2-10p(1-p)+3p^2$.`),b(String.raw`Expanding gives $3-16p+16p^2$, which is zero at $p=1/4$ and $p=3/4$.`,String.raw`Khai triển được $3-16p+16p^2$, bằng không tại $p=1/4$ và $p=3/4$.`),b(String.raw`Completeness fails by definition, even though sufficiency holds.`,String.raw`Theo định nghĩa, tính đầy đủ thất bại dù tính đủ đúng.`)],
    primarySolution:[b(String.raw`The Bernoulli likelihood factors through $T=X_1+X_2$, hence T is sufficient.`,String.raw`Likelihood Bernoulli phân tích qua $T=X_1+X_2$, nên T đủ.`),b(String.raw`For the proposed g, $\mathbb E_pg(T)=3(1-p)^2-10p(1-p)+3p^2=3-16p+16p^2$.`,String.raw`Với g đã cho, $\mathbb E_pg(T)=3(1-p)^2-10p(1-p)+3p^2=3-16p+16p^2$.`),b(String.raw`At $p=1/4$ the value is $3-4+1=0$; at $p=3/4$ it is $3-12+9=0$.`,String.raw`Tại $p=1/4$ giá trị là $3-4+1=0$; tại $p=3/4$ là $3-12+9=0$.`),b(String.raw`Yet $g(0)=3$ and $g(1)=-5$, so g is nonzero with probability-positive values. The definition of completeness is violated.`,String.raw`Nhưng $g(0)=3$ và $g(1)=-5$, nên g khác không trên các giá trị có xác suất dương. Định nghĩa đầy đủ bị vi phạm.`)],
    companions:[
      {prompt:b(String.raw`Let $T\sim\operatorname{Binomial}(3,p)$ with restricted parameter set $p\in\{1/4,3/4\}$. Verify that $g(0)=g(3)=9$, $g(1)=g(2)=-7$ is a nonzero zero-mean function.`,String.raw`Cho $T\sim\operatorname{Binomial}(3,p)$ với không gian tham số hạn chế $p\in\{1/4,3/4\}$. Kiểm tra $g(0)=g(3)=9$, $g(1)=g(2)=-7$ là hàm khác không có trung bình bằng không.`),solution:[b(String.raw`The endpoint counts have total probability $(1-p)^3+p^3=7/16$ at either allowed parameter.`,String.raw`Hai số đếm đầu mút có xác suất tổng $(1-p)^3+p^3=7/16$ tại mỗi tham số cho phép.`),b(String.raw`The middle counts have total probability $3p(1-p)^2+3p^2(1-p)=9/16$ at p=1/4 and also at p=3/4.`,String.raw`Hai số đếm giữa có xác suất tổng $3p(1-p)^2+3p^2(1-p)=9/16$ tại p=1/4 và cũng tại p=3/4.`),b(String.raw`Thus $\mathbb E_pg(T)=9(7/16)-7(9/16)=0$ for both parameters, while $g$ is nonzero; the binomial total remains sufficient by factorization.`,String.raw`Vậy $\mathbb E_pg(T)=9(7/16)-7(9/16)=0$ ở cả hai tham số, trong khi $g$ khác không; tổng nhị thức vẫn đủ theo phân tích nhân tử.`)]},
      {prompt:b(String.raw`Take two iid Poisson$(\lambda)$ counts with $\lambda\in\{1/2,1\}$ and $T=X_1+X_2$. Define $g(0)=2,g(1)=-3,g(2)=2$, and $g(t)=0$ for $t\ge3$. Verify zero mean for both allowed rates.`,String.raw`Cho hai số đếm Poisson$(\lambda)$ iid với $\lambda\in\{1/2,1\}$, $T=X_1+X_2$. Đặt $g(0)=2,g(1)=-3,g(2)=2$, $g(t)=0$ khi $t\ge3$. Kiểm tra kỳ vọng bằng không tại cả hai tốc độ.`),solution:[b(String.raw`The sum satisfies $T\sim\operatorname{Poisson}(2\lambda)$ and is sufficient by the joint likelihood factorization.`,String.raw`Tổng có $T\sim\operatorname{Poisson}(2\lambda)$ và đủ theo phân tích likelihood chung.`),b(String.raw`For mean parameter $m=2\lambda$, $\mathbb E g(T)=e^{-m}(2-3m+m^2)$, since the t=2 mass is $e^{-m}m^2/2$ and is multiplied by 2.`,String.raw`Với tham số trung bình $m=2\lambda$, $\mathbb E g(T)=e^{-m}(2-3m+m^2)$, vì khối lượng t=2 là $e^{-m}m^2/2$ và được nhân 2.`),b(String.raw`Allowed m values are 1 and 2; the polynomial is $2-3+1=0$ and $2-6+4=0$. Since $g(0)=2$, T is not complete in this restricted model.`,String.raw`Các giá trị m cho phép là 1 và 2; đa thức lần lượt là $2-3+1=0$ và $2-6+4=0$. Vì $g(0)=2$, T không đầy đủ trong mô hình hạn chế này.`)]},
      {prompt:b(String.raw`For two iid geometric$(p)$ failure counts, $P(X_i=x)=p(1-p)^x$, restrict $p\in\{1/4,3/4\}$ and let $T=X_1+X_2$. Check that $g(0)=9,g(1)=-24,g(2)=16$ and $g(t)=0$ otherwise has zero expectation at both p values.`,String.raw`Với hai số đếm thất bại hình học$(p)$ iid, $P(X_i=x)=p(1-p)^x$, hạn chế $p\in\{1/4,3/4\}$ và đặt $T=X_1+X_2$. Kiểm tra $g(0)=9,g(1)=-24,g(2)=16$, $g(t)=0$ nếu khác, có kỳ vọng bằng không ở cả hai p.`),solution:[b(String.raw`The joint likelihood is $p^2(1-p)^T$, so T is sufficient; its pmf is $P(T=t)=(t+1)p^2(1-p)^t$.`,String.raw`Likelihood chung là $p^2(1-p)^T$, nên T đủ; pmf của nó là $P(T=t)=(t+1)p^2(1-p)^t$.`),b(String.raw`Only t=0,1,2 contribute, giving $\mathbb E_pg(T)=p^2[9-48(1-p)+48(1-p)^2]$.`,String.raw`Chỉ t=0,1,2 đóng góp, cho $\mathbb E_pg(T)=p^2[9-48(1-p)+48(1-p)^2]$.`),b(String.raw`At p=1/4 the bracket is $9-36+27=0$; at p=3/4 it is $9-12+3=0$.`,String.raw`Tại p=1/4, ngoặc vuông là $9-36+27=0$; tại p=3/4 là $9-12+3=0$.`),b(String.raw`Because $g(0)=9\ne0$ on a positive-probability value, T is sufficient but not complete for this restricted geometric model.`,String.raw`Vì $g(0)=9\ne0$ tại giá trị có xác suất dương, T đủ nhưng không đầy đủ trong mô hình hình học hạn chế này.`)]}
    ],
    reviewNote:`Each noncompleteness witness is nonzero on a value with positive probability and has expectation zero at every allowed parameter. Sufficiency follows separately from the likelihood factorization.`,
    sourceIds:['p-mit18655']
  },

  'm2-w046-e5': {
    title:b('Transfer: verify a UMVU claim','Chuyển giao: kiểm tra khẳng định UMVU'),
    application:b(String.raw`For an unbiased estimator with finite variance, Rao–Blackwellize by the sufficient total; completeness then identifies the unique unbiased function of that total.`,String.raw`Với ước lượng không chệch có phương sai hữu hạn, Rao–Blackwell hóa theo tổng đủ; tính đầy đủ sau đó xác định hàm không chệch duy nhất của tổng.`),
    formula:b(String.raw`For iid Bernoulli$(p)$, $p\in[0,1]$, $T=\sum_iX_i\sim\operatorname{Binomial}(n,p)$ is sufficient and complete. The estimator $T/n$ is unbiased for p. For every unbiased $U\in L^2$, $R=\mathbb E[U\mid T]$ is unbiased, has $\operatorname{Var}(R)\le\operatorname{Var}(U)$, and completeness forces $R=T/n$ a.s.; hence $T/n$ is UMVU. Binomial completeness is assumed here, not proved.`,String.raw`Với Bernoulli$(p)$ iid, $p\in[0,1]$, $T=\sum_iX_i\sim\operatorname{Binomial}(n,p)$ là thống kê đủ và đầy đủ. Ước lượng $T/n$ không chệch cho p. Với mọi $U\in L^2$ không chệch, $R=\mathbb E[U\mid T]$ không chệch, có $\operatorname{Var}(R)\le\operatorname{Var}(U)$, và tính đầy đủ buộc $R=T/n$ h.c.; do đó $T/n$ là UMVU. Tính đầy đủ nhị thức được giả định, không chứng minh ở đây.`),
    steps:[b(String.raw`The total T is sufficient by the Bernoulli likelihood factorization, and $\mathbb E[T/n]=p$.`,String.raw`Tổng T đủ theo phân tích likelihood Bernoulli, và $\mathbb E[T/n]=p$.`),b(String.raw`For any unbiased finite-variance U, sufficiency makes $R=\mathbb E[U\mid T]$ an unbiased function of T.`,String.raw`Với mọi U không chệch có phương sai hữu hạn, tính đủ làm $R=\mathbb E[U\mid T]$ thành hàm không chệch của T.`),b(String.raw`Rao–Blackwell and the conditional-variance identity give $\operatorname{Var}(R)\le\operatorname{Var}(U)$.`,String.raw`Rao–Blackwell và đồng nhất thức phương sai có điều kiện cho $\operatorname{Var}(R)\le\operatorname{Var}(U)$.`),b(String.raw`Since both R and $T/n$ are unbiased functions of the complete T, completeness makes them equal a.s.; consequently $T/n$ has no larger variance than any unbiased finite-variance estimator.`,String.raw`Vì R và $T/n$ đều là hàm không chệch của T đầy đủ, tính đầy đủ làm chúng bằng nhau h.c.; do đó $T/n$ có phương sai không lớn hơn mọi ước lượng không chệch có phương sai hữu hạn.`),b(String.raw`The completeness theorem for the binomial total is an invoked premise; the exercise does not derive it.`,String.raw`Định lý đầy đủ của tổng nhị thức là tiền đề được viện dẫn; bài tập không suy ra định lý đó.`)],
    primarySolution:[b(String.raw`The sample total $T$ is sufficient and $\mathbb E_p[T/n]=np/n=p$.`,String.raw`Tổng mẫu $T$ đủ và $\mathbb E_p[T/n]=np/n=p$.`),b(String.raw`Let U be any unbiased estimator of p with finite variance. By sufficiency, $\mathbb E[U\mid T]$ is an unbiased function of T.`,String.raw`Cho U là ước lượng p bất kỳ không chệch có phương sai hữu hạn. Theo tính đủ, $\mathbb E[U\mid T]$ là hàm không chệch của T.`),b(String.raw`Completeness of the Binomial$(n,p)$ total implies this function must equal the already unbiased $T/n$ almost surely.`,String.raw`Tính đầy đủ của tổng Binomial$(n,p)$ suy ra hàm này phải bằng $T/n$ không chệch đã biết h.c.`),b(String.raw`Rao–Blackwell gives $\operatorname{Var}(T/n)=\operatorname{Var}(\mathbb E[U\mid T])\le\operatorname{Var}(U)$ for every such U, proving the UMVU claim.`,String.raw`Rao–Blackwell cho $\operatorname{Var}(T/n)=\operatorname{Var}(\mathbb E[U\mid T])\le\operatorname{Var}(U)$ với mọi U như vậy, chứng minh khẳng định UMVU.`),b(String.raw`The unproved input is completeness of the binomial total for the full parameter family $p\in[0,1]$; sufficiency and unbiasedness are directly checked.`,String.raw`Tiền đề chưa chứng minh là tính đầy đủ của tổng nhị thức trên cả họ tham số $p\in[0,1]$; tính đủ và không chệch được kiểm tra trực tiếp.`)],
    companions:[
      {prompt:b(String.raw`For $n=4$ Bernoulli$(p)$ observations, estimate $p^2$ using $T=\sum_iX_i$. Verify unbiasedness of $T(T-1)/12$ and explain why it is UMVU assuming binomial completeness.`,String.raw`Với $n=4$ quan sát Bernoulli$(p)$, ước lượng $p^2$ bằng $T=\sum_iX_i$. Kiểm tra $T(T-1)/12$ không chệch và giải thích vì sao là UMVU nếu giả sử đầy đủ nhị thức.`),solution:[b(String.raw`For $T\sim\operatorname{Binomial}(4,p)$, the factorial moment is $\mathbb E[T(T-1)]=4\cdot3p^2=12p^2$.`,String.raw`Với $T\sim\operatorname{Binomial}(4,p)$, moment giai thừa là $\mathbb E[T(T-1)]=4\cdot3p^2=12p^2$.`),b(String.raw`Thus $A(T)=T(T-1)/12$ is unbiased for $p^2$ and is a function of the sufficient total.`,String.raw`Do đó $A(T)=T(T-1)/12$ không chệch cho $p^2$ và là hàm của tổng đủ.`),b(String.raw`For any unbiased finite-variance estimator U, $\mathbb E[U\mid T]$ is unbiased and no more variable; completeness makes it equal A(T), so A is UMVU.`,String.raw`Với mọi ước lượng U không chệch có phương sai hữu hạn, $\mathbb E[U\mid T]$ không chệch và ít biến thiên hơn; tính đầy đủ làm nó bằng A(T), nên A là UMVU.`)]},
      {prompt:b(String.raw`For three iid Poisson$(\lambda)$ counts, let $T=X_1+X_2+X_3$. Verify $T/3$ is UMVU for $\lambda$, assuming the standard completeness result for Poisson totals.`,String.raw`Với ba số đếm Poisson$(\lambda)$ iid, đặt $T=X_1+X_2+X_3$. Kiểm tra $T/3$ là UMVU cho $\lambda$, giả sử kết quả đầy đủ chuẩn của tổng Poisson.`),solution:[b(String.raw`The sum has distribution $\operatorname{Poisson}(3\lambda)$, so $\mathbb E[T/3]=3\lambda/3=\lambda$.`,String.raw`Tổng có phân phối $\operatorname{Poisson}(3\lambda)$, nên $\mathbb E[T/3]=3\lambda/3=\lambda$.`),b(String.raw`The joint likelihood factors through T, so T is sufficient; the Poisson-total completeness theorem is assumed.`,String.raw`Likelihood chung phân tích qua T nên T đủ; định lý đầy đủ của tổng Poisson được giả định.`),b(String.raw`Rao–Blackwellize any unbiased finite-variance estimator by T. Its conditional expectation remains unbiased with no larger variance, and completeness forces it to equal T/3; hence T/3 is UMVU.`,String.raw`Rao–Blackwell hóa mọi ước lượng không chệch có phương sai hữu hạn theo T. Kỳ vọng có điều kiện vẫn không chệch với phương sai không lớn hơn, còn tính đầy đủ buộc nó bằng T/3; vậy T/3 là UMVU.`)]},
      {prompt:b(String.raw`For two iid Bernoulli$(p)$ observations, $U=1_{\{X_1=1,X_2=0\}}$ estimates $p(1-p)$. Compute its Rao–Blackwellization given $T=X_1+X_2$ and its variance.`,String.raw`Với hai quan sát Bernoulli$(p)$ iid, $U=1_{\{X_1=1,X_2=0\}}$ ước lượng $p(1-p)$. Tính Rao–Blackwell hóa theo $T=X_1+X_2$ và phương sai.`),solution:[b(String.raw`The estimator U is unbiased because $P(X_1=1,X_2=0)=p(1-p)=q$.`,String.raw`Ước lượng U không chệch vì $P(X_1=1,X_2=0)=p(1-p)=q$.`),b(String.raw`If T=0 or 2, U=0; if T=1, the two ordered patterns are equiprobable and U is 1 on one, so $\mathbb E[U\mid T]=\frac12 1_{\{T=1\}}$.`,String.raw`Nếu T=0 hoặc 2 thì U=0; nếu T=1, hai thứ tự đồng xác suất và U bằng 1 ở một trường hợp, nên $\mathbb E[U\mid T]=\frac12 1_{\{T=1\}}$.`),b(String.raw`This conditional estimator has mean $(1/2)P(T=1)=q$ and variance $q/2-q^2$.`,String.raw`Ước lượng có điều kiện này có trung bình $(1/2)P(T=1)=q$ và phương sai $q/2-q^2$.`),b(String.raw`The original indicator has variance $q-q^2$, so conditioning reduces variance by $q/2$. Completeness of the Binomial$(2,p)$ total then yields the UMVU conclusion.`,String.raw`Chỉ báo ban đầu có phương sai $q-q^2$, nên điều kiện hóa giảm phương sai $q/2$. Tính đầy đủ của tổng Binomial$(2,p)$ sau đó cho kết luận UMVU.`)]}
    ],
    reviewNote:`The UMVU proof compares against every unbiased finite-variance estimator, using sufficiency for Rao–Blackwell and completeness for uniqueness. The binomial-completeness theorem is expressly named as assumed, not proved.`,
    sourceIds:['p-mit18655']
  },

  'm2-w047-e1': {
    title:b('Build a randomized most-powerful test','Dựng kiểm định mạnh nhất có ngẫu nhiên hóa'),
    application:b(String.raw`For two simple hypotheses, rank outcomes by their likelihood ratios and spend the level budget from largest to smallest, randomizing only at a tied boundary when needed.`,String.raw`Với hai giả thuyết đơn, xếp kết quả theo tỷ số likelihood rồi dùng ngân sách mức từ lớn xuống nhỏ, chỉ ngẫu nhiên hóa tại biên nếu cần.`),
    formula:b(String.raw`For simple $H_0:P_0$ versus simple $H_1:P_1$, a most-powerful level-$\alpha$ test rejects when $\Lambda(x)=f_1(x)/f_0(x)>k$, accepts when it is below k, and may randomize on $\Lambda=k$ so $\mathbb E_0\phi=\alpha$. Test functions satisfy $0\le\phi\le1$.`,String.raw`Với $H_0:P_0$ đơn so với $H_1:P_1$ đơn, kiểm định mạnh nhất mức $\alpha$ bác bỏ khi $\Lambda(x)=f_1(x)/f_0(x)>k$, chấp nhận khi nhỏ hơn k, và có thể ngẫu nhiên hóa tại $\Lambda=k$ để $\mathbb E_0\phi=\alpha$. Hàm kiểm định thỏa $0\le\phi\le1$.`),
    steps:[b(String.raw`Under the null, $P_0(X=1)=.2$; rejecting exactly at $X=1$ therefore uses size $.2$.`,String.raw`Dưới giả thuyết không, $P_0(X=1)=.2$; chỉ bác bỏ tại $X=1$ nên dùng mức $.2$.`),b(String.raw`The likelihood ratios are $\Lambda(1)=.8/.2=4$ and $\Lambda(0)=.2/.8=1/4$, ranking outcome 1 first.`,String.raw`Các tỷ số likelihood là $\Lambda(1)=.8/.2=4$ và $\Lambda(0)=.2/.8=1/4$, nên xếp kết quả 1 trước.`),b(String.raw`The size budget is exactly exhausted at outcome 1, so no randomization at the remaining outcome is required.`,String.raw`Ngân sách mức được dùng hết chính xác tại kết quả 1, nên không cần ngẫu nhiên hóa ở kết quả còn lại.`),b(String.raw`Under the alternative, this rejection event has probability $.8$, giving power $.8$.`,String.raw`Dưới đối thuyết, biến cố bác bỏ này có xác suất $.8$, nên lực kiểm định bằng $.8$.`)],
    primarySolution:[b(String.raw`Compute likelihood ratios: $\Lambda(1)=.8/.2=4$ and $\Lambda(0)=.2/.8=.25$.`,String.raw`Tính tỷ số likelihood: $\Lambda(1)=.8/.2=4$ và $\Lambda(0)=.2/.8=.25$.`),b(String.raw`Since outcome 1 has the larger ratio, reject there first; its null probability is $.2$, exactly the allowed level.`,String.raw`Vì kết quả 1 có tỷ số lớn hơn, bác bỏ tại đó trước; xác suất dưới giả thuyết không là $.2$, đúng mức cho phép.`),b(String.raw`Set $\phi(1)=1,\phi(0)=0$. Then size is $\mathbb E_0\phi=.2$.`,String.raw`Đặt $\phi(1)=1,\phi(0)=0$. Khi đó mức là $\mathbb E_0\phi=.2$.`),b(String.raw`Its power is $\mathbb E_1\phi=P_1(X=1)=.8$; the Neyman–Pearson lemma makes it most powerful. No boundary randomization is needed.`,String.raw`Lực kiểm định là $\mathbb E_1\phi=P_1(X=1)=.8$; bổ đề Neyman–Pearson cho tính mạnh nhất. Không cần ngẫu nhiên hóa biên.`)],
    companions:[
      {prompt:b(String.raw`Under $H_0$, $X\sim\operatorname{Bernoulli}(.2)$; under $H_1$, $X\sim\operatorname{Bernoulli}(.6)$. Construct an exact level $.5$ most-powerful test, including its boundary randomization and power.`,String.raw`Dưới $H_0$, $X\sim\operatorname{Bernoulli}(.2)$; dưới $H_1$, $X\sim\operatorname{Bernoulli}(.6)$. Dựng kiểm định mạnh nhất mức $.5$ chính xác, gồm ngẫu nhiên hóa biên và lực.`),solution:[b(String.raw`The ratios are $\Lambda(1)=.6/.2=3$ and $\Lambda(0)=.4/.8=.5$, so reject at $X=1$ first; this spends size $.2$.`,String.raw`Tỷ số là $\Lambda(1)=.6/.2=3$ và $\Lambda(0)=.4/.8=.5$, nên bác bỏ tại $X=1$ trước; dùng mức $.2$.`),b(String.raw`The remaining null size is $.5-.2=.3$, and $P_0(X=0)=.8$, so randomize at zero with probability $\gamma=.3/.8=3/8$.`,String.raw`Mức dưới giả thuyết không còn $.5-.2=.3$, còn $P_0(X=0)=.8$, nên ngẫu nhiên hóa tại 0 với xác suất $\gamma=.3/.8=3/8$.`),b(String.raw`The power is $.6+.4(3/8)=.6+.15=.75$.`,String.raw`Lực kiểm định là $.6+.4(3/8)=.6+.15=.75$.`),b(String.raw`This uses all null size and randomizes only on the lower likelihood-ratio boundary.`,String.raw`Kiểm định dùng hết mức dưới giả thuyết không và chỉ ngẫu nhiên hóa tại biên tỷ số thấp hơn.`)]},
      {prompt:b(String.raw`A three-outcome experiment has null probabilities $(.5,.3,.2)$ and alternative probabilities $(.2,.3,.5)$. Find the most-powerful test of exact size $.4$ and its power.`,String.raw`Thí nghiệm ba kết quả có xác suất không $(.5,.3,.2)$ và xác suất đối $(.2,.3,.5)$. Tìm kiểm định mạnh nhất mức $.4$ chính xác và lực.`),solution:[b(String.raw`The likelihood ratios for outcomes 1,2,3 are $.2/.5=.4$, $.3/.3=1$, and $.5/.2=2.5$. Rank outcome 3 first, then outcome 2.`,String.raw`Tỷ số likelihood của kết quả 1,2,3 lần lượt là $.2/.5=.4$, $.3/.3=1$, $.5/.2=2.5$. Xếp kết quả 3 trước, rồi kết quả 2.`),b(String.raw`Reject on outcome 3, using null size $.2$. The remaining $.2$ requires rejecting on outcome 2 with probability $.2/.3=2/3$.`,String.raw`Bác bỏ tại kết quả 3, dùng mức không $.2$. Phần $.2$ còn lại đòi bác bỏ kết quả 2 với xác suất $.2/.3=2/3$.`),b(String.raw`Power is $.5+(2/3)(.3)=.7$, and null size is $.2+(2/3)(.3)=.4$.`,String.raw`Lực kiểm định là $.5+(2/3)(.3)=.7$, còn mức không là $.2+(2/3)(.3)=.4$.`)]},
      {prompt:b(String.raw`For three outcomes, let null probabilities be $(.4,.35,.25)$ and alternative probabilities $(.1,.2,.7)$. Construct an exact size $.425$ likelihood-ratio test and compute power.`,String.raw`Với ba kết quả, xác suất không là $(.4,.35,.25)$ và xác suất đối $(.1,.2,.7)$. Dựng kiểm định tỷ số likelihood mức $.425$ chính xác và tính lực.`),solution:[b(String.raw`The ratios are $.1/.4=.25$, $.2/.35=4/7$, and $.7/.25=2.8$, so outcome 3 is first and outcome 2 second.`,String.raw`Tỷ số lần lượt là $.1/.4=.25$, $.2/.35=4/7$, và $.7/.25=2.8$, nên kết quả 3 đứng đầu rồi đến kết quả 2.`),b(String.raw`Reject on outcome 3 for null size $.25$, then reject on outcome 2 with probability $.175/.35=1/2$ to reach $.425$.`,String.raw`Bác bỏ kết quả 3 với mức không $.25$, rồi bác bỏ kết quả 2 với xác suất $.175/.35=1/2$ để đạt $.425$.`),b(String.raw`The power is $.7+(1/2)(.2)=.8$, and the test attains the prescribed null size.`,String.raw`Lực kiểm định là $.7+(1/2)(.2)=.8$, và kiểm định đạt đúng mức không đã cho.`)]}
    ],
    reviewNote:`For the primary pair the high-ratio outcome exactly uses the level, so no randomization is needed. Companion randomization probabilities are computed from the remaining null mass, then power is evaluated under the alternative.`,
    sourceIds:['p-mit18655']
  },

  'm2-w047-e2': {
    title:b('Prove the Neyman–Pearson inequality','Chứng minh bất đẳng thức Neyman–Pearson'),
    application:b(String.raw`Compare a competing test pointwise with the likelihood-ratio rule, then integrate the signed comparison under one common dominating measure.`,String.raw`So sánh kiểm định cạnh tranh theo từng điểm với quy tắc tỷ số likelihood, rồi tích phân bất đẳng thức theo một độ đo trội chung.`),
    formula:b(String.raw`For simple hypotheses with densities $f_0,f_1$ relative to a common measure, let $0\le\phi,\phi^*\le1$ and choose $\phi^*=1$ where $f_1>kf_0$, $\phi^*=0$ where $f_1<kf_0$, with arbitrary boundary randomization where equal. Then $(\phi^*-\phi)(f_1-kf_0)\ge0$ pointwise. If $\mathbb E_0\phi^*=\alpha$, $\mathbb E_0\phi\le\alpha$, and $k\ge0$, integration gives $\mathbb E_1\phi^*\ge\mathbb E_1\phi$.`,String.raw`Với giả thuyết đơn có mật độ $f_0,f_1$ theo cùng độ đo, lấy $0\le\phi,\phi^*\le1$ và chọn $\phi^*=1$ khi $f_1>kf_0$, $\phi^*=0$ khi $f_1<kf_0$, ngẫu nhiên hóa tùy ý tại biên bằng nhau. Khi đó $(\phi^*-\phi)(f_1-kf_0)\ge0$ từng điểm. Nếu $\mathbb E_0\phi^*=\alpha$, $\mathbb E_0\phi\le\alpha$, $k\ge0$, tích phân cho $\mathbb E_1\phi^*\ge\mathbb E_1\phi$.`),
    steps:[b(String.raw`Where $f_1-kf_0>0$, the LR rule has $\phi^*=1$, so $\phi^*-\phi\ge0$ because a test never exceeds 1.`,String.raw`Ở nơi $f_1-kf_0>0$, quy tắc tỷ số có $\phi^*=1$, nên $\phi^*-\phi\ge0$ vì kiểm định không vượt 1.`),b(String.raw`Where $f_1-kf_0<0$, it has $\phi^*=0$, so both factors are nonpositive and their product is nonnegative.`,String.raw`Ở nơi $f_1-kf_0<0$, quy tắc có $\phi^*=0$, nên cả hai thừa số không dương và tích không âm.`),b(String.raw`Where $f_1=kf_0$, the second factor is zero, so boundary randomization does not alter the pointwise inequality.`,String.raw`Ở nơi $f_1=kf_0$, thừa số thứ hai bằng không, nên ngẫu nhiên hóa biên không làm đổi bất đẳng thức từng điểm.`),b(String.raw`Integrating gives $(\mathbb E_1\phi^*-\mathbb E_1\phi)-k(\mathbb E_0\phi^*-\mathbb E_0\phi)\ge0$.`,String.raw`Tích phân cho $(\mathbb E_1\phi^*-\mathbb E_1\phi)-k(\mathbb E_0\phi^*-\mathbb E_0\phi)\ge0$.`),b(String.raw`Because $\mathbb E_0\phi^*-\mathbb E_0\phi\ge0$ and $k\ge0$, the power difference is nonnegative.`,String.raw`Vì $\mathbb E_0\phi^*-\mathbb E_0\phi\ge0$ và $k\ge0$, hiệu power không âm.`)],
    primarySolution:[b(String.raw`On $\{f_1>kf_0\}$, $\phi^*=1$ and $\phi\le1$, so both factors in $(\phi^*-\phi)(f_1-kf_0)$ are nonnegative.`,String.raw`Trên $\{f_1>kf_0\}$, $\phi^*=1$ và $\phi\le1$, nên hai thừa số trong $(\phi^*-\phi)(f_1-kf_0)$ không âm.`),b(String.raw`On $\{f_1<kf_0\}$, $\phi^*=0$ and $\phi\ge0$, so both factors are nonpositive; at equality the product is zero.`,String.raw`Trên $\{f_1<kf_0\}$, $\phi^*=0$ và $\phi\ge0$, nên cả hai thừa số không dương; tại đẳng thức tích bằng không.`),b(String.raw`Thus the pointwise product is nonnegative everywhere, including the randomized LR boundary.`,String.raw`Vậy tích từng điểm không âm ở mọi nơi, kể cả biên LR được ngẫu nhiên hóa.`),b(String.raw`Integrate against the common measure to obtain $\mathbb E_1\phi^*-\mathbb E_1\phi\ge k(\mathbb E_0\phi^*-\mathbb E_0\phi)$.`,String.raw`Tích phân theo độ đo chung cho $\mathbb E_1\phi^*-\mathbb E_1\phi\ge k(\mathbb E_0\phi^*-\mathbb E_0\phi)$.`),b(String.raw`Since the candidate has size $\alpha$ and the competitor has size at most $\alpha$, the right side is nonnegative; hence the candidate is most powerful for this simple alternative.`,String.raw`Vì kiểm định ứng viên có mức $\alpha$ còn kiểm định cạnh tranh có mức không quá $\alpha$, vế phải không âm; do đó ứng viên mạnh nhất cho đối thuyết đơn này.`)],
    companions:[
      {prompt:b(String.raw`For outcomes 1,2,3, let $f_0=(.5,.3,.2)$ and $f_1=(.2,.3,.5)$. At size $.4$, take $\phi^*=(0,2/3,1)$ and competitor $\phi=(.8,0,0)$. Verify the integrated NP inequality with $k=1$.`,String.raw`Với kết quả 1,2,3, cho $f_0=(.5,.3,.2)$ và $f_1=(.2,.3,.5)$. Ở mức $.4$, lấy $\phi^*=(0,2/3,1)$ và đối thủ $\phi=(.8,0,0)$. Kiểm tra bất đẳng thức NP tích phân với $k=1$.`),solution:[b(String.raw`The candidate size is $.3(2/3)+.2=.4$; the competitor size is $.5(.8)=.4$.`,String.raw`Mức ứng viên là $.3(2/3)+.2=.4$; mức đối thủ là $.5(.8)=.4$.`),b(String.raw`Their powers are $\mathbb E_1\phi^*=(.3)(2/3)+.5=.7$ and $\mathbb E_1\phi=(.2)(.8)=.16$, so the difference is $.54$.`,String.raw`Power lần lượt là $\mathbb E_1\phi^*=(.3)(2/3)+.5=.7$ và $\mathbb E_1\phi=(.2)(.8)=.16$, nên hiệu là $.54$.`),b(String.raw`The pointwise products $(\phi^*-\phi)(f_1-f_0)$ are $.24,0,.30$, summing to $.54\ge0=k(.4-.4)$, as the inequality predicts.`,String.raw`Các tích từng điểm $(\phi^*-\phi)(f_1-f_0)$ là $.24,0,.30$, tổng $.54\ge0=k(.4-.4)$, đúng như bất đẳng thức dự đoán.`)]},
      {prompt:b(String.raw`For $H_0:p=.4$ against $H_1:p=.7$ from one Bernoulli observation, let $\phi^*(1)=1,\phi^*(0)=0$ and competitor $\phi(1)=.5,\phi(0)=.2$. With $k=1$, verify the size and power inequality.`,String.raw`Với $H_0:p=.4$ so với $H_1:p=.7$ qua một quan sát Bernoulli, cho $\phi^*(1)=1,\phi^*(0)=0$ và đối thủ $\phi(1)=.5,\phi(0)=.2$. Với $k=1$, kiểm tra bất đẳng thức mức và lực.`),solution:[b(String.raw`The candidate size is $.4$; the competitor size is $.4(.5)+.6(.2)=.32$, so the candidate uses no less size.`,String.raw`Mức ứng viên là $.4$; mức đối thủ là $.4(.5)+.6(.2)=.32$, nên ứng viên dùng mức không ít hơn.`),b(String.raw`The powers are $.7$ and $.7(.5)+.3(.2)=.41$, giving difference $.29$.`,String.raw`Các power là $.7$ và $.7(.5)+.3(.2)=.41$, cho hiệu $.29$.`),b(String.raw`The likelihood ratios are $1.75$ at 1 and $.5$ at 0, so k=1 defines $\phi^*$. The inequality requires power difference at least $1(.4-.32)=.08$, and $.29\ge.08$.`,String.raw`Tỷ số likelihood là $1.75$ tại 1 và $.5$ tại 0, nên k=1 xác định $\phi^*$. Bất đẳng thức đòi hiệu power ít nhất $1(.4-.32)=.08$, và $.29\ge.08$.`)]},
      {prompt:b(String.raw`For $H_0:N(0,1)$ versus $H_1:N(1,1)$, the LR test $\phi^*=1_{\{X>1\}}$ has size $1-\Phi(1)$. Compare its power with the feasible competitor $\phi=1_{\{X>2\}}$.`,String.raw`Với $H_0:N(0,1)$ so với $H_1:N(1,1)$, kiểm định LR $\phi^*=1_{\{X>1\}}$ có mức $1-\Phi(1)$. So sánh power với đối thủ khả thi $\phi=1_{\{X>2\}}$.`),solution:[b(String.raw`The likelihood ratio is $f_1(x)/f_0(x)=e^{x-1/2}$, increasing in x; the cutoff x=1 therefore gives the LR test.`,String.raw`Tỷ số likelihood là $f_1(x)/f_0(x)=e^{x-1/2}$, tăng theo x; ngưỡng x=1 cho kiểm định LR.`),b(String.raw`Its null size is $P_0(X>1)=1-\Phi(1)$; the competitor has smaller size $P_0(X>2)=1-\Phi(2)$.`,String.raw`Mức không của nó là $P_0(X>1)=1-\Phi(1)$; đối thủ có mức nhỏ hơn $P_0(X>2)=1-\Phi(2)$.`),b(String.raw`Under the alternative, powers are $P_1(X>1)=1/2$ and $P_1(X>2)=1-\Phi(1)$, respectively. Since $1/2>1-\Phi(1)$, the LR test is more powerful at the permitted level.`,String.raw`Dưới đối thuyết, power lần lượt là $P_1(X>1)=1/2$ và $P_1(X>2)=1-\Phi(1)$. Vì $1/2>1-\Phi(1)$, kiểm định LR mạnh hơn trong mức cho phép.`)]}
    ],
    reviewNote:`The proof needs a common dominating measure, randomized tests in [0,1], an exact-size LR rule, and nonnegative k. Integrating the pointwise inequality gives the claimed power ordering for simple-versus-simple hypotheses.`,
    sourceIds:['p-mit18655']
  },

  'm2-w047-e3': {
    title:b('Derive a likelihood-ratio ordering','Suy thứ tự tỷ số likelihood'),
    application:b(String.raw`For a binomial sample, cancel the common combinatorial coefficient and examine the one-count likelihood-ratio factor to identify which counts should be rejected first.`,String.raw`Với mẫu nhị thức, triệt tiêu hệ số tổ hợp chung rồi xét thừa số tỷ số likelihood khi tăng một số đếm để xác định số đếm nào cần bác bỏ trước.`),
    formula:b(String.raw`For $S\sim\operatorname{Binomial}(n,p)$ and simple hypotheses $H_0:p=p_0$ versus $H_1:p=p_1$, with $0<p_0<p_1<1$, $\Lambda(S)=(p_1/p_0)^S((1-p_1)/(1-p_0))^{n-S}$ and $\Lambda(S+1)/\Lambda(S)=p_1(1-p_0)/(p_0(1-p_1))>1$. The NP rejection region is an upper tail, with boundary randomization if needed for exact level.`,String.raw`Với $S\sim\operatorname{Binomial}(n,p)$ và giả thuyết đơn $H_0:p=p_0$ so với $H_1:p=p_1$, $0<p_0<p_1<1$, ta có $\Lambda(S)=(p_1/p_0)^S((1-p_1)/(1-p_0))^{n-S}$ và $\Lambda(S+1)/\Lambda(S)=p_1(1-p_0)/(p_0(1-p_1))>1$. Miền bác bỏ NP là đuôi trên, ngẫu nhiên hóa tại biên nếu cần đúng mức.`),
    steps:[b(String.raw`The two pmfs share the coefficient $\binom nS$, which cancels in their likelihood ratio.`,String.raw`Hai pmf có chung hệ số $\binom nS$, hệ số này triệt tiêu trong tỷ số likelihood.`),b(String.raw`The remaining ratio is $(p_1/p_0)^S((1-p_1)/(1-p_0))^{n-S}$.`,String.raw`Tỷ số còn lại là $(p_1/p_0)^S((1-p_1)/(1-p_0))^{n-S}$.`),b(String.raw`Increasing S by one multiplies it by $p_1(1-p_0)/(p_0(1-p_1))$, which exceeds 1 exactly because $p_1>p_0$.`,String.raw`Tăng S thêm một nhân tỷ số với $p_1(1-p_0)/(p_0(1-p_1))$, lớn hơn 1 đúng vì $p_1>p_0$.`),b(String.raw`Neyman–Pearson therefore orders larger success counts first and rejects for $S\ge c$, possibly randomizing at c to match a discrete size target.`,String.raw`Vì vậy Neyman–Pearson xếp số lần thành công lớn trước và bác bỏ khi $S\ge c$, có thể ngẫu nhiên hóa tại c để khớp mức rời rạc.`)],
    primarySolution:[b(String.raw`Under $p_0$ and $p_1$, the binomial pmfs are $\binom nS p_j^S(1-p_j)^{n-S}$ for $j=0,1$.`,String.raw`Dưới $p_0$ và $p_1$, pmf nhị thức là $\binom nS p_j^S(1-p_j)^{n-S}$ với $j=0,1$.`),b(String.raw`Canceling the shared coefficient gives $\Lambda(S)=(p_1/p_0)^S((1-p_1)/(1-p_0))^{n-S}$.`,String.raw`Triệt tiêu hệ số chung cho $\Lambda(S)=(p_1/p_0)^S((1-p_1)/(1-p_0))^{n-S}$.`),b(String.raw`Its adjacent ratio is $\Lambda(S+1)/\Lambda(S)=p_1(1-p_0)/(p_0(1-p_1))>1$, hence the LR increases with S.`,String.raw`Tỷ số liên tiếp là $\Lambda(S+1)/\Lambda(S)=p_1(1-p_0)/(p_0(1-p_1))>1$, nên LR tăng theo S.`),b(String.raw`The simple-versus-simple NP rule rejects at large S, with randomization at a boundary count if the null tail probabilities cannot attain the requested level exactly.`,String.raw`Quy tắc NP đơn-đơn bác bỏ khi S lớn, ngẫu nhiên hóa tại số đếm biên nếu xác suất đuôi không đạt chính xác mức yêu cầu.`)],
    companions:[
      {prompt:b(String.raw`For $n=3$, test $p_0=.2$ against $p_1=.5$ at exact size $.2$. Derive the LR ordering, boundary randomization, and power.`,String.raw`Với $n=3$, kiểm định $p_0=.2$ so với $p_1=.5$ ở mức $.2$ chính xác. Suy thứ tự LR, ngẫu nhiên hóa biên và power.`),solution:[b(String.raw`The adjacent LR factor is $.5(.8)/[.2(.5)]=4>1$, so reject larger S first.`,String.raw`Thừa số LR liên tiếp là $.5(.8)/[.2(.5)]=4>1$, nên bác bỏ số S lớn trước.`),b(String.raw`Under the null, $P(S=3)=.008$ and $P(S=2)=3(.2)^2(.8)=.096$; these total $.104$. At $S=1$, the null mass is $3(.2)(.8)^2=.384$.`,String.raw`Dưới giả thuyết không, $P(S=3)=.008$ và $P(S=2)=3(.2)^2(.8)=.096$, tổng $.104$. Tại $S=1$, khối lượng không là $3(.2)(.8)^2=.384$.`),b(String.raw`Use the remaining $.096$ by rejecting at $S=1$ with probability $.096/.384=1/4$, attaining size $.2$.`,String.raw`Dùng $.096$ còn lại bằng cách bác bỏ tại $S=1$ với xác suất $.096/.384=1/4$, đạt mức $.2$.`),b(String.raw`Under $p_1=.5$, the masses at S=3,2,1 are $.125,.375,.375$, so power is $.125+.375+(1/4)(.375)=.59375$.`,String.raw`Dưới $p_1=.5$, khối lượng tại S=3,2,1 là $.125,.375,.375$, nên power là $.125+.375+(1/4)(.375)=.59375$.`)]},
      {prompt:b(String.raw`For $n=2$, compare $p_0=.5$ to $p_1=.75$ at exact size $.5$. Find the randomized cutoff test and its power.`,String.raw`Với $n=2$, so sánh $p_0=.5$ với $p_1=.75$ ở mức $.5$ chính xác. Tìm kiểm định ngưỡng ngẫu nhiên và power.`),solution:[b(String.raw`The adjacent LR factor is $.75(.5)/[.5(.25)]=3$, so counts S=2 then S=1 rank highest.`,String.raw`Thừa số LR liên tiếp là $.75(.5)/[.5(.25)]=3$, nên số đếm S=2 rồi S=1 được xếp cao nhất.`),b(String.raw`Under the null, $P(S=2)=1/4$; the remaining size is $1/4$, while $P(S=1)=1/2$. Randomize at S=1 with probability $1/2$.`,String.raw`Dưới giả thuyết không, $P(S=2)=1/4$; mức còn lại là $1/4$, còn $P(S=1)=1/2$. Ngẫu nhiên hóa tại S=1 với xác suất $1/2$.`),b(String.raw`The alternative power is $P_{.75}(S=2)+(1/2)P_{.75}(S=1)=.75^2+(1/2)(2\cdot.75\cdot.25)=.5625+.1875=.75$.`,String.raw`Power đối thuyết là $P_{.75}(S=2)+(1/2)P_{.75}(S=1)=.75^2+(1/2)(2\cdot.75\cdot.25)=.5625+.1875=.75$.`)]},
      {prompt:b(String.raw`For $n=3$, test $p_0=.75$ against $p_1=.25$ at exact size $.1$. Determine the LR direction, boundary randomization, and power.`,String.raw`Với $n=3$, kiểm định $p_0=.75$ so với $p_1=.25$ ở mức $.1$ chính xác. Xác định hướng LR, ngẫu nhiên hóa biên và power.`),solution:[b(String.raw`The adjacent LR factor is $.25(.25)/[.75(.75)]=1/9<1$, so smaller success counts have larger likelihood ratios.`,String.raw`Thừa số LR liên tiếp là $.25(.25)/[.75(.75)]=1/9<1$, nên số lần thành công nhỏ có LR lớn hơn.`),b(String.raw`Under the null, $P(S=0)=.25^3=.015625$ and $P(S=1)=3(.75)(.25)^2=.140625$. Reject always at zero and at one with probability $(.1-.015625)/.140625=.6$.`,String.raw`Dưới giả thuyết không, $P(S=0)=.25^3=.015625$ và $P(S=1)=3(.75)(.25)^2=.140625$. Luôn bác bỏ tại 0 và bác bỏ tại 1 với xác suất $(.1-.015625)/.140625=.6$.`),b(String.raw`Under $p_1=.25$, $P(S=0)=.421875$ and $P(S=1)=3(.25)(.75)^2=.421875$, so power is $.421875+.6(.421875)=.675$.`,String.raw`Dưới $p_1=.25$, $P(S=0)=.421875$ và $P(S=1)=3(.25)(.75)^2=.421875$, nên power là $.421875+.6(.421875)=.675$.`)]}
    ],
    reviewNote:`The monotonicity conclusion assumes interior probabilities so the binomial likelihood ratio is finite. If the alternative probability is smaller, the LR decreases and the NP region is a lower tail; discrete levels may require boundary randomization.`,
    sourceIds:['p-mit18655']
  },

  'm2-w047-e4': {
    title:b('Counterexample: composite alternatives','Phản ví dụ: giả thuyết thay thế ghép'),
    application:b(String.raw`The Neyman–Pearson lemma optimizes for one fixed alternative distribution. Opposite directions in a two-sided alternative can demand incompatible rejection regions.`,String.raw`Bổ đề Neyman–Pearson tối ưu cho một phân phối đối thuyết cố định. Các hướng đối nhau trong đối thuyết hai phía có thể đòi miền bác bỏ không tương thích.`),
    formula:b(String.raw`The NP lemma is for one simple $P_0$ versus one simple $P_1$. For $X\sim N(\mu,1)$, testing $H_0:\mu=0$ against $H_1:\mu\ne0$ at level $.05$, the unique MP test for $\mu=1$ rejects when $X>z_{.95}\approx1.645$, while for $\mu=-1$ it rejects when $X<-1.645$. These regions differ, so no test is generally MP for both; NP alone gives no unrestricted two-sided UMP result.`,String.raw`Bổ đề NP dành cho một $P_0$ đơn so với một $P_1$ đơn. Với $X\sim N(\mu,1)$, kiểm định $H_0:\mu=0$ so với $H_1:\mu\ne0$ ở mức $.05$, kiểm định mạnh nhất duy nhất cho $\mu=1$ bác bỏ khi $X>z_{.95}\approx1.645$, còn với $\mu=-1$ bác bỏ khi $X<-1.645$. Hai miền này khác nhau nên nói chung không có kiểm định mạnh nhất cho cả hai; NP tự nó không cho kết quả UMP hai phía không hạn chế.`),
    steps:[b(String.raw`NP compares one simple null and one simple alternative, so fix each alternative value separately before applying it.`,String.raw`NP so một giả thuyết không đơn và một đối thuyết đơn, nên phải cố định riêng từng giá trị đối thuyết trước khi áp dụng.`),b(String.raw`Under $N(0,1)$ versus $N(1,1)$, the likelihood ratio is $e^{x-1/2}$, increasing in x; the level-.05 MP region is $x>1.645$.`,String.raw`Với $N(0,1)$ so với $N(1,1)$, tỷ số likelihood là $e^{x-1/2}$, tăng theo x; miền mạnh nhất mức .05 là $x>1.645$.`),b(String.raw`Against $N(-1,1)$, the ratio is $e^{-x-1/2}$, decreasing in x; its level-.05 MP region is $x<-1.645$.`,String.raw`So với $N(-1,1)$, tỷ số là $e^{-x-1/2}$, giảm theo x; miền mạnh nhất mức .05 là $x<-1.645$.`),b(String.raw`Both tests are uniquely MP up to null sets, and their rejection regions are disjoint with positive-probability differences under the null. No single test can attain both pointwise power maxima.`,String.raw`Cả hai kiểm định mạnh nhất duy nhất ngoài tập không, và miền bác bỏ khác nhau trên các miền có xác suất dương dưới giả thuyết không. Không kiểm định đơn nào đạt đồng thời cả hai cực đại power.`),b(String.raw`A one-sided UMP theorem can follow from monotone likelihood ratio under its own conditions; symmetry or NP alone does not prove unrestricted two-sided UMP.`,String.raw`Định lý UMP một phía có thể suy ra từ tỷ số likelihood đơn điệu dưới các điều kiện riêng; đối xứng hay NP đơn thuần không chứng minh UMP hai phía không hạn chế.`)],
    primarySolution:[b(String.raw`The alternative $H_1:\mu\ne0$ is composite, whereas the NP lemma addresses a fixed simple alternative.`,String.raw`Đối thuyết $H_1:\mu\ne0$ là phức hợp, trong khi bổ đề NP xét một đối thuyết đơn cố định.`),b(String.raw`For the simple alternative $\mu=1$, $f_1(x)/f_0(x)=e^{x-1/2}$, so the unique level-.05 MP test rejects in the upper tail $x>1.645$.`,String.raw`Với đối thuyết đơn $\mu=1$, $f_1(x)/f_0(x)=e^{x-1/2}$, nên kiểm định mạnh nhất mức .05 duy nhất bác bỏ ở đuôi trên $x>1.645$.`),b(String.raw`For $\mu=-1$, $f_{-1}(x)/f_0(x)=e^{-x-1/2}$, yielding the unique lower-tail MP test $x<-1.645$.`,String.raw`Với $\mu=-1$, $f_{-1}(x)/f_0(x)=e^{-x-1/2}$, cho kiểm định mạnh nhất duy nhất ở đuôi dưới $x<-1.645$.`),b(String.raw`Since these two level-.05 tests disagree on positive-measure regions, none is simultaneously most powerful against both alternatives. NP alone therefore cannot certify an unrestricted two-sided UMP test.`,String.raw`Vì hai kiểm định mức .05 này khác nhau trên miền có độ đo dương, không kiểm định nào mạnh nhất đồng thời cho cả hai đối thuyết. Do đó NP đơn thuần không chứng nhận kiểm định UMP hai phía không hạn chế.`)],
    companions:[
      {prompt:b(String.raw`For $X\sim N(\mu,1)$, test $H_0:\mu=2$ against the composite alternative $\mu\ne2$ at level $.05$. Write the unique MP regions for the simple alternatives $\mu=3$ and $\mu=1$ and explain the conflict.`,String.raw`Với $X\sim N(\mu,1)$, kiểm định $H_0:\mu=2$ so với đối thuyết phức hợp $\mu\ne2$ ở mức $.05$. Viết miền mạnh nhất duy nhất cho đối thuyết đơn $\mu=3$ và $\mu=1$, giải thích xung đột.`),solution:[b(String.raw`For $\mu=3$ versus the null mean 2, the normal likelihood ratio increases in x, so the level-.05 MP test rejects when $X>2+1.645=3.645$.`,String.raw`Với $\mu=3$ so với trung bình không 2, tỷ số chuẩn tăng theo x nên kiểm định mạnh nhất mức .05 bác bỏ khi $X>2+1.645=3.645$.`),b(String.raw`For $\mu=1$, the ratio decreases in x; the corresponding MP test rejects when $X<2-1.645=.355$.`,String.raw`Với $\mu=1$, tỷ số giảm theo x; kiểm định mạnh nhất tương ứng bác bỏ khi $X<2-1.645=.355$.`),b(String.raw`The upper- and lower-tail regions are distinct and each is unique for its simple alternative. Thus no test is MP for both, so NP does not supply a two-sided UMP test here.`,String.raw`Miền đuôi trên và đuôi dưới khác nhau, mỗi miền là duy nhất cho đối thuyết đơn tương ứng. Vì vậy không kiểm định nào mạnh nhất cho cả hai; NP không cung cấp UMP hai phía ở đây.`)]},
      {prompt:b(String.raw`For one Bernoulli observation, let $H_0:p=.5$ and consider alternatives $p=.8$ and $p=.2$ at exact size $.5$. Find each unique MP test and decide whether a common UMP test exists.`,String.raw`Với một quan sát Bernoulli, cho $H_0:p=.5$ và xét đối thuyết $p=.8$, $p=.2$ ở mức $.5$ chính xác. Tìm từng kiểm định mạnh nhất duy nhất và xác định có UMP chung không.`),solution:[b(String.raw`For alternative $.8$, the likelihood ratios at X=1 and X=0 are $1.6$ and $.4$, so the size-.5 MP test rejects exactly when X=1 and has power $.8$.`,String.raw`Với đối thuyết $.8$, tỷ số tại X=1 và X=0 là $1.6$ và $.4$, nên kiểm định mạnh nhất mức .5 bác bỏ đúng khi X=1 và có power $.8$.`),b(String.raw`For alternative $.2$, the ratios are $.4$ at X=1 and $1.6$ at X=0; it rejects exactly when X=0 and also has power $.8$.`,String.raw`Với đối thuyết $.2$, tỷ số là $.4$ tại X=1 và $1.6$ tại X=0; kiểm định bác bỏ đúng khi X=0 và cũng có power $.8$.`),b(String.raw`The unique MP rules are opposite and cannot be the same test function, so no level-.5 test is UMP over both alternatives.`,String.raw`Hai quy tắc mạnh nhất duy nhất đối nhau và không thể là cùng hàm kiểm định, nên không có kiểm định mức .5 UMP cho cả hai đối thuyết.`)]},
      {prompt:b(String.raw`With two Bernoulli trials, test $p_0=.5$ against both $p_1=.8$ and $p_1=.2$ at level $.25$. Find the two MP regions and show why they cannot define a common UMP test.`,String.raw`Với hai phép thử Bernoulli, kiểm định $p_0=.5$ so với cả $p_1=.8$ và $p_1=.2$ ở mức $.25$. Tìm hai miền mạnh nhất và chứng minh không thể có UMP chung.`),solution:[b(String.raw`Under the null, $S\sim\operatorname{Binomial}(2,.5)$ and each endpoint count 0 or 2 has probability $.25$. For alternative $.8$, the LR increases with S, so the size-.25 MP rule rejects at S=2.`,String.raw`Dưới giả thuyết không, $S\sim\operatorname{Binomial}(2,.5)$ và mỗi số đếm đầu mút 0 hoặc 2 có xác suất $.25$. Với đối thuyết $.8$, LR tăng theo S nên quy tắc mạnh nhất mức .25 bác bỏ tại S=2.`),b(String.raw`For alternative $.2$, LR decreases with S, so its unique size-.25 MP rule instead rejects at S=0.`,String.raw`Với đối thuyết $.2$, LR giảm theo S nên quy tắc mạnh nhất mức .25 duy nhất bác bỏ tại S=0.`),b(String.raw`These endpoint events are disjoint and both rules are unique under the null. No single test can equal both, hence no UMP test exists for this two-sided pair at that level.`,String.raw`Hai biến cố đầu mút rời nhau và cả hai quy tắc đều duy nhất dưới giả thuyết không. Không kiểm định nào bằng cả hai, nên không có UMP cho cặp hai phía này ở mức đó.`)]}
    ],
    reviewNote:`The primary is an explicit normal counterexample: for alpha=.05, the two simple alternatives +1 and -1 have different unique NP tails. This refutes a general UMP claim while leaving open one-sided UMP and restricted unbiased/invariant optimality results.`,
    sourceIds:['p-mit18655']
  },

  'm2-w047-e5': {
    title:b('Transfer: compare tests by size and power','Chuyển giao: so sánh kiểm định qua mức và power'),
    application:b(String.raw`For Bernoulli tests, express size and power as linear functions of the two rejection probabilities; allocate size to the outcome with larger likelihood ratio.`,String.raw`Với kiểm định Bernoulli, biểu diễn mức và lực tuyến tính theo hai xác suất bác bỏ; phân bổ mức cho kết quả có tỷ số likelihood lớn hơn.`),
    formula:b(String.raw`For $H_0:p_0=.3$ versus $H_1:p_1=.6$, with rejection probabilities $r_1=P(\text{reject}\mid X=1)$ and $r_0=P(\text{reject}\mid X=0)$, $\operatorname{size}=.3r_1+.7r_0$ and $\operatorname{power}=.6r_1+.4r_0$, where $0\le r_0,r_1\le1$. The LR values are 2 at 1 and $4/7$ at 0.`,String.raw`Với $H_0:p_0=.3$ so với $H_1:p_1=.6$, đặt $r_1=P(\text{bác bỏ}\mid X=1)$, $r_0=P(\text{bác bỏ}\mid X=0)$, ta có $\operatorname{size}=.3r_1+.7r_0$ và $\operatorname{power}=.6r_1+.4r_0$, với $0\le r_0,r_1\le1$. LR bằng 2 tại 1 và $4/7$ tại 0.`),
    steps:[b(String.raw`Under the null, X=1 and X=0 have probabilities $.3$ and $.7$, so the size is $.3r_1+.7r_0$.`,String.raw`Dưới giả thuyết không, X=1 và X=0 có xác suất $.3$ và $.7$, nên mức là $.3r_1+.7r_0$.`),b(String.raw`Under the alternative their probabilities are $.6$ and $.4$, giving power $.6r_1+.4r_0$.`,String.raw`Dưới đối thuyết, xác suất tương ứng là $.6$ và $.4$, cho power $.6r_1+.4r_0$.`),b(String.raw`The likelihood ratios are $.6/.3=2$ for X=1 and $.4/.7=4/7$ for X=0, so spend the size budget on X=1 first.`,String.raw`Tỷ số likelihood là $.6/.3=2$ tại X=1 và $.4/.7=4/7$ tại X=0, nên dùng ngân sách mức cho X=1 trước.`),b(String.raw`Taking $r_1=1,r_0=0$ attains size $.3$ and power $.6$. Any positive rejection probability at X=0 displaces more useful size from X=1, so cannot improve power.`,String.raw`Chọn $r_1=1,r_0=0$ đạt mức $.3$ và power $.6$. Bác bỏ thêm tại X=0 sẽ lấy ngân sách khỏi X=1 có ích hơn, nên không thể tăng power.`)],
    primarySolution:[b(String.raw`The size constraint is $.3r_1+.7r_0\le.3$, with each rejection probability in $[0,1]$.`,String.raw`Ràng buộc mức là $.3r_1+.7r_0\le.3$, với mỗi xác suất bác bỏ thuộc $[0,1]$.`),b(String.raw`Since the LR at X=1 is 2 and at X=0 is $4/7$, allocate size first to X=1.`,String.raw`Vì LR tại X=1 bằng 2, còn tại X=0 bằng $4/7$, hãy phân bổ mức cho X=1 trước.`),b(String.raw`Choose $(r_1,r_0)=(1,0)$. The size is $.3$ and power is $.6$.`,String.raw`Chọn $(r_1,r_0)=(1,0)$. Mức là $.3$ và power là $.6$.`),b(String.raw`For any feasible pair, $r_0\le(3/7)(1-r_1)$; hence power $\le.6r_1+(1.2/7)(1-r_1)\le.6$, confirming maximality.`,String.raw`Với mọi cặp khả thi, $r_0\le(3/7)(1-r_1)$; do đó power $\le.6r_1+(1.2/7)(1-r_1)\le.6$, xác nhận cực đại.`)],
    companions:[
      {prompt:b(String.raw`For one Bernoulli observation, test $p_0=.4$ against $p_1=.7$ at level at most $.5$. Find an optimal randomized test and its power.`,String.raw`Với một quan sát Bernoulli, kiểm định $p_0=.4$ so với $p_1=.7$ ở mức không quá $.5$. Tìm kiểm định ngẫu nhiên tối ưu và power.`),solution:[b(String.raw`The likelihood ratios are $.7/.4=1.75$ at X=1 and $.3/.6=.5$ at X=0, so reject at X=1 first.`,String.raw`Tỷ số likelihood là $.7/.4=1.75$ tại X=1 và $.3/.6=.5$ tại X=0, nên bác bỏ tại X=1 trước.`),b(String.raw`Rejecting whenever X=1 uses size $.4$; the remaining $.1$ null size is $.6r_0$, so choose $r_0=1/6$.`,String.raw`Luôn bác bỏ khi X=1 dùng mức $.4$; mức không $.1$ còn lại bằng $.6r_0$, nên chọn $r_0=1/6$.`),b(String.raw`The resulting size is $.4+.6(1/6)=.5$, and power is $.7+.3(1/6)=.75$.`,String.raw`Mức đạt được là $.4+.6(1/6)=.5$, còn power là $.7+.3(1/6)=.75$.`)]},
      {prompt:b(String.raw`Test one Bernoulli observation under $p_0=.25$ versus $p_1=.5$ at exact level $.4$. Find the boundary randomization probability and power.`,String.raw`Kiểm định một quan sát Bernoulli với $p_0=.25$ so với $p_1=.5$ ở mức $.4$ chính xác. Tìm xác suất ngẫu nhiên hóa biên và power.`),solution:[b(String.raw`The LR values are $.5/.25=2$ at X=1 and $.5/.75=2/3$ at X=0, so use X=1 first.`,String.raw`Các LR là $.5/.25=2$ tại X=1 và $.5/.75=2/3$ tại X=0, nên dùng X=1 trước.`),b(String.raw`Always rejecting at X=1 spends null size $.25$, leaving $.15$. Since $P_0(X=0)=.75$, set $r_0=.15/.75=.2$.`,String.raw`Luôn bác bỏ tại X=1 dùng mức không $.25$, còn $.15$. Vì $P_0(X=0)=.75$, đặt $r_0=.15/.75=.2$.`),b(String.raw`The size is $.25+.75(.2)=.4$ and power is $.5+.5(.2)=.6$.`,String.raw`Mức là $.25+.75(.2)=.4$ và power là $.5+.5(.2)=.6$.`)]},
      {prompt:b(String.raw`Under $p_0=.65$ versus lower alternative $p_1=.35$, find the most-powerful test with exact size $.2$ and compute power.`,String.raw`Dưới $p_0=.65$ so với đối thuyết thấp hơn $p_1=.35$, tìm kiểm định mạnh nhất mức $.2$ chính xác và tính power.`),solution:[b(String.raw`At X=0 the likelihood ratio is $.65/.35=13/7$, while at X=1 it is $.35/.65=7/13$; thus reject at X=0 first.`,String.raw`Tại X=0, tỷ số likelihood là $.65/.35=13/7$, còn tại X=1 là $.35/.65=7/13$; vì vậy bác bỏ tại X=0 trước.`),b(String.raw`Under the null, $P_0(X=0)=.35$. To spend only $.2$, randomize there with probability $r_0=.2/.35=4/7$ and set $r_1=0$.`,String.raw`Dưới giả thuyết không, $P_0(X=0)=.35$. Để dùng đúng $.2$, ngẫu nhiên hóa tại đó với xác suất $r_0=.2/.35=4/7$ và đặt $r_1=0$.`),b(String.raw`The size is $.35(4/7)=.2$ and the power is $.65(4/7)=13/35\approx.3714$.`,String.raw`Mức là $.35(4/7)=.2$ và power là $.65(4/7)=13/35\approx.3714$.`)]}
    ],
    reviewNote:`The primary optimization is over randomized tests with both rejection probabilities between zero and one. Likelihood-ratio ordering shows X=1 gets the size budget first; the stated linear bound verifies no feasible pair exceeds power .6.`,
    sourceIds:['p-mit18655']
  },

  'm2-w048-e1': {
    title:b('Compute score and information for Bernoulli','Tính score và thông tin Bernoulli'),
    application:b(String.raw`Differentiate the Bernoulli log likelihood and use the binomial variance to compute the score's mean and Fisher information.`,String.raw`Lấy đạo hàm log likelihood Bernoulli rồi dùng phương sai nhị thức để tính kỳ vọng score và thông tin Fisher.`),
    formula:b(String.raw`For iid $X_i\sim\operatorname{Bernoulli}(p)$ with $0<p<1$, put $S=\sum_iX_i$. Then $\ell(p)=S\log p+(n-S)\log(1-p)$, score $S_p=\ell'(p)=(S-np)/[p(1-p)]$, $\mathbb E_pS_p=0$, and $I_n(p)=\mathbb E_pS_p^2=n/[p(1-p)]$.`,String.raw`Với $X_i\sim\operatorname{Bernoulli}(p)$ iid, $0<p<1$, đặt $S=\sum_iX_i$. Khi đó $\ell(p)=S\log p+(n-S)\log(1-p)$, score $S_p=\ell'(p)=(S-np)/[p(1-p)]$, $\mathbb E_pS_p=0$, và $I_n(p)=\mathbb E_pS_p^2=n/[p(1-p)]$.`),
    steps:[b(String.raw`The likelihood is $p^S(1-p)^{n-S}$, so its log is $S\log p+(n-S)\log(1-p)$.`,String.raw`Likelihood là $p^S(1-p)^{n-S}$, nên log bằng $S\log p+(n-S)\log(1-p)$.`),b(String.raw`Differentiate: $\ell'(p)=S/p-(n-S)/(1-p)=(S-np)/[p(1-p)]$.`,String.raw`Lấy đạo hàm: $\ell'(p)=S/p-(n-S)/(1-p)=(S-np)/[p(1-p)]$.`),b(String.raw`Since $\mathbb E_pS=np$, the score has mean zero.`,String.raw`Vì $\mathbb E_pS=np$, score có kỳ vọng bằng không.`),b(String.raw`Because $S\sim\operatorname{Binomial}(n,p)$, $\operatorname{Var}(S)=np(1-p)$, and hence $\operatorname{Var}(S_p)=np(1-p)/[p^2(1-p)^2]=n/[p(1-p)]$.`,String.raw`Vì $S\sim\operatorname{Binomial}(n,p)$, $\operatorname{Var}(S)=np(1-p)$, nên $\operatorname{Var}(S_p)=np(1-p)/[p^2(1-p)^2]=n/[p(1-p)]$.`),b(String.raw`The score mean is zero, so its second moment equals its variance; that is the Fisher information.`,String.raw`Kỳ vọng score bằng không nên moment bậc hai bằng phương sai; đó là thông tin Fisher.`)],
    primarySolution:[b(String.raw`For an observed binary sample, the log likelihood is $\ell(p)=S\log p+(n-S)\log(1-p)$.`,String.raw`Với mẫu nhị phân quan sát được, log likelihood là $\ell(p)=S\log p+(n-S)\log(1-p)$.`),b(String.raw`Differentiating gives $S_p=S/p-(n-S)/(1-p)=(S-np)/[p(1-p)]$.`,String.raw`Lấy đạo hàm được $S_p=S/p-(n-S)/(1-p)=(S-np)/[p(1-p)]$.`),b(String.raw`The expectation is zero because $\mathbb E S=np$.`,String.raw`Kỳ vọng bằng không vì $\mathbb E S=np$.`),b(String.raw`Its variance is $\operatorname{Var}(S)/[p^2(1-p)^2]=np(1-p)/[p^2(1-p)^2]=n/[p(1-p)]$.`,String.raw`Phương sai là $\operatorname{Var}(S)/[p^2(1-p)^2]=np(1-p)/[p^2(1-p)^2]=n/[p(1-p)]$.`),b(String.raw`Since the score is centered, $I_n(p)=\mathbb E S_p^2=\operatorname{Var}(S_p)=n/[p(1-p)]$.`,String.raw`Vì score đã định tâm, $I_n(p)=\mathbb E S_p^2=\operatorname{Var}(S_p)=n/[p(1-p)]$.`)],
    companions:[
      {prompt:b(String.raw`For n iid Poisson$(\lambda)$ observations, $\lambda>0$, derive the score, verify mean zero, and compute Fisher information.`,String.raw`Với n quan sát Poisson$(\lambda)$ iid, $\lambda>0$, suy score, kiểm tra kỳ vọng bằng không và tính thông tin Fisher.`),solution:[b(String.raw`Writing $T=\sum_iX_i$, the log likelihood is $\ell(\lambda)=-n\lambda+T\log\lambda-\sum_i\log(X_i!)$.`,String.raw`Viết $T=\sum_iX_i$, log likelihood là $\ell(\lambda)=-n\lambda+T\log\lambda-\sum_i\log(X_i!)$.`),b(String.raw`The score is $S_\lambda=T/\lambda-n$. Since $\mathbb E T=n\lambda$, its mean is zero.`,String.raw`Score là $S_\lambda=T/\lambda-n$. Vì $\mathbb E T=n\lambda$, kỳ vọng score bằng không.`),b(String.raw`With $\operatorname{Var}(T)=n\lambda$, $I_n(\lambda)=\operatorname{Var}(T/\lambda)=n/\lambda$.`,String.raw`Với $\operatorname{Var}(T)=n\lambda$, $I_n(\lambda)=\operatorname{Var}(T/\lambda)=n/\lambda$.`)]},
      {prompt:b(String.raw`For n iid exponential observations with rate $\lambda>0$, density $\lambda e^{-\lambda x}$ on $x\ge0$, compute the score and information.`,String.raw`Với n quan sát mũ iid có tốc độ $\lambda>0$, mật độ $\lambda e^{-\lambda x}$ trên $x\ge0$, tính score và thông tin.`),solution:[b(String.raw`Let $T=\sum_iX_i$. The log likelihood is $n\log\lambda-\lambda T$, so $S_\lambda=n/\lambda-T$.`,String.raw`Đặt $T=\sum_iX_i$. Log likelihood là $n\log\lambda-\lambda T$, nên $S_\lambda=n/\lambda-T$.`),b(String.raw`Each observation has mean $1/\lambda$, hence $\mathbb E T=n/\lambda$ and $\mathbb E S_\lambda=0$.`,String.raw`Mỗi quan sát có trung bình $1/\lambda$, nên $\mathbb E T=n/\lambda$ và $\mathbb E S_\lambda=0$.`),b(String.raw`Each has variance $1/\lambda^2$, giving $I_n(\lambda)=\operatorname{Var}(T)=n/\lambda^2$.`,String.raw`Mỗi biến có phương sai $1/\lambda^2$, nên $I_n(\lambda)=\operatorname{Var}(T)=n/\lambda^2$.`)]},
      {prompt:b(String.raw`For n iid $N(\mu,\sigma^2)$ observations with known $\sigma^2>0$, derive the score for $\mu$ and its information.`,String.raw`Với n quan sát $N(\mu,\sigma^2)$ iid, $\sigma^2>0$ đã biết, suy score theo $\mu$ và thông tin.`),solution:[b(String.raw`The log likelihood, up to a parameter-free constant, is $-\frac1{2\sigma^2}\sum_i(X_i-\mu)^2$.`,String.raw`Log likelihood, bỏ hằng số không phụ thuộc tham số, là $-\frac1{2\sigma^2}\sum_i(X_i-\mu)^2$.`),b(String.raw`Differentiation gives $S_\mu=\sum_i(X_i-\mu)/\sigma^2$, whose mean is zero.`,String.raw`Lấy đạo hàm được $S_\mu=\sum_i(X_i-\mu)/\sigma^2$, có kỳ vọng bằng không.`),b(String.raw`Independence yields $\operatorname{Var}(S_\mu)=n\sigma^2/\sigma^4=n/\sigma^2$, so $I_n(\mu)=n/\sigma^2$.`,String.raw`Độc lập cho $\operatorname{Var}(S_\mu)=n\sigma^2/\sigma^4=n/\sigma^2$, nên $I_n(\mu)=n/\sigma^2$.`)]}
    ],
    reviewNote:`The score and information formulas assume an interior parameter and the usual fixed support of the Bernoulli model. The score is centered, so its variance and second moment agree.`,
    sourceIds:['p-mit18655']
  },

  'm2-w048-e2': {
    title:b('Prove the Cramér–Rao inequality','Chứng minh bất đẳng thức Cramér–Rao'),
    application:b(String.raw`Differentiate the unbiasedness identity to turn its derivative into covariance with the score, then apply Cauchy–Schwarz only after checking both integral interchanges.`,String.raw`Lấy đạo hàm đồng nhất thức không chệch để biến đạo hàm thành hiệp phương sai với score, rồi chỉ dùng Cauchy–Schwarz sau khi kiểm tra hai phép đổi thứ tự tích phân.`),
    formula:b(String.raw`Let $\theta$ lie in an open interval, with densities $f_\theta$ on common parameter-independent support and score $S_\theta=\partial_\theta\log f_\theta$. If $T\in L^2$, $\tau(\theta)=\mathbb E_\theta T$ is differentiable, differentiation may pass under both $\int f_\theta=1$ and $\int T f_\theta$, and $0<I(\theta)=\mathbb E_\theta S_\theta^2<\infty$, then $\mathbb E_\theta S_\theta=0$, $\operatorname{Cov}_\theta(T,S_\theta)=\tau'(\theta)$, and $\operatorname{Var}_\theta(T)\ge[\tau'(\theta)]^2/I(\theta)$.`,String.raw`Cho $\theta$ thuộc khoảng mở, mật độ $f_\theta$ có hỗ trợ chung không phụ thuộc tham số và score $S_\theta=\partial_\theta\log f_\theta$. Nếu $T\in L^2$, $\tau(\theta)=\mathbb E_\theta T$ khả vi, đạo hàm được phép đổi chỗ dưới cả $\int f_\theta=1$ và $\int T f_\theta$, và $0<I(\theta)=\mathbb E_\theta S_\theta^2<\infty$, thì $\mathbb E_\theta S_\theta=0$, $\operatorname{Cov}_\theta(T,S_\theta)=\tau'(\theta)$ và $\operatorname{Var}_\theta(T)\ge[\tau'(\theta)]^2/I(\theta)$.`),
    steps:[b(String.raw`Differentiate normalization under its own integrable domination: $0=\partial_\theta\int f_\theta\,d\nu=\int\partial_\theta f_\theta\,d\nu=\mathbb E_\theta S_\theta$.`,String.raw`Lấy đạo hàm điều kiện chuẩn hóa với hàm trội khả tích riêng: $0=\partial_\theta\int f_\theta\,d\nu=\int\partial_\theta f_\theta\,d\nu=\mathbb E_\theta S_\theta$.`),b(String.raw`Separately differentiate unbiasedness $\tau(\theta)=\int T(x)f_\theta(x)d\nu(x)$, using an integrable dominator for $T(x)\partial_\theta f_\eta(x)$ locally in $\eta$.`,String.raw`Tách riêng, lấy đạo hàm $\tau(\theta)=\int T(x)f_\theta(x)d\nu(x)$, dùng hàm trội khả tích cho $T(x)\partial_\theta f_\eta(x)$ cục bộ theo $\eta$.`),b(String.raw`On the fixed support, $\partial_\theta f_\theta=S_\theta f_\theta$ a.e.; hence $\tau'(\theta)=\mathbb E_\theta[T S_\theta]$.`,String.raw`Trên hỗ trợ cố định, $\partial_\theta f_\theta=S_\theta f_\theta$ h.k.n.; do đó $\tau'(\theta)=\mathbb E_\theta[T S_\theta]$.`),b(String.raw`Since $\mathbb E_\theta S_\theta=0$, this identity is $\operatorname{Cov}_\theta(T,S_\theta)=\tau'(\theta)$.`,String.raw`Vì $\mathbb E_\theta S_\theta=0$, đồng nhất thức này là $\operatorname{Cov}_\theta(T,S_\theta)=\tau'(\theta)$.`),b(String.raw`Cauchy–Schwarz gives $[\tau'(\theta)]^2\le\operatorname{Var}_\theta(T)I(\theta)$; divide by positive finite information to get the bound.`,String.raw`Cauchy–Schwarz cho $[\tau'(\theta)]^2\le\operatorname{Var}_\theta(T)I(\theta)$; chia cho thông tin dương hữu hạn được chặn cần tìm.`)],
    primarySolution:[b(String.raw`A parameter-independent support and valid differentiation of $\int f_\theta=1$ imply $\mathbb E_\theta S_\theta=0$. The normalization step needs an integrable bound for the density derivative near the parameter value.`,String.raw`Hỗ trợ không phụ thuộc tham số và phép lấy đạo hàm hợp lệ của $\int f_\theta=1$ suy ra $\mathbb E_\theta S_\theta=0$. Bước chuẩn hóa cần hàm khả tích trội đạo hàm mật độ gần giá trị tham số.`),b(String.raw`Differentiate $\mathbb E_\theta T=\int T f_\theta\,d\nu=\tau(\theta)$ under a separate estimator-specific domination, obtaining $\tau'(\theta)=\int T\,\partial_\theta f_\theta\,d\nu=\mathbb E_\theta[T S_\theta]$.`,String.raw`Lấy đạo hàm $\mathbb E_\theta T=\int T f_\theta\,d\nu=\tau(\theta)$ với hàm trội riêng cho ước lượng, được $\tau'(\theta)=\int T\,\partial_\theta f_\theta\,d\nu=\mathbb E_\theta[T S_\theta]$.`),b(String.raw`Because the score mean is zero, $\mathbb E[T S_\theta]=\operatorname{Cov}(T,S_\theta)$. This step also requires $T\in L^2$ and finite score information.`,String.raw`Vì score có kỳ vọng không, $\mathbb E[T S_\theta]=\operatorname{Cov}(T,S_\theta)$. Bước này cũng cần $T\in L^2$ và thông tin score hữu hạn.`),b(String.raw`Apply Cauchy–Schwarz: $[\tau'(\theta)]^2\le\operatorname{Var}_\theta(T)\mathbb E_\theta S_\theta^2=\operatorname{Var}_\theta(T)I(\theta)$.`,String.raw`Áp dụng Cauchy–Schwarz: $[\tau'(\theta)]^2\le\operatorname{Var}_\theta(T)\mathbb E_\theta S_\theta^2=\operatorname{Var}_\theta(T)I(\theta)$.`),b(String.raw`With $0<I(\theta)<\infty$, divide to obtain the Cramér–Rao bound. The two differentiation-under-integral justifications are distinct when T is unbounded.`,String.raw`Với $0<I(\theta)<\infty$, chia hai vế để được chặn Cramér–Rao. Hai biện minh đổi đạo hàm qua tích phân là riêng biệt khi T không bị chặn.`)],
    companions:[
      {prompt:b(String.raw`For one Bernoulli$(p)$ observation with $0<p<1$, take $T=X$ to estimate $\tau(p)=p$. Compute the score covariance and information and verify the CR inequality.`,String.raw`Với một quan sát Bernoulli$(p)$, $0<p<1$, lấy $T=X$ để ước lượng $\tau(p)=p$. Tính hiệp phương sai score và thông tin, kiểm tra bất đẳng thức CR.`),solution:[b(String.raw`The fixed support is $\{0,1\}$ and $S_p=(X-p)/[p(1-p)]$, so $\mathbb E_pS_p=0$.`,String.raw`Hỗ trợ cố định là $\{0,1\}$ và $S_p=(X-p)/[p(1-p)]$, nên $\mathbb E_pS_p=0$.`),b(String.raw`The covariance is $\operatorname{Cov}(X,S_p)=\mathbb E[(X-p)^2]/[p(1-p)]=1=\tau'(p)$.`,String.raw`Hiệp phương sai là $\operatorname{Cov}(X,S_p)=\mathbb E[(X-p)^2]/[p(1-p)]=1=\tau'(p)$.`),b(String.raw`Information is $I(p)=\mathbb E S_p^2=1/[p(1-p)]$, so CR says $\operatorname{Var}(X)\ge p(1-p)$.`,String.raw`Thông tin là $I(p)=\mathbb E S_p^2=1/[p(1-p)]$, nên CR cho $\operatorname{Var}(X)\ge p(1-p)$.`),b(String.raw`In fact $\operatorname{Var}(X)=p(1-p)$, so equality holds; finite support makes the differentiations direct finite sums.`,String.raw`Thực tế $\operatorname{Var}(X)=p(1-p)$ nên có đẳng thức; hỗ trợ hữu hạn khiến phép lấy đạo hàm là tổng hữu hạn trực tiếp.`)]},
      {prompt:b(String.raw`For n iid $N(\mu,4)$ observations, verify the score identity $\operatorname{Cov}(\bar X,S_\mu)=1$ and the CR lower bound for estimating $\mu$.`,String.raw`Với n quan sát $N(\mu,4)$ iid, kiểm tra đồng nhất thức score $\operatorname{Cov}(\bar X,S_\mu)=1$ và chặn dưới CR khi ước lượng $\mu$.`),solution:[b(String.raw`The common support is $\mathbb R^n$ and $S_\mu=\sum_i(X_i-\mu)/4$. Normal tails dominate the density derivatives times $\bar X$ locally in $\mu$, so differentiation is justified.`,String.raw`Hỗ trợ chung là $\mathbb R^n$ và $S_\mu=\sum_i(X_i-\mu)/4$. Đuôi chuẩn trội đạo hàm mật độ nhân $\bar X$ cục bộ theo $\mu$, nên phép đạo hàm hợp lệ.`),b(String.raw`Since $\bar X-\mu=(1/n)\sum_i(X_i-\mu)$, $\operatorname{Cov}(\bar X,S_\mu)=\operatorname{Var}(\sum_i(X_i-\mu))/(4n)=4n/(4n)=1$.`,String.raw`Vì $\bar X-\mu=(1/n)\sum_i(X_i-\mu)$, $\operatorname{Cov}(\bar X,S_\mu)=\operatorname{Var}(\sum_i(X_i-\mu))/(4n)=4n/(4n)=1$.`),b(String.raw`The information is $I(\mu)=n/4$, so the CR bound is $4/n$.`,String.raw`Thông tin là $I(\mu)=n/4$, nên chặn CR là $4/n$.`),b(String.raw`The sample-mean variance is $4/n$, exactly the bound; the score and centered sample mean are proportional.`,String.raw`Phương sai trung bình mẫu là $4/n$, đúng bằng chặn; score tỷ lệ với trung bình mẫu đã tâm hóa.`)]},
      {prompt:b(String.raw`For n iid Poisson$(\lambda)$ observations, $\lambda>0$, verify $\operatorname{Cov}(T/n,S_\lambda)=1$ for $T=\sum_iX_i$, and state the CR bound for estimating $\lambda$.`,String.raw`Với n quan sát Poisson$(\lambda)$ iid, $\lambda>0$, kiểm tra $\operatorname{Cov}(T/n,S_\lambda)=1$ với $T=\sum_iX_i$, rồi nêu chặn CR khi ước lượng $\lambda$.`),solution:[b(String.raw`The support $\mathbb N_0^n$ is fixed, $S_\lambda=T/\lambda-n$, and Poisson moments ensure the density-series derivatives are integrable.`,String.raw`Hỗ trợ $\mathbb N_0^n$ cố định, $S_\lambda=T/\lambda-n$, và moment Poisson bảo đảm các đạo hàm chuỗi mật độ khả tích.`),b(String.raw`Because $\operatorname{Var}(T)=n\lambda$, $\operatorname{Cov}(T/n,S_\lambda)=\operatorname{Cov}(T/n,T/\lambda)=n\lambda/(n\lambda)=1$.`,String.raw`Vì $\operatorname{Var}(T)=n\lambda$, $\operatorname{Cov}(T/n,S_\lambda)=\operatorname{Cov}(T/n,T/\lambda)=n\lambda/(n\lambda)=1$.`),b(String.raw`The information is $I(\lambda)=n/\lambda$, so any unbiased finite-variance estimator of $\lambda$ has variance at least $\lambda/n$.`,String.raw`Thông tin là $I(\lambda)=n/\lambda$, nên mọi ước lượng không chệch phương sai hữu hạn của $\lambda$ có phương sai ít nhất $\lambda/n$.`),b(String.raw`The sample mean has variance $\lambda/n$, attaining the bound.`,String.raw`Trung bình mẫu có phương sai $\lambda/n$, đạt chặn.`)]}
    ],
    reviewNote:`The normalization derivative and estimator-mean derivative require separate domination arguments; common support alone is not enough, especially for unbounded T. Cauchy–Schwarz additionally needs finite estimator variance and positive finite score information.`,
    sourceIds:['p-mit18655']
  },

  'm2-w048-e3': {
    title:b('Check equality for the sample proportion','Kiểm tra đẳng thức cho tỷ lệ mẫu'),
    application:b(String.raw`Compare the sample-proportion variance with the information bound, then verify the equality condition by expressing its centered form as a multiple of the score.`,String.raw`So sánh phương sai tỷ lệ mẫu với chặn từ thông tin, rồi kiểm tra điều kiện đẳng thức bằng cách viết dạng tâm hóa thành bội của score.`),
    formula:b(String.raw`For iid $\operatorname{Bernoulli}(p)$ with $0<p<1$, $S=\sum_iX_i$, score $S_p=(S-np)/[p(1-p)]$, and $I_n(p)=n/[p(1-p)]$. The unbiased estimator $\hat p=S/n$ has $\operatorname{Var}(\hat p)=p(1-p)/n=1/I_n(p)$ and $\hat p-p=[p(1-p)/n]S_p$.`,String.raw`Với $\operatorname{Bernoulli}(p)$ iid, $0<p<1$, $S=\sum_iX_i$, score $S_p=(S-np)/[p(1-p)]$, $I_n(p)=n/[p(1-p)]$. Ước lượng không chệch $\hat p=S/n$ có $\operatorname{Var}(\hat p)=p(1-p)/n=1/I_n(p)$ và $\hat p-p=[p(1-p)/n]S_p$.`),
    steps:[b(String.raw`The sample proportion is unbiased and its variance is $\operatorname{Var}(S/n)=np(1-p)/n^2=p(1-p)/n$.`,String.raw`Tỷ lệ mẫu không chệch và có phương sai $\operatorname{Var}(S/n)=np(1-p)/n^2=p(1-p)/n$.`),b(String.raw`For target $\tau(p)=p$, the derivative is $\tau'(p)=1$, while information is $I_n(p)=n/[p(1-p)]$.`,String.raw`Với đại lượng đích $\tau(p)=p$, đạo hàm là $\tau'(p)=1$, còn thông tin là $I_n(p)=n/[p(1-p)]$.`),b(String.raw`The Cramér–Rao lower bound is $[\tau'(p)]^2/I_n(p)=p(1-p)/n$, matching the actual variance.`,String.raw`Chặn dưới Cramér–Rao là $[\tau'(p)]^2/I_n(p)=p(1-p)/n$, trùng phương sai thực tế.`),b(String.raw`Moreover, $\hat p-p=(S-np)/n=[p(1-p)/n]S_p$, so the centered estimator is proportional to the score, the equality condition in Cauchy–Schwarz.`,String.raw`Hơn nữa, $\hat p-p=(S-np)/n=[p(1-p)/n]S_p$, nên ước lượng tâm hóa tỷ lệ với score, là điều kiện đẳng thức Cauchy–Schwarz.`)],
    primarySolution:[b(String.raw`Since $S\sim\operatorname{Binomial}(n,p)$, $\operatorname{Var}(S/n)=np(1-p)/n^2=p(1-p)/n$.`,String.raw`Vì $S\sim\operatorname{Binomial}(n,p)$, $\operatorname{Var}(S/n)=np(1-p)/n^2=p(1-p)/n$.`),b(String.raw`The target is $\tau(p)=p$, so $\tau'(p)=1$; the score calculation gives $I_n(p)=n/[p(1-p)]$.`,String.raw`Đại lượng đích là $\tau(p)=p$, nên $\tau'(p)=1$; phép tính score cho $I_n(p)=n/[p(1-p)]$.`),b(String.raw`Consequently the CR bound is $1/I_n(p)=p(1-p)/n$, exactly the sample-proportion variance.`,String.raw`Do đó chặn CR là $1/I_n(p)=p(1-p)/n$, đúng bằng phương sai tỷ lệ mẫu.`),b(String.raw`The centered estimator satisfies $S/n-p=(p(1-p)/n)S_p$, attaining the Cauchy–Schwarz equality condition.`,String.raw`Ước lượng tâm hóa thỏa $S/n-p=(p(1-p)/n)S_p$, đạt điều kiện đẳng thức Cauchy–Schwarz.`)],
    companions:[
      {prompt:b(String.raw`For n iid Poisson$(\lambda)$ counts, verify that $\bar X=T/n$ attains the CR bound for estimating $\lambda$.`,String.raw`Với n số đếm Poisson$(\lambda)$ iid, kiểm tra $\bar X=T/n$ đạt chặn CR khi ước lượng $\lambda$.`),solution:[b(String.raw`The estimator is unbiased and has variance $\lambda/n$ because $T\sim\operatorname{Poisson}(n\lambda)$.`,String.raw`Ước lượng không chệch và có phương sai $\lambda/n$ vì $T\sim\operatorname{Poisson}(n\lambda)$.`),b(String.raw`The score information is $I_n(\lambda)=n/\lambda$, so the CR bound for target $\tau(\lambda)=\lambda$ is $1/I_n(\lambda)=\lambda/n$.`,String.raw`Thông tin score là $I_n(\lambda)=n/\lambda$, nên chặn CR cho $\tau(\lambda)=\lambda$ là $1/I_n(\lambda)=\lambda/n$.`),b(String.raw`The centered mean is $\bar X-\lambda=(T-n\lambda)/n=(\lambda/n)S_\lambda$, so equality also follows from proportionality to the score.`,String.raw`Trung bình tâm hóa là $\bar X-\lambda=(T-n\lambda)/n=(\lambda/n)S_\lambda$, nên đẳng thức cũng theo tính tỷ lệ với score.`)]},
      {prompt:b(String.raw`For n iid $N(\mu,\sigma^2)$ observations with known $\sigma^2$, compare the variance of $\bar X$ with its CR bound for $\mu$.`,String.raw`Với n quan sát $N(\mu,\sigma^2)$ iid, $\sigma^2$ đã biết, so phương sai $\bar X$ với chặn CR cho $\mu$.`),solution:[b(String.raw`The sample mean is unbiased and has variance $\sigma^2/n$.`,String.raw`Trung bình mẫu không chệch và có phương sai $\sigma^2/n$.`),b(String.raw`The information for $\mu$ is $I_n(\mu)=n/\sigma^2$, giving bound $1/I_n(\mu)=\sigma^2/n$.`,String.raw`Thông tin cho $\mu$ là $I_n(\mu)=n/\sigma^2$, cho chặn $1/I_n(\mu)=\sigma^2/n$.`),b(String.raw`The score is $\sum_i(X_i-\mu)/\sigma^2$, and $\bar X-\mu=(\sigma^2/n)S_\mu$; hence the bound is attained.`,String.raw`Score là $\sum_i(X_i-\mu)/\sigma^2$, còn $\bar X-\mu=(\sigma^2/n)S_\mu$; vì thế đạt chặn.`)]},
      {prompt:b(String.raw`For n iid exponential observations with rate $\lambda>0$, use $\bar X$ to estimate the mean $\tau(\lambda)=1/\lambda$. Check equality in the CR bound.`,String.raw`Với n quan sát mũ iid có tốc độ $\lambda>0$, dùng $\bar X$ ước lượng trung bình $\tau(\lambda)=1/\lambda$. Kiểm tra đẳng thức cận CR.`),solution:[b(String.raw`Each observation has mean $1/\lambda$ and variance $1/\lambda^2$, so $\bar X$ is unbiased with variance $1/(n\lambda^2)$.`,String.raw`Mỗi quan sát có trung bình $1/\lambda$ và phương sai $1/\lambda^2$, nên $\bar X$ không chệch với phương sai $1/(n\lambda^2)$.`),b(String.raw`The rate information is $I_n(\lambda)=n/\lambda^2$, while $\tau'(\lambda)=-1/\lambda^2$. The CR bound is $(1/\lambda^4)/(n/\lambda^2)=1/(n\lambda^2)$.`,String.raw`Thông tin theo tốc độ là $I_n(\lambda)=n/\lambda^2$, còn $\tau'(\lambda)=-1/\lambda^2$. Chặn CR là $(1/\lambda^4)/(n/\lambda^2)=1/(n\lambda^2)$.`),b(String.raw`The score is $S_\lambda=n/\lambda-\sum_iX_i$, and $\bar X-1/\lambda=-S_\lambda/n$, establishing the equality condition.`,String.raw`Score là $S_\lambda=n/\lambda-\sum_iX_i$, còn $\bar X-1/\lambda=-S_\lambda/n$, xác lập điều kiện đẳng thức.`)]}
    ],
    reviewNote:`The CR comparisons use unbiased estimators and regular fixed-support models. Equality holds because each centered estimator is a constant multiple of its score, not merely because the numeric variances happen to match.`,
    sourceIds:['p-mit18655']
  },

  'm2-w048-e4': {
    title:b('Counterexample: parameter-dependent support','Phản ví dụ: hỗ trợ phụ thuộc tham số'),
    application:b(String.raw`For a uniform endpoint model, maximize the likelihood on its feasible parameter set, compute the maximum's law, and identify the moving support that invalidates the regular score argument.`,String.raw`Với mô hình đầu mút đều, cực đại hóa likelihood trên miền tham số khả thi, tính luật của giá trị cực đại và xác định hỗ trợ chuyển động làm lập luận score chính quy mất hiệu lực.`),
    formula:b(String.raw`For iid $X_i\sim\operatorname{Uniform}(0,\theta)$, $\theta>0$, use the specified density $f_\theta(x)=\theta^{-1}1_{[0,\theta]}(x)$, including the endpoint. For $M=X_{(n)}=\max_iX_i>0$, $L(\theta)=\theta^{-n}1_{\{\theta\ge M\}}$, so $\hat\theta_{\rm MLE}=M$. Also $F_M(x)=(x/\theta)^n$ on $[0,\theta]$, $\mathbb E M^k=n\theta^k/(n+k)$ for $k>0$, and $\operatorname{Var}(M)=n\theta^2/[(n+1)^2(n+2)]$.`,String.raw`Với $X_i\sim\operatorname{Uniform}(0,\theta)$ iid, $\theta>0$, dùng mật độ đã quy định $f_\theta(x)=\theta^{-1}1_{[0,\theta]}(x)$, kể cả đầu mút. Với $M=X_{(n)}=\max_iX_i>0$, $L(\theta)=\theta^{-n}1_{\{\theta\ge M\}}$, nên $\hat\theta_{\rm MLE}=M$. Đồng thời $F_M(x)=(x/\theta)^n$ trên $[0,\theta]$, $\mathbb E M^k=n\theta^k/(n+k)$ với $k>0$, và $\operatorname{Var}(M)=n\theta^2/[(n+1)^2(n+2)]$.`),
    steps:[b(String.raw`For an observed sample with $M>0$, the likelihood is zero for $\theta<M$ and equals $\theta^{-n}$ for $\theta\ge M$.`,String.raw`Với mẫu quan sát có $M>0$, likelihood bằng không khi $\theta<M$ và bằng $\theta^{-n}$ khi $\theta\ge M$.`),b(String.raw`On the feasible set $\theta\ge M$, $\theta^{-n}$ decreases in theta, so the closed-endpoint convention attains the maximum at $\hat\theta=M$.`,String.raw`Trên miền khả thi $\theta\ge M$, $\theta^{-n}$ giảm theo theta, nên quy ước đầu mút đóng đạt cực đại tại $\hat\theta=M$.`),b(String.raw`Independence yields $P(M\le x)=\prod_iP(X_i\le x)=(x/\theta)^n$ for $0\le x\le\theta$, with density $n x^{n-1}/\theta^n$.`,String.raw`Độc lập cho $P(M\le x)=\prod_iP(X_i\le x)=(x/\theta)^n$ khi $0\le x\le\theta$, với mật độ $n x^{n-1}/\theta^n$.`),b(String.raw`Integrating $x^k$ gives $\mathbb E M^k=\int_0^\theta x^k n x^{n-1}/\theta^n\,dx=n\theta^k/(n+k)$.`,String.raw`Tích phân $x^k$ cho $\mathbb E M^k=\int_0^\theta x^k n x^{n-1}/\theta^n\,dx=n\theta^k/(n+k)$.`),b(String.raw`Subtracting $(n\theta/(n+1))^2$ from $n\theta^2/(n+2)$ gives the stated variance. The support moves with theta, so the usual score identity fails.`,String.raw`Lấy $n\theta^2/(n+2)$ trừ $(n\theta/(n+1))^2$ được phương sai đã nêu. Hỗ trợ thay đổi theo theta nên đồng nhất thức score thông thường thất bại.`)],
    primarySolution:[b(String.raw`Under the explicitly specified density $\theta^{-1}1_{[0,\theta]}(x)$, the sample likelihood is $L(\theta)=\theta^{-n}1_{\{\theta\ge M\}}$.`,String.raw`Theo mật độ được nêu rõ $\theta^{-1}1_{[0,\theta]}(x)$, likelihood mẫu là $L(\theta)=\theta^{-n}1_{\{\theta\ge M\}}$.`),b(String.raw`For the a.s. event $M>0$, the feasible set is $[M,\infty)$ and $\theta^{-n}$ decreases there; because the endpoint is included, the MLE is attained at $\hat\theta=M$.`,String.raw`Trên biến cố h.c. $M>0$, miền khả thi là $[M,\infty)$ và $\theta^{-n}$ giảm tại đó; vì gồm đầu mút, MLE đạt tại $\hat\theta=M$.`),b(String.raw`Independence gives $F_M(x)=(x/\theta)^n$ for $0\le x\le\theta$, hence $f_M(x)=n x^{n-1}/\theta^n$ on that interval.`,String.raw`Độc lập cho $F_M(x)=(x/\theta)^n$ với $0\le x\le\theta$, nên $f_M(x)=n x^{n-1}/\theta^n$ trên khoảng đó.`),b(String.raw`For $k>0$, $\mathbb E M^k=(n/\theta^n)\int_0^\theta x^{n+k-1}dx=n\theta^k/(n+k)$.`,String.raw`Với $k>0$, $\mathbb E M^k=(n/\theta^n)\int_0^\theta x^{n+k-1}dx=n\theta^k/(n+k)$.`),b(String.raw`Thus $\operatorname{Var}(M)=n\theta^2/(n+2)-n^2\theta^2/(n+1)^2=n\theta^2/[(n+1)^2(n+2)]$.`,String.raw`Do đó $\operatorname{Var}(M)=n\theta^2/(n+2)-n^2\theta^2/(n+1)^2=n\theta^2/[(n+1)^2(n+2)]$.`),b(String.raw`For a fixed interior sample point, the log-likelihood score is $-n/\theta$, whose expectation is not zero. The moving support invalidates differentiation of the normalization and the regular Cramér–Rao score identity.`,String.raw`Với điểm mẫu cố định bên trong, score log-likelihood là $-n/\theta$, có kỳ vọng khác không. Hỗ trợ chuyển động làm phép đạo hàm chuẩn hóa và đồng nhất thức score Cramér–Rao chính quy mất hiệu lực.`)],
    companions:[
      {prompt:b(String.raw`For iid $X_i\sim\operatorname{Uniform}(-\theta,\theta)$, $\theta>0$, use endpoint-inclusive density $(2\theta)^{-1}1_{[-\theta,\theta]}$. Find the MLE and variance of $M=\max_i|X_i|$.`,String.raw`Với $X_i\sim\operatorname{Uniform}(-\theta,\theta)$ iid, $\theta>0$, dùng mật độ gồm đầu mút $(2\theta)^{-1}1_{[-\theta,\theta]}$. Tìm MLE và phương sai của $M=\max_i|X_i|$.`),solution:[b(String.raw`The likelihood is $(2\theta)^{-n}1_{\{\theta\ge M\}}$; it decreases on $\theta\ge M$, so the included endpoint gives $\hat\theta=M$.`,String.raw`Likelihood là $(2\theta)^{-n}1_{\{\theta\ge M\}}$; nó giảm trên $\theta\ge M$, nên đầu mút được tính cho $\hat\theta=M$.`),b(String.raw`For one observation, $|X_i|$ is Uniform$(0,\theta)$; hence $P(M\le x)=(x/\theta)^n$ for $0\le x\le\theta$.`,String.raw`Với một quan sát, $|X_i|$ đều trên $(0,\theta)$; do đó $P(M\le x)=(x/\theta)^n$ với $0\le x\le\theta$.`),b(String.raw`The same moment integration gives $E[M]=n\theta/(n+1)$ and $E[M^2]=n\theta^2/(n+2)$.`,String.raw`Tích phân moment tương tự cho $E[M]=n\theta/(n+1)$ và $E[M^2]=n\theta^2/(n+2)$.`),b(String.raw`Therefore $\operatorname{Var}(M)=n\theta^2/[(n+1)^2(n+2)]$, with support again depending on theta.`,String.raw`Vì vậy $\operatorname{Var}(M)=n\theta^2/[(n+1)^2(n+2)]$, và hỗ trợ vẫn phụ thuộc theta.`)]},
      {prompt:b(String.raw`For the endpoint-inclusive model $X_i\sim\operatorname{Uniform}(\theta,\theta+1)$, $\theta>0$, an observed sample is $(1.2,1.6)$. Find the full MLE set.`,String.raw`Với mô hình gồm đầu mút $X_i\sim\operatorname{Uniform}(\theta,\theta+1)$, $\theta>0$, mẫu quan sát là $(1.2,1.6)$. Tìm toàn bộ tập MLE.`),solution:[b(String.raw`The density of each observation is 1 when $\theta\le x_i\le\theta+1$ and zero otherwise.`,String.raw`Mật độ mỗi quan sát bằng 1 khi $\theta\le x_i\le\theta+1$ và bằng không nếu không.`),b(String.raw`For both data values to lie in the support, require $\theta\le\min(1.2,1.6)=1.2$ and $\theta+1\ge\max(1.2,1.6)=1.6$, so $\theta\ge.6$.`,String.raw`Để cả hai số liệu thuộc hỗ trợ, cần $\theta\le\min(1.2,1.6)=1.2$ và $\theta+1\ge\max(1.2,1.6)=1.6$, nên $\theta\ge.6$.`),b(String.raw`Thus $L(\theta)=1$ for every $\theta\in[.6,1.2]$ and zero outside; every value in that interval is an MLE.`,String.raw`Vậy $L(\theta)=1$ với mọi $\theta\in[.6,1.2]$ và bằng không ngoài khoảng; mọi giá trị trong khoảng đều là MLE.`)]},
      {prompt:b(String.raw`For iid observations with Pareto density $f_\theta(x)=\theta x^{-2}1_{[\theta,\infty)}(x)$, $\theta>0$, and sample $(2,3,5)$, find the MLE under the stated endpoint convention.`,String.raw`Với các quan sát iid có mật độ Pareto $f_\theta(x)=\theta x^{-2}1_{[\theta,\infty)}(x)$, $\theta>0$, và mẫu $(2,3,5)$, tìm MLE theo quy ước đầu mút đã nêu.`),solution:[b(String.raw`The density is normalized since $\int_\theta^\infty\theta x^{-2}dx=1$.`,String.raw`Mật độ được chuẩn hóa vì $\int_\theta^\infty\theta x^{-2}dx=1$.`),b(String.raw`For data $(2,3,5)$, the likelihood is $\theta^3(2^{-2}3^{-2}5^{-2})1_{\{0<\theta\le2\}}$.`,String.raw`Với dữ liệu $(2,3,5)$, likelihood là $\theta^3(2^{-2}3^{-2}5^{-2})1_{\{0<\theta\le2\}}$.`),b(String.raw`It increases with theta on the feasible interval, so its maximum is attained at the included endpoint $\hat\theta=\min_iX_i=2$.`,String.raw`Likelihood tăng theo theta trên khoảng khả thi, nên cực đại đạt tại đầu mút được tính $\hat\theta=\min_iX_i=2$.`)]}
    ],
    reviewNote:`The specified endpoint-inclusive density makes the Uniform(0,theta) likelihood attain its maximum at the sample maximum. The moving support breaks the zero-mean score identity; the unbiased rescaling $(n+1)M/n$ has variance $\theta^2/[n(n+2)]<\theta^2/n^2$, exposing why the formal regular CR bound cannot be used.`,
    sourceIds:['p-mit18655']
  },

  'm2-w048-e5': {
    title:b('Transfer: score identities under reparameterization','Chuyển giao: đồng nhất thức score khi đổi tham số'),
    application:b(String.raw`Apply the chain rule to transform the score, square its local scale factor to transform Fisher information, and then state the bound for the new target parameter.`,String.raw`Dùng quy tắc dây chuyền để biến đổi score, bình phương hệ số cục bộ để biến đổi thông tin Fisher, rồi nêu chặn cho tham số đích mới.`),
    formula:b(String.raw`Let $\eta=g(\theta)$ with $g\in C^1$ near $\theta$ and $g'(\theta)\ne0$, so the inverse is locally differentiable. Then $S_\eta=S_\theta(d\theta/d\eta)$ and $I_\eta=I_\theta(d\theta/d\eta)^2=I_\theta/[g'(\theta)]^2$. Under retained regularity and an unbiased estimator $\hat\eta$, $\operatorname{Var}(\hat\eta)\ge1/I_\eta$.`,String.raw`Cho $\eta=g(\theta)$ với $g\in C^1$ gần $\theta$, $g'(\theta)\ne0$, nên hàm ngược khả vi cục bộ. Khi đó $S_\eta=S_\theta(d\theta/d\eta)$ và $I_\eta=I_\theta(d\theta/d\eta)^2=I_\theta/[g'(\theta)]^2$. Nếu tính chính quy vẫn giữ và $\hat\eta$ không chệch, $\operatorname{Var}(\hat\eta)\ge1/I_\eta$.`),
    steps:[b(String.raw`The inverse function theorem gives a local map $\theta=\theta(\eta)$ with $d\theta/d\eta=1/g'(\theta)$.`,String.raw`Định lý hàm ngược cho ánh xạ cục bộ $\theta=\theta(\eta)$ với $d\theta/d\eta=1/g'(\theta)$.`),b(String.raw`For the same likelihood written in the new coordinate, $S_\eta=\partial_\eta\ell=(\partial_\theta\ell)(d\theta/d\eta)=S_\theta(d\theta/d\eta)$.`,String.raw`Với cùng likelihood viết theo tọa độ mới, $S_\eta=\partial_\eta\ell=(\partial_\theta\ell)(d\theta/d\eta)=S_\theta(d\theta/d\eta)$.`),b(String.raw`Taking the score's second moment multiplies information by the square: $I_\eta=I_\theta(d\theta/d\eta)^2$.`,String.raw`Lấy moment bậc hai của score nhân thông tin với bình phương hệ số: $I_\eta=I_\theta(d\theta/d\eta)^2$.`),b(String.raw`For an unbiased estimator of target $\tau(\eta)=\eta$, the derivative is 1, so CR gives variance at least $1/I_\eta$.`,String.raw`Với ước lượng không chệch cho đại lượng đích $\tau(\eta)=\eta$, đạo hàm bằng 1 nên CR cho phương sai ít nhất $1/I_\eta$.`),b(String.raw`The transformed density must still satisfy the common-support and differentiation conditions; a smooth coordinate change alone does not repair a nonregular model.`,String.raw`Mật độ sau đổi biến vẫn phải thỏa hỗ trợ chung và điều kiện lấy đạo hàm; phép đổi tọa độ trơn tự nó không sửa được mô hình không chính quy.`)],
    primarySolution:[b(String.raw`Because $g'(\theta)\ne0$, the inverse function theorem gives $d\theta/d\eta=1/g'(\theta)$.`,String.raw`Vì $g'(\theta)\ne0$, định lý hàm ngược cho $d\theta/d\eta=1/g'(\theta)$.`),b(String.raw`The chain rule yields $S_\eta=(\partial_\theta\ell)(d\theta/d\eta)=S_\theta(d\theta/d\eta)$.`,String.raw`Quy tắc dây chuyền cho $S_\eta=(\partial_\theta\ell)(d\theta/d\eta)=S_\theta(d\theta/d\eta)$.`),b(String.raw`Thus $I_\eta=\mathbb E[S_\eta^2]=I_\theta(d\theta/d\eta)^2=I_\theta/[g'(\theta)]^2$.`,String.raw`Do đó $I_\eta=\mathbb E[S_\eta^2]=I_\theta(d\theta/d\eta)^2=I_\theta/[g'(\theta)]^2$.`),b(String.raw`For an unbiased estimator of $\eta$, the target derivative with respect to eta is 1; the CR lower bound is $\operatorname{Var}(\hat\eta)\ge1/I_\eta$.`,String.raw`Với ước lượng không chệch của $\eta$, đạo hàm đại lượng đích theo eta bằng 1; chặn dưới CR là $\operatorname{Var}(\hat\eta)\ge1/I_\eta$.`),b(String.raw`This bound assumes the reparameterized family remains regular and $0<I_\eta<\infty$.`,String.raw`Chặn này giả sử họ sau đổi tham số vẫn chính quy và $0<I_\eta<\infty$.`)],
    companions:[
      {prompt:b(String.raw`For n iid Poisson$(\lambda)$ observations, set $\eta=\log\lambda$. Find the transformed score and information, then state the CR bound for any unbiased estimator of eta.`,String.raw`Với n quan sát Poisson$(\lambda)$ iid, đặt $\eta=\log\lambda$. Tìm score và thông tin sau đổi tham số, rồi nêu chặn CR cho mọi ước lượng eta không chệch.`),solution:[b(String.raw`Since $\lambda=e^\eta$, $d\lambda/d\eta=\lambda$. The original score is $S_\lambda=T/\lambda-n$.`,String.raw`Vì $\lambda=e^\eta$, $d\lambda/d\eta=\lambda$. Score ban đầu là $S_\lambda=T/\lambda-n$.`),b(String.raw`The chain rule gives $S_\eta=\lambda S_\lambda=T-n\lambda$, which has mean zero.`,String.raw`Quy tắc dây chuyền cho $S_\eta=\lambda S_\lambda=T-n\lambda$, có kỳ vọng bằng không.`),b(String.raw`Information becomes $I_\eta=I_\lambda\lambda^2=(n/\lambda)\lambda^2=n\lambda$.`,String.raw`Thông tin thành $I_\eta=I_\lambda\lambda^2=(n/\lambda)\lambda^2=n\lambda$.`),b(String.raw`If an unbiased estimator of $\eta$ exists in the considered class, its variance is at least $1/(n\lambda)$.`,String.raw`Nếu có ước lượng $\eta$ không chệch trong lớp đang xét, phương sai của nó ít nhất $1/(n\lambda)$.`)]},
      {prompt:b(String.raw`For n iid Bernoulli$(p)$ observations, use the logit coordinate $\eta=\log[p/(1-p)]$. Compute $dp/d\eta$, the transformed score and information, and the CR bound for an unbiased eta estimator.`,String.raw`Với n quan sát Bernoulli$(p)$ iid, dùng tọa độ logit $\eta=\log[p/(1-p)]$. Tính $dp/d\eta$, score và thông tin sau đổi tham số, cùng chặn CR cho ước lượng eta không chệch.`),solution:[b(String.raw`The inverse map is $p=e^\eta/(1+e^\eta)$, so $dp/d\eta=p(1-p)$.`,String.raw`Hàm ngược là $p=e^\eta/(1+e^\eta)$, nên $dp/d\eta=p(1-p)$.`),b(String.raw`Multiplying $S_p=(T-np)/[p(1-p)]$ by $dp/d\eta$ gives $S_\eta=T-np$.`,String.raw`Nhân $S_p=(T-np)/[p(1-p)]$ với $dp/d\eta$ được $S_\eta=T-np$.`),b(String.raw`Hence $I_\eta=I_p[p(1-p)]^2=[n/(p(1-p))][p(1-p)]^2=np(1-p)$.`,String.raw`Vậy $I_\eta=I_p[p(1-p)]^2=[n/(p(1-p))][p(1-p)]^2=np(1-p)$.`),b(String.raw`The CR variance bound for an unbiased estimator of logit p is $1/[np(1-p)]$, assuming the regular interior model.`,String.raw`Chặn phương sai CR cho ước lượng không chệch của logit p là $1/[np(1-p)]$, giả sử mô hình nội tại chính quy.`)]},
      {prompt:b(String.raw`For n iid $N(\mu,\sigma^2)$ observations with known $\sigma^2$, let $\eta=e^\mu$. Find the transformed information and CR lower bound for unbiased estimation of eta.`,String.raw`Với n quan sát $N(\mu,\sigma^2)$ iid, $\sigma^2$ đã biết, đặt $\eta=e^\mu$. Tìm thông tin sau đổi tham số và chặn dưới CR cho ước lượng eta không chệch.`),solution:[b(String.raw`The inverse is $\mu=\log\eta$, so $d\mu/d\eta=1/\eta$.`,String.raw`Hàm ngược là $\mu=\log\eta$, nên $d\mu/d\eta=1/\eta$.`),b(String.raw`The original mean information is $I_\mu=n/\sigma^2$; therefore $I_\eta=I_\mu/\eta^2=n/(\sigma^2\eta^2)$.`,String.raw`Thông tin trung bình ban đầu là $I_\mu=n/\sigma^2$; do đó $I_\eta=I_\mu/\eta^2=n/(\sigma^2\eta^2)$.`),b(String.raw`An unbiased estimator of $\eta$ has CR variance bound $1/I_\eta=\sigma^2\eta^2/n$.`,String.raw`Ước lượng không chệch của $\eta$ có chặn phương sai CR $1/I_\eta=\sigma^2\eta^2/n$.`),b(String.raw`The coordinate change is locally smooth with nonzero derivative and the normal model retains fixed support, so regularity is preserved.`,String.raw`Phép đổi tọa độ trơn cục bộ có đạo hàm khác không và mô hình chuẩn vẫn có hỗ trợ cố định, nên tính chính quy được giữ.`)]}
    ],
    reviewNote:`The information transformation squares the inverse-map derivative. The CR bound is for an unbiased estimator of eta and presumes the reparameterized family retains the regularity hypotheses.`,
    sourceIds:['p-mit18655']
  },

};
export default reviewed;
